window.JASTROW_CHUNKS[7]={"2800":{"h":"אפרדוכסוס","r":"A02800","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אפדכסוס</span></div>","alt":[]},"2801":{"h":"אֶפְרָה","r":"A02801","html":"<div class=\"sense\"><b>1)</b> <i>meadow</i>, v. <a href=\"#\" data-headword=\"אֲפַר\">אֲפַר</a>; </div><div class=\"sense\"><b>2)</b> <i>ashes</i>, v. <a href=\"#\" data-headword=\"אֶפְרָא II\"><span dir=\"rtl\">אֶפְרָא</span> II</a>.</div>","alt":[]},"2802":{"h":"אפרהנג","r":"A02802","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פַּרְהַנְגְּ\">פרהנג</a>, <a href=\"#\" data-headword=\"פַּרְהַנְגַּרְיָא\"><a href=\"#\" data-headword=\"פַּרְהַנְגַּרְיָא\">פַּרְהַנְגַּרְיָא</a>.</a></div>","alt":[]},"2803":{"h":"אַפְרוֹדִיטֵי","r":"A02803","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Ἀφροδίτη) <i>Aphrodite</i>, a Greek goddess (Venus). <span class=\"citation\">Ab. Zar. III, 4</span> <span dir=\"rtl\">מרחץ של א׳</span> a bath where A. has a statue. Ib. we do not say, the bath has been built <span dir=\"rtl\">נוי לא׳ וכ׳</span> as an ornament of A., but we say, A. is an ornamental attachment to the bath. <span class=\"citation\">Y. Shebi. VIII, end 38ᵇ</span> <span dir=\"rtl\">מזלפין להדא א׳</span> squirting water (as a libation) to A.</div>","alt":[]},"2804":{"h":"אפרוודין","r":"A02804","html":"<div class=\"sense\">, read:</div>","alt":[]},"2805":{"h":"אִפַּרְוָורִין","r":"A02805","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\">, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"אִיפַּרְוָון\">אִיפַּרְוָון</a>) <span dir=\"rtl\">אִפְּרוֹרְוָן</span></span> f. pl. (v. <a href=\"#\" data-headword=\"פַּרְוָר\">פַּרְוָר</a>, <a href=\"#\" data-headword=\"פַּרְבָּר\">פַּרְבָּר</a>, <a href=\"#\" data-headword=\"פַּרְוָורָא\">פַּרְוָורָא</a>, <a href=\"#\" data-headword=\"פַּרְוִילָא\"><a href=\"#\" data-headword=\"פַּרְוִילָא\">פַּרְוִילָא</a>)</a><i>those appointed over the outworks of a fortress, runners</i>. <span class=\"citation\">Targ. Ezek. IV, 2</span>; <span class=\"citation\">XXI, 27</span> (h. <a href=\"#\" data-headword=\"כרים\">כָּרִים</a>).</div>","alt":[]},"2806":{"h":"אֶפְרוֹחַ","r":"A02806","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>brood, young bird</i>. <span class=\"citation\">Bets. 6ᵇ</span>; <span class=\"citation\">Tosef. ib. I, 1</span>; a. fr.—<span class=\"citation\">Gen. R. s. 37</span> <span dir=\"rtl\">אתמול א׳ וכ׳</span> yesterday a chicken, to-day an egg (lost prestige).</div>","alt":[]},"2807":{"h":"אֶפְרוֹחָא","r":"A02807","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">אֶפְרוֹחִין</span> <span class=\"citation\">Targ. Deut. XXII, 6</span> (Var. <a href=\"#\" data-headword=\"אִפְרָחִין\">אִפְרָחין</a>); a. e.—<span dir=\"rtl\">אֶפְרוֹחיָּיא</span>. <span class=\"citation\">Y. Ber. II, 5ᵃ</span></div>","alt":[]},"2808":{"h":"אפרוטוס","r":"A02808","html":"<div class=\"sense\">, v. <span dir=\"rtl\">איפרו׳</span></div>","alt":[]},"2809":{"h":"אפרוכוס","r":"A02809","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אִיפַּרְכוֹס\">אִיפּרְכוֹס</a>, v. <a href=\"#\" data-headword=\"אִיפַּרְכָא\">אִיפַּרְכָא</a></div>","alt":[]},"2810":{"h":"אַפְרוֹמְבְּיָא","r":"A02810","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (φορβεία) <i>halter</i>. <span class=\"citation\">Tosef. Kel. B. Mets. IV, 6</span> sq. V. <a href=\"#\" data-headword=\"פְּרוּמְבְּיָא\">פְּרוֹמְבְּיָא</a>.</div>","alt":[]},"2811":{"h":"אפרופוס","r":"A02811","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אַפֹּופְסִין\">אפופסיס</a>.</div>","alt":[]},"2812":{"h":"אַפְרַזְתָּא","r":"A02812","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְזַפְתָּא I\">אַרְזַפְתָּא</a></div>","alt":[]},"2813":{"h":"אפרחי","r":"A02813","html":"<div class=\"sense\"> <span class=\"citation\">Y. Sot. III, 18ᶜ</span> bot., v. <a href=\"#\" data-headword=\"פְּרַח I\">פְּרַח</a></div>","alt":[]},"2814":{"h":"אִפְרָחִין","r":"A02814","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶפְרוֹחָא\">אֶפְרוֹחָא</a></div>","alt":[]},"2815":{"h":"אפרטוטות","r":"A02815","html":"<div class=\"sense\">, read with Mus.:</div>","alt":[]},"2816":{"h":"*אַפָּרָטוֹסוֹת","r":"A02816","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (apparatus) <i>military engines</i>. Y. Keth. II, 26ᵈ; (<span class=\"citation\">Y. Gitt. III, 45ᵃ</span> top <span dir=\"rtl\">איסטרטיות</span> <i>camps</i>).</div>","alt":[]},"2817":{"h":"אַפִּרְיוֹן","r":"A02817","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>on a frame</i>,] <i>frame and hangings of a palanquin, litter of parade</i>, esp. for a bride in the wedding procession. <span class=\"citation\">Sot. IX, 14</span> (<span class=\"citation\">49ᵃ</span>); Tosef. ib. XV, 9.—<span class=\"citation\">Sot. 12ᵃ</span> <span dir=\"rtl\">הושיבה בא׳</span> (<span class=\"citation\">Pesik. R. s. 43</span> <span dir=\"rtl\">בפוריא</span>), a. e. he placed her in the litter, arranged a wedding procession for her. <span class=\"citation\">Num. R. s. 20</span>, end, <span dir=\"rtl\">לישב בא׳</span> to take her seat in the litter (for the wedding procession); a. e.</div>","alt":["אַפִּירְיוֹן"]},"2818":{"h":"*אַפְרִיזָא","r":"A02818","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּרַז\">פרז</a>) [<i>the leader</i>], (archit.) <i>the king-beam, principal</i>. <span class=\"citation\">B. Bath. 6ᵃ</span></div>","alt":[]},"2819":{"h":"אַפִּרְיָיא","r":"A02819","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפִּרְיָין\">next w.</a></div>","alt":[]},"2820":{"h":"אַפִּרְיָין","r":"A02820","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"אַפִּרְיוֹן\">אַפִּרְיוֹן</a>. B. Mets. end <span dir=\"rtl\">א׳ נמטייה לר׳ שמעון</span> ed. (Ar. <span dir=\"rtl\">הבו ליה אפרייא לר&quot;ל</span>, Var. <a href=\"#\" data-headword=\"אִיפּוּרְיָיא\">אִיפּוּרְיָיא</a>, <span dir=\"rtl\">איפרייא</span>; Ms. M. <a href=\"#\" data-headword=\"אַפִּרְיָן\">אפרין</a>. Ms. H. <a href=\"#\" data-headword=\"אַפִּרְיוֹן\">אפריון</a>, v. Rabb. D. S. a. l. note) let a palanquin be put up for R. Sh., i.e. he deserves a triumphal procession. Cmp. <a href=\"#\" data-headword=\"פִּיפְיוֹרָא\">פִּיפְיוֹרָא</a>.</div>","alt":[]},"2821":{"h":"אֶפְרַיִם","r":"A02821","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Ephraim</i>. </div><div class=\"sense\"><b>1)</b>  son of Joseph, progenitor of the <i>tribe of Ephraim</i>. <span class=\"citation\">Gen. R. s. 98</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  name of the expected Messiah, also called <i>the Messiah, son of Joseph</i>, in contradist., in contradist. to the Messiah of the tribe of Judah. <span class=\"citation\">Pesik. R. s. 36</span>; <span class=\"citation\">37</span>.</div><div class=\"sense\"><b>—3)</b>  a disciple of R. Meïr. <span class=\"citation\">B. Mets. 87ᵃ</span>; <span class=\"citation\">Gen. R. s. 85</span> א׳ מקשאה E. the disputant.</div><div class=\"sense\"><b>—4)</b>  *E. the Scribe, a disciple of Resh Lakish. B. Mets. end (Ms. M. <span dir=\"rtl\">א׳ מקשאה</span>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"2822":{"h":"אַפִּרְיָן","r":"A02822","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפִּרְיָין\">אפִּרְיָין</a></div>","alt":[]},"2823":{"h":"אַפְרִיקִי","r":"A02823","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Africa, Ἀφρική) <i>Africa</i>, esp. Northern A., the <i>Africa Propria</i> or <i>Vera</i> of the Romans. Y. Shebi. III, 36ᶜ bot. the Girgashite <span dir=\"rtl\">הלך לו לא׳</span> emigrated to Africa (Carthage). Ib. ‘a land like your own’ (<span class=\"citation\">II Kings XVIII, 32</span>) <span dir=\"rtl\">זו א׳</span> that means A.; <span class=\"citation\">Lev. R. s. 17</span>; <span class=\"citation\">Deut. R. s. 5</span>.—<span class=\"citation\">Snh. 91ᵃ</span> <a href=\"#\" data-headword=\"אַפְרִיקִי II\">אפריקיא</a> (corr. acc.). <span class=\"citation\">Tam. 32ᵃ</span> sq. <span dir=\"rtl\">מדינת א׳</span>; (<span class=\"citation\">Lev. R. s. 27</span>; Pesik. Shor p. 74ᵃ <a href=\"#\" data-headword=\"קַרְטִיגְנָא\">קרטיגנא</a>, v. <a href=\"#\" data-headword=\"חוֹשֶׁךְ\">חֹשֶׁךְ</a>). <span class=\"citation\">Lam. R. to I, 5</span>. <span dir=\"rtl\">דוכוס דאפריקא</span> Duke (military governor) of A. (Egypt &amp;c.).—Denom. <span dir=\"rtl\">אַפְרְקִיִּים</span>, ch. <a href=\"#\" data-headword=\"אַפְרִיקִי\">אַפְרִיקָאֵי</a> <i>Africans</i> (Negroes). <span class=\"citation\">Sabb. 31ᵃ</span>.—<span class=\"citation\">Targ. II Chr. XXI, 16</span>.</div>","alt":["(אַפְרִיקָא) I"]},"2824":{"h":"אַפְרִיקִי II","r":"A02824","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (supposed to be) <i>Phrygia</i>, in Asia Minor. <span class=\"citation\">Targ. Y. Gen. X, 2</span> (h. text <span dir=\"rtl\">גֹמֶר</span>); <span class=\"citation\">Gen. R. s. 37</span>, beg.; (Y. Meg. I, 71ᵇ bot.; <span class=\"citation\">Yoma 10ᵃ</span> <a href=\"#\" data-headword=\"גִּרְמַמְיָא\">גרממיא</a>). [<span class=\"citation\">Y. Ber. IX, 13ᶜ</span> top; <span class=\"citation\">R. Hash. 26ᵃ</span> (of R. Akiba’s journeys)—perh. belonging to preced.]</div>","alt":["אַפְרִיקְיָא"]},"2825":{"h":"אִפַּרְכָא","r":"A02825","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיס ²\">אִיפַּ׳</a></div>","alt":["אִפַּרְכוֹס"]},"2826":{"h":"*אפרכוריס","r":"A02826","html":"<div class=\"sense\"> pr. n. pl., prob. <span dir=\"rtl\">אֲפִּיכִירוֹס</span> = <a href=\"#\" data-headword=\"אֲפִיקֵירוֹס\">אֲפִּיקִירוֹס</a> q. v. Y. Gitt. IV, 46ᵃ <span dir=\"rtl\">א׳ צריכא</span> if a slave fled to Ep., it is undecided whether he may be extradited; cmp. <a href=\"#\" data-headword=\"אנטריס\">אנטריס</a>.</div>","alt":[]},"2827":{"h":"אֶפַּרְכִי","r":"A02827","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פִּיס ²\">אִיפַּ׳</a></div>","alt":["אֶפַּרְכְיָא"]},"2828":{"h":"אפרכלי","r":"A02828","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 45ᵃ</span> ed., v. <a href=\"#\" data-headword=\"פַּרְכִּיל\">פַּרְכִיל</a>, <span dir=\"rtl\">פַּרְכָל</span>.</div>","alt":[]},"2829":{"h":"אֲפַרְכָּס","r":"A02829","html":"<div class=\"sense\"> transpos. of <a href=\"#\" data-headword=\"אַרְפְּכָס\">אַרְפְּכָס</a>.</div>","alt":[]},"2830":{"h":"אֲפַרְכֶסֶת","r":"A02830","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פַּרְכֵּס\">פרכס</a> q. v.) [the grinder, moving to and back,] <i>the hopper, grain-receiver</i> on top of the millstone. <span class=\"citation\">Ḥag. 3ᵃ</span>; <span class=\"citation\">Ḥull. 89ᵃ</span> <span dir=\"rtl\">עשה אזנך כאפ׳</span> (ed. <span dir=\"rtl\">כארפ׳</span>) make thy ear like the hopper to receive the teachings &amp;c.; <span class=\"citation\">Y. Kidd. I, end, 61ᵈ</span> <span dir=\"rtl\">נקב אזנך כאפרכס הזו</span> perforate (make open) thy ear &amp;c.; <span class=\"citation\">Pesik. R. s. 10</span> <span dir=\"rtl\">הרעישה אזנך וכ׳</span></div>","alt":["(אֲפַרְכֵס)"]},"2831":{"h":"אַפַּרְסְמָא","r":"A02831","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"אַפַּרְסָמוֹן\">next w.</a> <span class=\"citation\">Targ. Y. Ex. XXXV, 28</span>.—<span class=\"citation\">Kerith. 5ᵇ</span>. <span class=\"citation\">R. Hash. 23ᵃ</span>. <span class=\"citation\">Ber. 43ᵃ</span>. <span class=\"citation\">Ab. Zar. 28ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"*אַסְפַּסְתָּא\">אספסתא</a>).</div>","alt":[]},"2832":{"h":"אַפַּרְסָמוֹן","r":"A02832","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"פִּרְסֵם\">פִּרְסֵם</a>, <span dir=\"rtl\">פִּרְצֵם</span>; cmp. also <a href=\"#\" data-headword=\"בַּלְסָם\">בלסם</a>, <a href=\"#\" data-headword=\"בַּלְסָם\">בלסמון</a>) </div><div class=\"sense\"><b>1)</b> <i>balsamum</i>. <span class=\"citation\">Yoma 38ᵇ</span> sq. <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> top; a. fr.—<span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">אפל׳</span>.</div><div class=\"sense\"><b>—2)</b> <i>balsam-tree, balsam-wood</i>. <span class=\"citation\">Ber. 43ᵃ</span></div>","alt":["אַפַּרְסְמוֹן","(אפלסמון)"]},"2833":{"h":"אַפַּרְסְקִין","r":"A02833","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (πέρσικα, τὰ) <i>peaches</i>. <span class=\"citation\">Maasr. I, 2</span>; a. fr. V. <a href=\"#\" data-headword=\"פַּרְסֵק\">פַּרְסֵק</a>.</div>","alt":["(אַפַּרְסְקִים)","פַּרְסְקִין"]},"2834":{"h":"אַפַּרְקִיד","r":"A02834","html":"<div class=\"sense\"> adv. (v. <a href=\"#\" data-headword=\"פרקד\">פרקד</a>) <i>on the back</i>. <span class=\"citation\">Ber. 13ᵇ</span>; <span class=\"citation\">Nidd. 14ᵃ</span> <span dir=\"rtl\">גני א׳</span> lies on his back. <span class=\"citation\">B. Bath. 79ᵃ</span> top.</div>","alt":[]},"2835":{"h":"אַפְרִקְיָא","r":"A02835","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אַפְרִי׳</span></div>","alt":[]},"2836":{"h":"אַפְרַקְסוּת","r":"A02836","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אַפִּקַרְסוּת\">אַפְקַרְסוּת</a>. <span class=\"citation\">Ber. 23ᵇ</span>; <span class=\"citation\">24ᵇ</span> ed.</div>","alt":[]},"2837":{"h":"אַפְרַשׁ","r":"A02837","html":"<div class=\"sense\">, adv., with <a href=\"#\" data-headword=\"לְ־\">לְ־</a> (v. <a href=\"#\" data-headword=\"פְּרַשׁ\">פְּרַשׁ</a>) <i>for a time to be defined</i> (in the future), <i>indefinitely, forever</i> (h. <span dir=\"rtl\">לָנֶצַח</span>). <span class=\"citation\">Targ. Is. LVII, 16</span>; a. fr.</div>","alt":[]},"2838":{"h":"אַפְרָשָׁה","r":"A02838","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פָּרַשׁ\">פָּרַשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>separation, setting apart for a sacred purpose</i>, as the heave-offering (T’rumah, for the priest), or a sacrifice (Korban); also <i>isolation on account of levitical uncleanness</i>, or <i>on acc.</i> <i> of sacredness</i>. Trnsf. <i>the thing set apart, offering, gift</i>. Y. Yoma I, beg. 38ᵃ; Tosef. <span class=\"citation\">Parah III</span> (<span class=\"citation\">II), 1</span> <a href=\"#\" data-headword=\"זֶה\">זה</a> (<a href=\"#\" data-headword=\"שַׁרְיֵי\">הַ</a>)<span dir=\"rtl\">אַפְרָשָׁתוֹ בטהרה וכ׳</span> (Babli <span class=\"citation\">Yoma 8ᵇ</span> <span dir=\"rtl\">פרישתו</span>) the one is isolated for the purpose of purification (because of uncleanness), the other for sanctification (for the services of the Day of Atonement). <span class=\"citation\">Y. Dem. VII, 26ᵇ</span> bot. <span dir=\"rtl\">תלוי בה׳</span> depends on the act of setting apart. <span class=\"citation\">B. Kam. V, 7</span> <span dir=\"rtl\">הַפְרָשַׁת הר סיני</span> the isolation of Mount Sinai prescribed as preparation for the giving of the Law (<span class=\"citation\">Ex. XIX, 13</span>); a. fr.—Pl. <span dir=\"rtl\">אַפְרָשׁוֹת</span>, <span dir=\"rtl\">הַפְרָשׁוֹת</span>. Y. Shek. II, 46ᵈ top <span dir=\"rtl\">שלש א׳</span> three kinds of sacred gifts.</div><div class=\"sense\"><b>—2)</b> <i>crossing the Ocean;</i> cmp. <a href=\"#\" data-headword=\"פָּרַשׁ\">פָּרַשׁ</a>. <span class=\"citation\">Gen. R. s. 6</span> <span dir=\"rtl\">הפרשת וכ׳</span>; <span class=\"citation\">Lev. R. s. 25</span> <a href=\"#\" data-headword=\"פָּרָשׁ ²\">פָּרָשַׁת</a>.</div>","alt":["הַפְרָשָׁה"]},"2839":{"h":"אַפְרָשׁוּ","r":"A02839","html":"<div class=\"sense\">as <a href=\"#\" data-headword=\"אַפְרָשָׁה\">foreg.</a> 1). <span class=\"citation\">Targ. Ezek. XLV, 1</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"אַפְרָשׁוּ\">אַפְרַשְׁוָתָא</a>, constr. <span dir=\"rtl\">אַפְרַשְׁוַת</span>. <span class=\"citation\">Targ. O. Num. XVIII, 8</span>; <span class=\"citation\">19</span> (some ed. <a href=\"#\" data-headword=\"אַפְרָשׁוּ\">אַפְרָשׁוּת</a> sing.).</div>","alt":["אַפְרָשׁוּתָא"]},"2840":{"h":"אֶפְרָתִי","r":"A02840","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (perh. = b. h.) <i>of Ephratha, Ephrathi</i>. <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> top <span dir=\"rtl\">יוסף א׳</span>; <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> top <span dir=\"rtl\">יוסי א׳</span>; (<span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">הַפְּרָתִי</span>).—Pl. <a href=\"#\" data-headword=\"אֶפְרָתִי\">אֶפְרָתִים</a>. <span class=\"citation\">Ruth R. to I, 2</span> expl. <a href=\"#\" data-headword=\"פלטיאני\">פלטיאני</a> <i>courtiers, noblemen</i>.—Ch. <a href=\"#\" data-headword=\"אֶפְרָתִי\">אֶפְרָתִין</a>. Targ. Ruth l. c. <span dir=\"rtl\">א׳ רבנין</span> (in Ms. our w. omitted).</div>","alt":[]},"2841":{"h":"אֶפֶשׁ","r":"A02841","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֶפֶשׁ\">אפש</a>, √<a href=\"#\" data-headword=\"אַף I\">אף</a>, cmp. <span dir=\"rtl\">הפץ</span>; corresp. to b. h. <a href=\"#\" data-headword=\"נֶפֶשׁ\">נֶפֶשׁ</a>, v. <span class=\"citation\">Jer. XV, 1</span>) <i>desire, pleasure;</i> [only with personal pron. as suffix]. <span class=\"citation\">Naz. IV, 5</span> אי אַפְשִׁי וכ׳ I will not live with an offensive woman. <span class=\"citation\">Keth. XII, 3</span> אי א׳ לזוז וכ׳ I cannot leave my husband’s house. Y. Yoma VII, 45ᵇ bot. <span dir=\"rtl\">אי א׳ שיכפר וכ׳</span> I do not want the Day of Atonement to bring me forgiveness. <span class=\"citation\">Y. Yeb. XIII, beg. 13ᵇ</span> א׳ בנישואיך I am willing to marry thee. <span class=\"citation\">Num. R. s. 13</span> (alluding to <span class=\"citation\">Gen. III, 22</span>) <span dir=\"rtl\">אמר אדם אי א׳</span> said Adam, I cannot (do penitence). Said the Lord, ‘And now’,—said Adam ‘pen’, ‘by no means’, ‘I will not’. <span class=\"citation\">Y. Keth. VII, 31ᵇ</span> bot. <span dir=\"rtl\">אי א׳ אשה</span> (read <span dir=\"rtl\">באשה</span>). <span class=\"citation\">Y. Pes. VIII, 35ᵈ</span> bot. <span dir=\"rtl\">א׳ שתמנה</span> (read <span dir=\"rtl\">אי א׳</span>). Y. Gitt. VI, 1; a. fr. <span class=\"citation\">Gen. R. s. 38</span> <span dir=\"rtl\">אי אַפְשֵׁנוּ וכ׳</span> we desire neither him nor his divine protection.</div>","alt":["אֶיפֶשׁ"]},"2842":{"h":"אַפְשַׁח","r":"A02842","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"פְּשַׁח\">פְּשַׁח</a></div>","alt":[]},"2843":{"h":"אפשלתה","r":"A02843","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַשְׁפְּלָה\">אַשְׁפְּלָה</a></div>","alt":[]},"2844":{"h":"אֶפְשַׁר","r":"A02844","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּשַׁר I\">פשר</a>) <i>division, space between, alternative</i>, whence <i>possibility; it is possible</i>. <span class=\"citation\">Targ. Job XIV, 14</span>; a. fr.—<span class=\"citation\">Ḥull. 11ᵇ</span> <span dir=\"rtl\">היכא דא׳ א׳</span> where it is possible (to ascertain facts), it is possible (we must do), but where it is impossible &amp;c. <span class=\"citation\">Yeb. 61ᵇ</span> sq. <span dir=\"rtl\">אין דנין א׳ משאי א׳</span> we cannot form an analogy between a case where there is an alternative and one where there is none. <span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">לא א׳ ליה</span> he has no means. <span class=\"citation\">Y. Sot. VII, 21ᶜ</span> bot. <span dir=\"rtl\">אי א׳ לומר</span> you cannot say. <span class=\"citation\">Taan. 3ᵇ</span> <span dir=\"rtl\">אי א׳ לעולם וכ׳</span> the world cannot exist without &amp;c.; a. fr.</div>","alt":["אֶיפְשַׁר","(אֶוְשַׁר)"]},"2845":{"h":"*אַפְתָּא I","r":"A02845","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>bread</i>. <span class=\"citation\">Ber. 40ᵇ</span> quot. in Ar., prob. from misreading <a href=\"#\" data-headword=\"רִיפְתָּא\">ריפתא</a>; v. Rabb. D. S. a. l. Ms. M.</div>","alt":[]},"2846":{"h":"אַפְתָּא II","r":"A02846","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פתי\">פתי</a>) <i>extension, width</i>, whence </div><div class=\"sense\"><b>1)</b>  (archit.) <i>a chamber</i> or <i>wing projecting from a building</i> (with stairs from outside), <i>balcony-chamber</i>. <span class=\"citation\">B. Bath. 61ᵃ</span> (explain. <a href=\"#\" data-headword=\"יָצִיעַ I\">יציע</a>). <span class=\"citation\">Ḥull. 92ᵃ</span> <span dir=\"rtl\">ב&quot;כ דתותי א׳</span> a synagogue named ‘under the balcony’.</div><div class=\"sense\"><b>—2)</b>  (bot.) <i>stole, tuber</i>. <span class=\"citation\">Lam. R. to I, 16</span>, end <span dir=\"rtl\">כהדא א׳ דקרא וכ׳</span> like that tuber of cabbage, the larger the latter grows, the smaller gets the former.</div><div class=\"sense\"><b>—3)</b>  pl. <a href=\"#\" data-headword=\"פְּתֵי I\">אַפְתֵּי</a>, only with <a href=\"#\" data-headword=\"רְמַשׁ\">רַמְשָׁא</a>, <i>spreading of night, nightfall</i>. <span class=\"citation\">Y. Ab. Zar. I, beg. 39ᵃ</span>. Y. Bath. II, end, 13ᶜ. <span class=\"citation\">Lev. R. s. 25</span>; <span class=\"citation\">Koh. R. to II, 20</span>.—<span dir=\"rtl\">בפתי רמשא</span> = <span dir=\"rtl\">בא׳ ר׳</span>. Y. Ab. Zar. l. c.; <span class=\"citation\">Gen. R. s. 78</span>.</div>","alt":[]},"2847":{"h":"אפתיסיס","r":"A02847","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִיפֹּותוֹרוֹס\">אִיפּוֹתּוֹרוֹס</a></div>","alt":[]},"2848":{"h":"אֶפְתַּנְטִין","r":"A02848","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַוְותֶּנְטִי\">אֶוְותַּנְטִי</a></div>","alt":[]},"2849":{"h":"*אַפְתְּקָא","r":"A02849","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"פְּתַק I\">פתק</a>, cmp. <a href=\"#\" data-headword=\"הֶפְתֵּק\">הֶפְתֵּק</a>) <i>ladle with which provision is dealt out</i>. <span class=\"citation\">Snh. 39ᵃ</span> <span dir=\"rtl\">מחא ביה בא׳</span> (Rashi <span dir=\"rtl\">באפתקיה</span>, Ms. M. <span dir=\"rtl\">מחייה בהפתקיה</span>) he (the servant) warned him (Ms. M. struck him) with his ladle; (Rashi: struck him on his <i>neck</i>(!), v. <a href=\"#\" data-headword=\"אַפְקוֹתָא\">אַפְקוֹתָא</a>).</div>","alt":["הַפְתְּקָא"]},"2850":{"h":"אַפְתְּרִין","r":"A02850","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. I Num. XIII, 21</span> Ar., v. <a href=\"#\" data-headword=\"פַּתְרָן\">פַּתְרָן</a></div>","alt":[]},"2851":{"h":"אִצָּא","r":"A02851","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיצָא I\"><span dir=\"rtl\">אִיצָא</span> I</a></div>","alt":[]},"2852":{"h":"אֶצְבַּע","r":"A02852","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.; = <span dir=\"rtl\">עצבע</span>; <span dir=\"rtl\">עצב</span>, </div><div class=\"sense\"><b>1)</b> <i>finger</i>, esp. <i>index-finger</i>. <span class=\"citation\">Men. 11ᵃ</span> <span dir=\"rtl\">זו א׳</span> with this (the fourth from the little finger) the measure of ‘a finger’ is taken; <span class=\"citation\">Keth. 5ᵇ</span>. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> bot.; <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">(<span dir=\"rtl\">מטיפי</span>) <span dir=\"rtl\">מקוטעי א׳</span></span> who had their finger cut off (in evidence of devotion to the cause). <span class=\"citation\">Yoma I, 7</span> <span dir=\"rtl\">א׳ צרדה</span>; <span class=\"citation\">Tosef. ib. I, 9</span> explained <span dir=\"rtl\">א׳ גדולה</span> <i>middle finger;</i> cmp. Tanḥ. Bo, end, expl. <a href=\"#\" data-headword=\"אֶמְצָעִי\">אמצעית</a>.—<span class=\"citation\">Keth. 71ᵃ</span> <span dir=\"rtl\">הוא נותן א׳ וכ׳</span> he (the husband) puts his finger between her teeth (and must expect to be bitten), i.e. has to take the consequences of not interfering with her vow in due time.</div><div class=\"sense\"><b>—2)</b> <i>any projecting limb resembling the shape of a finger</i>. <span class=\"citation\">Ḥull. 61ᵃ</span> א׳ יתירה <i>the projecting toe</i> on a bird’s claw. <span class=\"citation\">Tam. IV, 3</span> (<span class=\"citation\">31ᵃ</span>) <span dir=\"rtl\">א׳ הכבד</span> the <i>lobe</i> of the liver.—Fig. (like <span dir=\"rtl\">יד</span>) <i>share, part.</i> <span class=\"citation\">Y. Pes. IV, 31ᵃ</span> top; <span class=\"citation\">Y. Ab. Zar. I, 40ᵃ</span> top, v. <a href=\"#\" data-headword=\"אֶמְצַע\">אֶמְצַע</a>.—Pl. <span dir=\"rtl\">אֶצְבָּעוֹת</span>. <span class=\"citation\">Ḥag. 15ᵃ</span>; a. fr. (mostly in the sense of <i>finger’s length</i>).—<span class=\"citation\">Pes. 112ᵇ</span>; <span class=\"citation\">Nidd. 66ᵃ</span> euphem. for <i>membra virilia.</i>—<i>Dual</i> <span dir=\"rtl\">אֶצְבְּעַיִּם</span>, <span dir=\"rtl\">אֶצְבְּעַיִּים</span>, <span class=\"citation\">Cant. R. to VIII, 11</span> <span dir=\"rtl\">גידם א׳</span> one whose (index) fingers were lopped (stump-like). Ib. that whole trade of mine <span dir=\"rtl\">אינה נקנית אלא בא׳</span> cannot be acquired except by learning how to use the index-fingers.—<span class=\"citation\">Pes. 109ᵃ</span>, a. e. <i>two finger lengths</i></div>","alt":[]},"2853":{"h":"אֶצְבְּעָא","r":"A02853","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. XXXI, 18</span>; a. e.—Pl. <a href=\"#\" data-headword=\"אצבעתא\">אֶצְבְּעָתָא</a>. <span class=\"citation\">Targ. Y. Gen. I, 7</span>; a. fr. <span class=\"citation\">Targ. Ps. VIII, 4</span> <span dir=\"rtl\">אצבעותך</span>. <span class=\"citation\">Ned. 49ᵇ</span> <span dir=\"rtl\">באצבעתיה</span> with his fingers. <span class=\"citation\">Erub. 53ᵃ</span> we are <span dir=\"rtl\">כי א׳ בקירא לסברא</span> (Ar. <a href=\"#\" data-headword=\"אוּצְבָּתָא\">אוצבתא</a>) as to reasoning like fingers on wax (hard to be impressed upon), <span dir=\"rtl\">ולשכחה וכ׳</span> but as to forgetfulness like fingers put in seed (leaving no trace), v. <a href=\"#\" data-headword=\"בִּזְרָא\">בִּזְרָא</a>; a. fr.</div>","alt":["אֶצְבַּע"]},"2854":{"h":"אֶצְבָּעִי","r":"A02854","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>of a finger’s length, dwarf of the smallest size</i>. <span class=\"citation\">Bekh. 45ᵇ</span></div>","alt":[]},"2855":{"h":"אצבעתא","r":"A02855","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶצְבְּעָא\">אֶצְבְּעָא</a></div>","alt":[]},"2856":{"h":"*אֲצַבְתִּי","r":"A02856","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <span dir=\"rtl\">צבת</span>, cmp. <span dir=\"rtl\">אצבע</span>) <i>tongs, snuffers.</i> Ohol. XIII, 4 (Var. <a href=\"#\" data-headword=\"אֲסַפְתִּי\">אֲסַפְתִּי</a>); Tosef. ib. XIV, 4 <span dir=\"rtl\">לאִיצַבְתּוֹ</span>, ed. Zuck. (Var. <span dir=\"rtl\">ולא לצבתו</span>) and for the snuffers belonging to it (the candlestick).</div>","alt":[]},"2857":{"h":"אָצוּ","r":"A02857","html":"<div class=\"sense\"> Ar., v. <a href=\"#\" data-headword=\"אַצְוָותָא\">אַצְוָותָא</a></div>","alt":[]},"2858":{"h":"אַצְוָא","r":"A02858","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַצְוָוא\">next w.</a></div>","alt":[]},"2859":{"h":"אַצְוָוא","r":"A02859","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"אַצְוָתָא\">אַצְוָתָא</a>, <a href=\"#\" data-headword=\"אַצְוָותָא\">אַצְוָותָא</a> (<a href=\"#\" data-headword=\"צוי\">צוי</a>, cmp. <a href=\"#\" data-headword=\"צבי\">צבי</a> a. <span dir=\"rtl\">סבב</span>) <i>creeper, vine</i>. <span class=\"citation\">Pes. 39ᵃ</span> (expl. <a href=\"#\" data-headword=\"חַרְחֲבִינָא\">חרחבינה</a>) <span dir=\"rtl\">אצווא דדיקלא</span> Ar. (ed. <a href=\"#\" data-headword=\"אַצְוָותָא\">אַצְוָותָא</a>, Ms. M. <a href=\"#\" data-headword=\"אֲסִיתָא\">אסיתא</a>, read <a href=\"#\" data-headword=\"אָסוּתָא\">אַסְוָתָא</a>, R. Ḥan. <a href=\"#\" data-headword=\"אַסְוָא\">אַסְוָא</a>, v. Rabb. D. S. a. l. note); <span class=\"citation\">Keth. 50ᵃ</span> <a href=\"#\" data-headword=\"אַצְוָתָא\">אַצְוָתָא</a>. <span class=\"citation\">Erub. 26ᵇ</span> אצוותא חרזייתא דדיקלא Ar. (ed. <span dir=\"rtl\">דדיקלא</span> omitted, also in Ms. M., cmp. Rabb. D. S. a. l. note) <i>arkablin</i> are the prickling creepers of the palm-tree; v. <a href=\"#\" data-headword=\"חַרְזָא\">חַרְזָא</a>. V. <a href=\"#\" data-headword=\"אַצְוָותָא\">אַצְוָותָא</a>.</div>","alt":[]},"2860":{"h":"אַצְוַוחְתָּא","r":"A02860","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">צוח</span>) <i>cry, noise</i>. <span class=\"citation\">Targ. Ezek. VII, 14</span>.</div>","alt":["אַצְוָחוּתָא"]},"2861":{"h":"אַצְוָותָא","r":"A02861","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">אצי</span>, √<span dir=\"rtl\">אץ</span>, cmp. <a href=\"#\" data-headword=\"חֲצָב I\">חצב</a> a. denom., a. <a href=\"#\" data-headword=\"אֲסִיתָא\">אֲסִיתָא</a>) <i>trough, kneading trough;</i> also <i>a trough-full, the quantity of bread baked at a time, batch</i>. <span class=\"citation\">Targ. Deut. XXVIII, 5</span>; a. e. (also as plur.) <span class=\"citation\">Targ. Ex. VII, 28</span>; a. e.—Pesik. B’shall. p. 91ᵃ <span dir=\"rtl\">כל א׳ וכ׳</span> the entire batch of bread. Ib. 91ᵇ (correct acc. to Buber note 198; Var. Ar. <a href=\"#\" data-headword=\"אָצוּ\">אָצוּ</a>, <a href=\"#\" data-headword=\"אַלְוָותָא\">אַסְוָותָא</a>, v. Koh. Ar. Compl. s. v.). Cmp. <a href=\"#\" data-headword=\"אֲצִיצָא\">אֲצִיצָא</a>. V. <a href=\"#\" data-headword=\"אַצְוָוא\">אַצְוָוא</a>.</div>","alt":["אַצְוָתָא"]},"2862":{"h":"אַצְוָחוּתָא","r":"A02862","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אִצְוַוחְ׳</span></div>","alt":["אַצְוַחְתָּא"]},"2863":{"h":"אַצְוָתָא","r":"A02863","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַצְוָוא\">אַצְוָוא</a> a. <a href=\"#\" data-headword=\"אַצְוָותָא\"><a href=\"#\" data-headword=\"אַצְוָותָא\">אִצְוָותָא</a>.</a></div>","alt":[]},"2864":{"h":"אִצְט־","r":"A02864","html":"<div class=\"sense\">, for words not found here, v. sub. <span dir=\"rtl\">אִסְט׳</span>, <a href=\"#\" data-headword=\"אִסְטְרָטָא\">אִיסְט׳</a> or <span dir=\"rtl\">אִיצְט׳</span>.</div>","alt":[]},"2865":{"h":"אִצְטַדְיָא","r":"A02865","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"צדי\">צדי</a>) </div><div class=\"sense\"><b>1)</b> <i>destruction</i>. <span class=\"citation\">Targ. Prov. XVII, 14</span> (h. text <a href=\"#\" data-headword=\"גָּלַע\">התגלע</a>; for <a href=\"#\" data-headword=\"טְעֵי\">אטעי</a> ib. read <span dir=\"rtl\">אַטֵּישׁ</span>, v. <a href=\"#\" data-headword=\"נָטַשׁ I\">נטש</a>).</div><div class=\"sense\"><b>—2)</b>  (cacophem.) <i>theatre, arena;</i> prevailing vers. <a href=\"#\" data-headword=\"אִצְטַרְיָא\">אִצְטַרְיָא</a> q. v.</div>","alt":[]},"2866":{"h":"אִצְטַדִּין","r":"A02866","html":"<div class=\"sense\"> as <a href=\"#\" data-headword=\"אִצְטַדְיָא\">preced.</a> 2); v. <a href=\"#\" data-headword=\"אִצְטָרִין\">אִצְטָרִין</a></div>","alt":["אִצְטַדִּינִין"]},"2867":{"h":"אצטלוס","r":"A02867","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִצְטַלּוּת\">next w.</a></div>","alt":[]},"2868":{"h":"*אִצְטַלּוּת","r":"A02868","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְלַל I\">טלל</a>, v. <a href=\"#\" data-headword=\"אִסְטַלִּית\">אִסְטַלִּית</a>) <i>covering, lining of a shoe</i>. <span class=\"citation\">Tosef. Kel. B. Bath. IV, 6</span> <span dir=\"rtl\">שניטל האונטלית שבו</span> ed. Zuck. (R. s. to <span class=\"citation\">Kel. XXVI, 4</span> <span dir=\"rtl\">שניטלו האונטלים</span>; Var. ed. Zuck. <span dir=\"rtl\">האצטלו׳</span>; ed. <span dir=\"rtl\">האצטלוס</span>) read <span dir=\"rtl\">שניטלה א׳</span> the lining of which is off.; v. <span dir=\"rtl\">זרב</span>.</div>","alt":[]},"2869":{"h":"אצטרא","r":"A02869","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִצְטַרְיָא\">אִצְטַרְיָא</a></div>","alt":[]},"2870":{"h":"אצטרבאמוטא","r":"A02870","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְטְרוֹפוֹמָטָא\">אִסְטְרוֹפוֹמָטָא</a></div>","alt":[]},"2871":{"h":"אִצְטַרְיָא","r":"A02871","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָרַר\">סרר</a>, cmp. <span dir=\"rtl\">אסטרניא</span>, <span dir=\"rtl\">אצטרניא</span> P. Sm. 304 a. quot. ibid.; cmp. <a href=\"#\" data-headword=\"אֲבֵידָן\">אֲבֵידָן</a>) <i>place of debauchery</i>, an opprobrious name for the <i>theatres, arenas</i> &amp;c. of the Romans, and a phonetic perversion of <i>theatrum</i>, θέατρον. <span class=\"citation\">Ab. Zar. I, 7</span> (<span class=\"citation\">16ᵃ</span>) you must not build … <span dir=\"rtl\">גרדום אצטדייא וכ׳</span> (Ms. M. <span dir=\"rtl\">אצטריבא</span>, prob. <span dir=\"rtl\">אצטרינא</span>, v. supra; in Ib. 18ᵇ repeatedly <span dir=\"rtl\">אצטר׳</span>, Mishn. Nap. <a href=\"#\" data-headword=\"אִצְטַדְיָא\">אצטדיא</a>, in comment. ib. <span dir=\"rtl\">אצטרדיא</span>), expl. ib. 16ᵇ <span dir=\"rtl\">בסיליקי של גרדום וכ׳</span> a building for public execution (court) or for public entertainment (amphitheatre &amp;c.)—Pl. <a href=\"#\" data-headword=\"אִסְטַגְיוֹת\">אִסְטַרְיוֹת</a>. Sifra Aḥare IX, 13. [<span class=\"citation\">Men. 103ᵇ</span> <span dir=\"rtl\">איסטריא של מלך</span> royal amphitheatre(?), v. <a href=\"#\" data-headword=\"אִסְטְרַטְיָא\">אסטרטיא</a>.] [Tanḥ. <span class=\"citation\">B’resh. 2</span> <a href=\"#\" data-headword=\"אסטרטאות\">אִסְטְרָטָאוֹת</a>, Var. <a href=\"#\" data-headword=\"אִסְטְרָאוֹת\">אִסְטְרָאוֹת</a> <i>theatres</i>.] <span class=\"citation\">Ab. Zar. 18ᵇ</span> לא הלך לאיסטרטאות Ms. M. (ed. <a href=\"#\" data-headword=\"טַרְטְיָאוֹת\">טַרְטְיָאוֹת</a> q. v.; En Yak. <a href=\"#\" data-headword=\"טַרְטֵימַר\">תרט׳</a>). [For the vers. <a href=\"#\" data-headword=\"אִצְטַדְיָא\">אִצְטַדְיָא</a> v. s. v.]</div>","alt":["אִצְטַרְיָה","אִצְטַרְיָיא","אִיצְ׳","אִיסְ׳"]},"2872":{"h":"אִצְטָרִין","r":"A02872","html":"<div class=\"sense\"> [<a href=\"#\" data-headword=\"אִיצְטַדִּין\">אִיצְטַדִּין</a>, v. <a href=\"#\" data-headword=\"אִצְטַרְיָא\">preced.</a> end] f. (prop. pl. of <a href=\"#\" data-headword=\"אצטרא\">אצטרא</a>, <span dir=\"rtl\">אסטרא</span>, v. <a href=\"#\" data-headword=\"אִצְטַרְיָא\">preced.</a>, used as sing.)same. <span class=\"citation\">B. Kam. IV, 4</span> (<span class=\"citation\">39ᵃ</span>) <span dir=\"rtl\">שור האיצטרין</span> Ms. M. (ed. <a href=\"#\" data-headword=\"אִצְטַדִּין\">אצטדין</a>, Ms. H. a. R. a. Mish. Nap. <span dir=\"rtl\">אסטדין</span>, Y. ed. <a href=\"#\" data-headword=\"איסטדין\">איסטדין</a>) an ox of the arena (that killed a person). <span class=\"citation\">Tosef. Ab. Zar. II, 7</span> היושב באסטרין וכ׳ Var. (ed. Zuck. <span dir=\"rtl\">איסטרטון</span>, ed. <span dir=\"rtl\">איסטרין</span>) he who attends the arena as a spectator is like a murderer (countenancing bloodshed); Y. ib. I, 40ᵃ <span dir=\"rtl\">היושב באיצטדין</span> (interchanging with <a href=\"#\" data-headword=\"תִּיאַטְרוֹן\">תיאטרון</a> theatrum). <i>Pl.</i> אִצְטְרִינִין &amp;c. <span class=\"citation\">Ab. Zar. 18ᵇ</span> אין הולכין לא׳ מפני ש&quot;ד Ms. M. (ed. <span dir=\"rtl\">לאצטדינין מפני מושב לצים …</span>, v. Rabb. D. S. a. l. note) you must not go to the arenas on account of bloodshed (ed. to theatres on account of ‘scorners’ seat’, <span class=\"citation\">Ps. I, 1</span>). Ib. Ms. M. repeat. <a href=\"#\" data-headword=\"אִצְטָרִין\">אִצְטָרִינָן</a>, cmp. <a href=\"#\" data-headword=\"אֲבֵידָן\">אֲבֵידָן</a>. Tosef. l. c. 6 <span dir=\"rtl\">לאיצרטיונין</span> (Var. <span dir=\"rtl\">לצטרדיונין</span>, <span dir=\"rtl\">לצטריונין</span>); 7 <span dir=\"rtl\">לאיצטריונין</span> (Var. <span dir=\"rtl\">לטריונין</span>, <span dir=\"rtl\">לצטריונין</span>), cmp. <a href=\"#\" data-headword=\"טַרְטְיָאוֹת\">טַרְטְיָאוֹת</a>.</div>","alt":["אִסְטָרִין","אִיצְ׳","אִיסְ׳"]},"2873":{"h":"אִצְטַרְכַיָּא","r":"A02873","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">צרך</span>) <i>travelling necessaries, provision</i>. <span class=\"citation\">Gen. R. s. 60</span>. <span class=\"citation\">Koh. R. to XI, 1</span>.</div>","alt":[]},"2874":{"h":"אצטרמיטה","r":"A02874","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְטְרוֹפוֹמָטָא\">אִסְטְרוֹפוֹמָטָא</a></div>","alt":[]},"2875":{"h":"אִצְיָיא","r":"A02875","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">אצי</span>, v. <a href=\"#\" data-headword=\"אַצְוָותָא\">אַצְוָותָא</a>) <i>cut, depression</i>, (agric.) <i>bed</i> as a measure, <i>row</i>.—Pl. <a href=\"#\" data-headword=\"אִיצְיָיתָא\">אִצְיָיתָא</a>, <a href=\"#\" data-headword=\"אִיצְיָיתָא\">אִצְיָאתָא</a>, <a href=\"#\" data-headword=\"אִצְיָיא\">אוּצְ׳</a>, <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיצְ׳</a>. <span class=\"citation\">B. Bath. 12ᵃ</span> <span dir=\"rtl\">תלת א׳ וכ׳</span> (Ms. M. <span dir=\"rtl\">איצ׳</span>, Ms. F. <span dir=\"rtl\">איתייתא</span>(?)) three rows containing twelve vine-trees each; (v. Rabb. D. S. a. l. note). Ib. 41ᵇ he encroached on his neighbor’s ground <span dir=\"rtl\">תרתי או׳</span> ed. (Mss. <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a>) two <i>bed-widths</i></div>","alt":["אִיצְיָיא","אוּצְ׳"]},"2876":{"h":"אַצִּיל","r":"A02876","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>the joint which touches the rib, elbow</i> (with or without <span dir=\"rtl\">יד</span>). <span class=\"citation\">Arakh. 19ᵇ</span> <span dir=\"rtl\">עד הא׳</span> up to the elbow.—<i>Pl</i> <span dir=\"rtl\">אַצִּילִים</span>, constr. <span dir=\"rtl\">אַצִּילֵי</span>. <span class=\"citation\">Zeb. 19ᵃ</span> top <span dir=\"rtl\">כנגד א׳ וכ׳</span> corresponding to the elbows (where the elbow in natural position touches the body). Y. Yoma V, 42ᵇ bot.; a. fr.—(Chald.) <span class=\"citation\">Lev. R. s. 8</span>, beg. <span dir=\"rtl\">ודין אצילים פריך</span> some ed. (read <span dir=\"rtl\">אצילֵיה</span>) and the other has his elbow (arm) broken.</div>","alt":[]},"2877":{"h":"*אֲצִיפָא","r":"A02877","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"צִיפָּא I\">צִיפָּא</a>) <i>matting</i> used for bailing dates, cmp. <a href=\"#\" data-headword=\"חוֹתָל\">חוֹתָל</a>. [Oth. opin: <i>the flesh sticking to the stone</i> of half-ripe dates.] <span class=\"citation\">Gitt. 89ᵃ</span> a woman was betrothed <span dir=\"rtl\">בא׳ דתוחלא</span> (Ar. <span dir=\"rtl\">אצפא</span>) with &amp;c. (an object of no value).</div>","alt":["אַצְפָא"]},"2878":{"h":"אֲצִיצָא","r":"A02878","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אצץ</span>, cmp. <a href=\"#\" data-headword=\"אַצְוָותָא\">אַצְוָותָא</a>) <i>a common bellied vessel</i>. <span class=\"citation\">B. Bath. 144ᵃ</span> אפי׳ א׳ דהרסנא Ms. (ed. <a href=\"#\" data-headword=\"ע׳\">ע׳</a>) even a pot in which fish-hash is kept. <span class=\"citation\">Meg. 16ᵃ</span> א׳ דבית הכסא Ar. (ed. <a href=\"#\" data-headword=\"ע׳\">ע׳</a>, Ms. O. <a href=\"#\" data-headword=\"עֲסִיסָא\">עסיסא</a>) night-chamber. [<span class=\"citation\">Targ. Esth. V, 1</span> <span dir=\"rtl\">ריעא עֲצוּצָא</span>, read <span dir=\"rtl\">דְּעַ׳ …</span> of the night-chamber.] Hebr. <a href=\"#\" data-headword=\"עָצִיץ\">עָצִיץ</a>.</div>","alt":["עֲצִיצָא"]},"2879":{"h":"*אציתין","r":"A02879","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Koh. XII, 11</span> a gloss of <span dir=\"rtl\">אנצין</span>, missing in ed. Buxt. a. oth.; v. <a href=\"#\" data-headword=\"*אֲנַץ\">אֲנַץ</a></div>","alt":[]},"2880":{"h":"אֲצַל","r":"A02880","html":"<div class=\"sense\"> (√<span dir=\"rtl\">צל</span>, v. <span dir=\"rtl\">נצל</span>) <i>to protect, spare, exempt from taxes</i>. <span class=\"citation\">B. Bath. 55ᵃ</span>, v. <a href=\"#\" data-headword=\"*אַנְדִּיסְקֵי\">אַנְדִּיסְקֵי</a>.—[<span class=\"citation\">Bets. 14ᵃ</span> <span dir=\"rtl\">אצלי</span>, v. <a href=\"#\" data-headword=\"צלי\">צלי</a>.]</div>","alt":[]},"2881":{"h":"אָצֵל","r":"A02881","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Atsel, Atsal</i>, mentioned <span class=\"citation\">I Chron. VIII, 37</span> sq.; <span class=\"citation\">IX, 43</span> sq. <span class=\"citation\">Pes. 62ᵇ</span> <span dir=\"rtl\">בין א׳ לא׳ וכ׳</span> (Ms. <span dir=\"rtl\">מן א׳ …</span>, v. Rabb. D. S. a. l. note, for var. lect.) the explanation of the repetition of <span class=\"citation\">I Chr. VIII, 29</span> to 38, and IX, 35 to 44 and the verbal discrepancies between the two records would load four hundred camels with discussion; cmp. Rashi to I Chr. l. c.</div>","alt":["אָצַל"]},"2882":{"h":"אֵצֶל","r":"A02882","html":"<div class=\"sense\"><i>by the side of, near, with</i>. <span class=\"citation\">B. Mets. V, 1</span> <span dir=\"rtl\">הרי אֶצְלִי בהן יין</span> thou hast wine with me instead, i.e. I owe thee &amp;c. <span class=\"citation\">Ib. 85ᵇ</span> <span dir=\"rtl\">א׳ מי אתה תקוע</span> by whose side art thou lodged (in the world to come)?; <span class=\"citation\">Koh. R. to IX, 10</span>; a. fr.</div>","alt":[]},"2883":{"h":"אַצְלָחוּתָא","r":"A02883","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">צלח</span>) <i>success, prosperity</i>. <span class=\"citation\">Targ. Is. XXXIII, 20</span>; a. e.</div>","alt":[]},"2884":{"h":"אַצְלִי","r":"A02884","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"צְלֵי\">צְלֵי</a></div>","alt":[]},"2885":{"h":"אֶצְעָדָה","r":"A02885","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>clasp</i> or <i>brooch</i> for fastening dresses on going out, in Talm. <i>knee-band</i>; v. <a href=\"#\" data-headword=\"בֵּירִית\">בִּירִית</a>. <span class=\"citation\">Sabb. 63ᵇ</span> <span dir=\"rtl\">בירית זו א׳</span> what the Mishnah calls <i>birith</i> is the Biblical <i>etsadah</i>; modified <span class=\"citation\">ibid.</span> <span dir=\"rtl\">בירית תחת א׳ וכ׳</span> <i>birith</i> has the function of the <i>etsadah</i> (Rashi: <i>birith</i> around the knee serves the same purpose as <i>etsadah</i> on the shoulder, to save inconvenience in walking).</div>","alt":[]},"2886":{"h":"*אַצְפָּא","r":"A02886","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אצף</span>, v. <a href=\"#\" data-headword=\"יְצֵף\">יְצֵף</a>) <i>trouble, labor</i>. <span class=\"citation\">Targ. Prov. XVI, 23</span> <span dir=\"rtl\">בכל מן דא׳ לך</span> (h. text <span dir=\"rtl\">עצב</span>) in whatever is a trouble to thee.</div>","alt":["אָצְפָא"]},"2887":{"h":"אַצְפָא","r":"A02887","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲצִיפָא\">אֲצִיפָא</a></div>","alt":[]},"2888":{"h":"אָצַר","r":"A02888","html":"<div class=\"sense\"><i>to lock up, hoard, gather;</i> cmp. <a href=\"#\" data-headword=\"גָּנַז\">גָּנַז</a>. <span class=\"citation\">B. Bath. 90ᵇ</span> <span dir=\"rtl\">אוֹצְרֵי פירות</span> those who store up fruit (for speculation). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אין אוֹצְרִין וכ׳</span>; <span class=\"citation\">Tosef. Ab. Zar. IV</span> (<span class=\"citation\">V), 1</span> (<a href=\"#\" data-headword=\"אֲצַר I\">אצר</a> a. <span dir=\"rtl\">עצר</span> used promiscuously) you must not hoard up (for speculation) such things as are necessaries of life; [correct <span dir=\"rtl\">אין א׳ דברים שיש … כגון יינות שמנים וסלתות ופירות</span>]. Ib. <span dir=\"rtl\">לֶאֱצוֹר</span> (Tosef. <span dir=\"rtl\">לאַצֵּר</span> <i>Pi.</i>). Ib. <span dir=\"rtl\">לא יְאַצֵּר</span> <i>Pi.</i> (Tosef. <span dir=\"rtl\">ולא יַעֲצוֹר</span>, read <a href=\"#\" data-headword=\"לֹא\">לא</a>; Var. <span dir=\"rtl\">לא יַאֲצִיר</span>). <span class=\"citation\">Gen. R. s. 45</span> end (play on <span dir=\"rtl\">נבוכדרא̇צ̇ר̇</span>) <span dir=\"rtl\">שאֲצָרָן וכ׳</span> he locked them up in the desert &amp;c.—<span class=\"citation\">Y. Dem. VI, end, 26ᵃ</span>; <span class=\"citation\">Tosef. ib. VI, 4</span>; <span class=\"citation\">Ab. Zar. 71ᵃ</span> <a href=\"#\" data-headword=\"אוֹצָר\">אוֹצֵר</a> (<a href=\"#\" data-headword=\"עוֹצָר\">עוֹצֵר</a>) <i>government’s store-collector, commissary</i> (apothecarius), or read <a href=\"#\" data-headword=\"אוֹצָר\">אוֹצָר</a> q. v.</div><div class=\"sense\"><b>Pi. אִיצֵּר</b> </div><div class=\"sense\"><b>Hif. הֶאֱצִיר</b> <div class=\"sense\">, v. supra.</div></div>","alt":[]},"2889":{"h":"אֲצַר I","r":"A02889","html":"<div class=\"sense\"> *<span class=\"citation\">Targ. O. Gen. XLI, 35</span> <span dir=\"rtl\">וייצרון</span>, Var. <span dir=\"rtl\">ויוצרון</span>, <span dir=\"rtl\">ויצרון</span>). <span class=\"citation\">B. Bath. 90ᵇ</span> <span dir=\"rtl\">פוק אצר לי וכ׳</span> (prob. <a href=\"#\" data-headword=\"אֲצַר I\">אַצַּר</a> <i>Pa.</i></div><div class=\"sense\"><b>Ithpa. אִתְאַצַּר</b> </div><div class=\"sense\"><b>Ithpe. אִתְאֲצַר</b> <div class=\"sense\"><i>to be stored up</i>. <span class=\"citation\">Targ. Is. XXIII, 18</span>.</div></div>","alt":["אָצַר"]},"2890":{"h":"אַצָּר","r":"A02890","html":"<div class=\"sense\"> w. (<a href=\"#\" data-headword=\"אֲצַר I\">preced.</a>) <span dir=\"rtl\">אַצַּר פירי</span> <i>speculator in provision</i>. <span class=\"citation\">Yoma 83ᵃ</span>; <span class=\"citation\">B. Bath. 90ᵇ</span></div>","alt":[]},"2891":{"h":"אֲצַר II","r":"A02891","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אַצָּר\">preced.</a>) <i>contraction</i>(h. . <span class=\"citation\">Bekh. 21ᵇ</span> <span dir=\"rtl\">א׳ חיותא</span> contraction of the womb (and consequent destruction of the fœtus).</div>","alt":[]},"2892":{"h":"אֹצְרוֹת","r":"A02892","html":"<div class=\"sense\">, read <span dir=\"rtl\">אוֹצְרוֹת רוּחַ</span> (v. <a href=\"#\" data-headword=\"אוֹצָר\">אוֹצָר</a>) <i>stores of wind</i>, name of the cavities in the <i>pearl-shell</i> in which the pearls are seated, and which contain a kali; v. <a href=\"#\" data-headword=\"אַשְׁלְגָא\">אַשְׁלְגָא</a>. <span class=\"citation\">Y. Sabb. IX, end, 12ᵇ</span> top.</div>","alt":["א׳ רוח"]},"2893":{"h":"אַקְהָא","r":"A02893","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְוָוא\">אַקְוָוא</a></div>","alt":[]},"2894":{"h":"אַקְהָיוּתָא","r":"A02894","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קהי\">קהי</a>) <i>bluntness</i> or <i>looseness</i> of teeth. <span class=\"citation\">Targ. Amos IV, 6</span> (h. text <span dir=\"rtl\">נקיון וכ׳</span>) <span dir=\"rtl\">אקהיות שנין</span> = <i>perplexity</i>. Cmp. <a href=\"#\" data-headword=\"אַקְוָוא\">אַקְוָוא</a>.</div>","alt":[]},"2895":{"h":"*אַקּוּבִּיטוֹן","r":"A02895","html":"<div class=\"sense\">, m. (accubitum, ἀκκούβιτον) <i>dining couch</i> of the Roman nobility of the imperial period in place of the older triclinium. <span class=\"citation\">Lev. R. s. 7</span> <span dir=\"rtl\">מיסב על א׳ וכ׳</span> (Pesik. Eth. Korb. p. 61ᵃ <span dir=\"rtl\">הקוביטין</span>; Yalk. Num. 777 <span dir=\"rtl\">איק׳</span>; ib. Lev. 479 <a href=\"#\" data-headword=\"קוּבְּתָא\">קוב׳</a>, <span dir=\"rtl\">קנב׳</span>; ib. Ps. 791 הננ׳ &amp;c., corr. acc.; <span class=\"citation\">Pesik. R. s. 16</span>, p. 83ᵇ ed. Fr. <span dir=\"rtl\">הקובטין</span>) reclining on his accubitum.—<span dir=\"rtl\">לחם א׳</span>, or <a href=\"#\" data-headword=\"רִיפְתָּא\">ריפתא</a> (<a href=\"#\" data-headword=\"ד\">ד</a>)א׳ <i>bread used at the meals of the nobility, fine bread</i>. <span class=\"citation\">Targ. Y. II, Gen. XL, 16</span> <span dir=\"rtl\">ריפתא קקבטון</span> (read <span dir=\"rtl\">ריפתא דאקקובטון</span>) bread of the nobles (h. text <a href=\"#\" data-headword=\"חרי\">חרי</a>). Pesik. R. l. c. p. 82ᵃ (ref. to <span dir=\"rtl\">לחם הפחה</span> <span class=\"citation\">Neh. V, 18</span>) <span dir=\"rtl\">הקקבטין</span> sub. <a href=\"#\" data-headword=\"לָחַם I\">לחם</a>; Pesik. l. c. p. 59ᵃ <a href=\"#\" data-headword=\"קקבטון\">קקבטון</a> (corr. acc.).</div>","alt":["אַקְקוּבְטוֹן"]},"2896":{"h":"אקובנאה","r":"A02896","html":"<div class=\"sense\">, <span class=\"citation\">B. Bath. 73ᵃ</span> bot. Ar., v. <a href=\"#\" data-headword=\"קוּפְיָא\">קוּפְיָא</a> a. <a href=\"#\" data-headword=\"קוּבְנָאָה\">קוּבְנָאָה</a>; cmp. <a href=\"#\" data-headword=\"אֲקוּנְבִּי\">אֲקוּנְבִּי</a>.</div>","alt":[]},"2897":{"h":"אַקְוָוא","r":"A02897","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קהי\">קהי</a>) <i>what blunts or loosens the teeth, weakening;</i> fig. (v. Mekh. Bo 18, end) <i>refutation, arguments.</i> Pl. <a href=\"#\" data-headword=\"אַלְוָותָא\">אַקְוָותָא</a>. <span class=\"citation\">Yeb. 110ᵇ</span> <span dir=\"rtl\">יתבי וקמקוו א׳</span> (Rashi Var. <span dir=\"rtl\">מקהו אַקְהָתָא</span>) they were sitting and raising arguments. Cmp. <a href=\"#\" data-headword=\"אַקְהָיוּתָא\">אַקְהָיוּתָא</a>.</div>","alt":["אַקְהָא"]},"2898":{"h":"אקומוניס","r":"A02898","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיקוֹנוֹמוֹס\">אִיקוֹנוֹמוֹס</a></div>","alt":[]},"2899":{"h":"אָקוֹן","r":"A02899","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (deriv. of <span dir=\"rtl\">קנה</span>, v. <a href=\"#\" data-headword=\"אֲקַן\">אקן</a>) </div><div class=\"sense\"><b>1)</b> <i>reed-basket</i>, used as a <i>fisher’s cauf.</i> <span class=\"citation\">Kel. XII, 2</span>; <span class=\"citation\">XXIII, 5</span>.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"אֲקַן\">אֲקַן</a></div>","alt":[]},"2900":{"h":"אִקוֹנָא","r":"A02900","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אִיק׳</span></div>","alt":[]},"2901":{"h":"אֲקוּנְבִּי","r":"A02901","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">קבב</span>, with <a href=\"#\" data-headword=\"נ\">נ</a> inserted; Mand. <span dir=\"rtl\">קומבא</span>, Nöld. Mand. Gr. p. 105) <i>cupola, arched vessel. </i> Pl. <span dir=\"rtl\">אֲקוּנְבְּיָאוֹת</span>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 8</span> <span dir=\"rtl\">א׳ שבמגדלים</span> ed. Zuck. (Var. <span dir=\"rtl\">אקובנ׳</span>, cmp. <a href=\"#\" data-headword=\"קוּבְנָאָה\">קובנאה</a>) cupolas on turrets (a piece of house furniture), ornamental vases.</div>","alt":[]},"2902":{"h":"*אֲקוּנָס","r":"A02902","html":"<div class=\"sense\">, a corruption of <a href=\"#\" data-headword=\"קוֹלְיָיס\">קוֹלְיָיס</a> m. (κολίας) <i>colias</i>, name of a small fish. <span class=\"citation\">Ab. Zar. 39ᵃ</span>; <span class=\"citation\">Ḥull. 66ᵇ</span> top; <span class=\"citation\">Tosef. Ḥull. III</span> (<span class=\"citation\">IV), 27</span> <a href=\"#\" data-headword=\"קוֹלְיָיס\">קולייס</a>.</div>","alt":[]},"2903":{"h":"אַקּוּפֵי","r":"A02903","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַף I\">נקף</a>, <span dir=\"rtl\">קף</span>) <i>curlings of the web, anything sticking out of the web</i> (threads, knots &amp;c.). <span class=\"citation\">Sabb. 75ᵇ</span> <span dir=\"rtl\">האי מאן דשקיל א׳ וכ׳</span> whoever takes threads out of clothes on the Sabbath, is guilty of an act of finishing; v. <a href=\"#\" data-headword=\"פַּטִּישׁ\">פַּטִישׁ</a>. Cmp. <a href=\"#\" data-headword=\"אַקָּפוּתָא\">אַקָּפוּתָא</a>.</div>","alt":[]},"2904":{"h":"אקופיא","r":"A02904","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּפְיָא\">קופיא</a></div>","alt":[]},"2905":{"h":"אקורפיטא","r":"A02905","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְרַפְטָא\">אַקְרַפְטָא</a></div>","alt":[]},"2906":{"h":"אֲקוּרְקַרְתָּא","r":"A02906","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְרוֹקְתָּא\">אַקְרוֹקְתָּא</a></div>","alt":[]},"2907":{"h":"אָקוֹשָׁא","r":"A02907","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קשי\">קשי</a>) <i>hard, hard-baked</i>. <span class=\"citation\">Targ. Y. Lev. XX, 10</span>.—<span class=\"citation\">Keth. 39ᵇ</span>. <span class=\"citation\">Sot. 4ᵇ</span>, opp. <a href=\"#\" data-headword=\"רַכִּיךְ\">רכיכא</a>. <span class=\"citation\">Sabb. 65ᵃ</span> <span dir=\"rtl\">כל מידי א׳</span> anything hard.—Pl. <span dir=\"rtl\">אָקוֹשֵׁי</span>. <span class=\"citation\">Sabb. 155ᵃ</span> <span dir=\"rtl\">חרובין א׳</span> ed. (Ms. M. <span dir=\"rtl\">דאשוני</span>, Ar. <span dir=\"rtl\">דאשינא</span>).—<span class=\"citation\">Targ. Ps. LVIII, 10</span> <a href=\"#\" data-headword=\"אָקוֹשָׁא\">אָקוֹשָׁן</a> (some ed. <a href=\"#\" data-headword=\"אַנְשׁוּן\">אַקְשׁוּן</a>).</div>","alt":[]},"2908":{"h":"אַקְטוֹר","r":"A02908","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (actor) <i>actor publicus</i>, an officer who had the supervision of slaves and state property.—Pl. <span dir=\"rtl\">אַקְטוֹרִין</span>. Mekh. B’shall. Par. 1; <span class=\"citation\">Yalk. Ex. 230</span> <a href=\"#\" data-headword=\"*אימיקנטרון\">או׳</a>.—<span class=\"citation\">Targ. Y. Ex. XVI, 5</span> <span dir=\"rtl\">אוֹקְטָרַיָּא</span>.</div>","alt":["(אוקטור)"]},"2909":{"h":"אִקְטִיסְפּוֹן","r":"A02909","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ctesiphon</i>, a town on the Eastern bank of the Tigris. <span class=\"citation\">Targ. Y. Gen. X, 10</span> <a href=\"#\" data-headword=\"ק׳\">ק׳</a> (for Bibl. <i>Kalneh</i>). <span class=\"citation\">Yoma 10ᵃ</span> (for Bibl. <i>Resen</i>) <span dir=\"rtl\">זה א׳</span> (Ms. <span dir=\"rtl\">זו אקטספון</span>; Var. <span dir=\"rtl\">קטיספון</span>; <span dir=\"rtl\">טיספוס</span>). <span class=\"citation\">Gitt. 6ᵃ</span>. <span class=\"citation\">Erub. 57ᵇ</span> <span dir=\"rtl\">אקיסט׳</span> (corr. acc.; Ms. M. <span dir=\"rtl\">קטי׳</span>; v. Rabb. D. S. a. l. note).</div>","alt":["קְטִיסְפּוֹן"]},"2910":{"h":"אַקְטַרְתָּא","r":"A02910","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָטַר I\">קטר</a>) <i>whatever raises dense smoke when ignited</i>, hence <i>roots, twigs</i> &amp;c. <span class=\"citation\">Taan. 24ᵇ</span> bot. <span dir=\"rtl\">ושדייא א׳</span> (Ms. M. adds. <span dir=\"rtl\">בתנורא</span>; v. Rabb. D. S. a. l.) she used to throw twigs into the stove (to make people believe she was baking).</div>","alt":[]},"2911":{"h":"אקי","r":"A02911","html":"<div class=\"sense\">, read: <span dir=\"rtl\">אִיקִי</span> (εἶκε) <i>make room!</i> Y’lamd. to Deut. XI, 22 quot. in Ar. (v. Tanḥ. Ekeb, 4); cmp. <span class=\"citation\">Midr. Till. to Ps. XVII</span>.</div>","alt":[]},"2912":{"h":"אקיוס","r":"A02912","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְסְיוֹס\">אַקְסְיוֹס</a></div>","alt":[]},"2913":{"h":"אֲקִילוֹס","r":"A02913","html":"<div class=\"sense\"> (Var. <span dir=\"rtl\">עֲקִילוֹס</span>), pr. n. m. <i>Akilos</i> (prob. identic with <a href=\"#\" data-headword=\"עֲקִילַס\">עקילס</a> q. v.). <span class=\"citation\">Gen. R. s. 1</span> R. Yudan relates <span dir=\"rtl\">בשם א׳</span>.</div>","alt":[]},"2914":{"h":"אקיסטפון","r":"A02914","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִקְטִיסְפּוֹן\">אִקְטִיסְפּוֹן</a></div>","alt":[]},"2915":{"h":"אקיקא","r":"A02915","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲקַקְיָא\">אֲקַקְיָא</a></div>","alt":[]},"2916":{"h":"אַקְלַד","r":"A02916","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְלִידָא\">אַקְלִידָא</a> a. <a href=\"#\" data-headword=\"קְלַד\"><a href=\"#\" data-headword=\"קְלַד\">קְלַד</a>.</a></div>","alt":[]},"2917":{"h":"אַקְלִיבוּסְתָּא","r":"A02917","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְלִיבוֹסֶת\">קְלִיבוֹסֶת</a></div>","alt":[]},"2918":{"h":"אַקְלִידָא","r":"A02918","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (κλείς-δός) <i>key, lock, fastening</i>. <span class=\"citation\">Sabb. 89ᵇ</span> <span dir=\"rtl\">ככא דא׳</span> (Ar. s. v. <a href=\"#\" data-headword=\"קְלַד\">קלד</a>: <span dir=\"rtl\">בבא</span>, Var., v. Rabb. D. S. a. l. note 400) the tooth of the key, <i>key-bit</i> (Ar. ‘<i>the key-gate</i>’); <span class=\"citation\">Men. 57ᵃ</span>; a. e.—Fig. <span dir=\"rtl\">א׳ דמטרא</span> the key (to the store) of rain; <span dir=\"rtl\">א׳ דת&quot;המ</span> the key (to the gate) of resurrection. <span class=\"citation\">Snh. 113ᵃ</span> (Var. <span dir=\"rtl\">קלידא</span>, <a href=\"#\" data-headword=\"מַפְתְּחָא\">מפתחא</a>; v. Rabb. D. S. a. l. note 30).—Pl. <span dir=\"rtl\">אַקְלִידֵי</span>, <span dir=\"rtl\">אַקְלִידַיָּיא</span>. <span class=\"citation\">Targ. I Chr. IX, 27</span>.—<span class=\"citation\">Gitt. 56ᵃ</span>; a. fr.—Denom. <a href=\"#\" data-headword=\"אַקְלַד\">אַקְלַד</a>, v. <a href=\"#\" data-headword=\"קְלַד\">קְלַד</a>.</div>","alt":[]},"2919":{"h":"אקלנדס","r":"A02919","html":"<div class=\"sense\">, read <span dir=\"rtl\">קאלנדס</span>, v. <a href=\"#\" data-headword=\"קלנדא\">קַלֶּנְדָּא</a></div>","alt":[]},"2920":{"h":"אִקְּלַס","r":"A02920","html":"<div class=\"sense\"> Ithpe. of <a href=\"#\" data-headword=\"קְלַס\">קְלַס</a>.</div>","alt":[]},"2921":{"h":"אַקְלִפְרִין","r":"A02921","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (aquiliferi) <i>eagle-bearers, bearers of the imperial standard</i>. <span class=\"citation\">Midr. Till. to Ps. XLV</span> (some ed. <span dir=\"rtl\">אלק׳</span> corr. acc.).</div>","alt":[]},"2922":{"h":"אקמינון","r":"A02922","html":"<div class=\"sense\"> <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">א׳ פרנסין</span>, read <span dir=\"rtl\">אוקמינון</span>, v. <span dir=\"rtl\">קום</span>.</div>","alt":["אקמנין"]},"2923":{"h":"*אַקְמְתָא","r":"A02923","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">אקם</span> = <span dir=\"rtl\">עקם</span>, cmp. <span dir=\"rtl\">עכביש</span>, <a href=\"#\" data-headword=\"עַכּוֹבִיתָא I\">עכוביתא</a>; Syr. <span dir=\"rtl\">אמקתא</span>?, v. P. Sm. 243) <i>spider</i>. <span class=\"citation\">Targ. Prov. XXX, 28</span>.</div>","alt":[]},"2924":{"h":"אֲקַן","r":"A02924","html":"<div class=\"sense\"> (deriv. of <a href=\"#\" data-headword=\"קני\">קני</a>) <i>to grow in stalks, produce stalks</i> <span class=\"citation\">Gitt. 30ᵃ</span> <span dir=\"rtl\">לא צריכא דאָקוּן</span> (Var. <span dir=\"rtl\">דהדר ואקון</span>) in the case before us it means that the seeds which had been despaired off produced stalks (blades) again <span dir=\"rtl\">מהו דתימא אֲקַנְתָּא מילתא וכ׳</span> when you might think this shooting up is <i>something</i> (enough to awaken new hopes of recovery), therefore &amp;c.; <span class=\"citation\">Taan. 19ᵃ</span>.—Denom. <a href=\"#\" data-headword=\"אֲבַנְתָּא\">אֲקַנְתָּא</a> <i>growth of stalks;</i> v. supra.</div>","alt":[]},"2925":{"h":"אקנוס","r":"A02925","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיקָנוֹס\">אִיקָנוֹס</a> a. <a href=\"#\" data-headword=\"אַקְסְיוֹס\"><a href=\"#\" data-headword=\"אַקְסְיוֹס\">אַקְסְיוֹס</a>.</a></div>","alt":[]},"2926":{"h":"אַקְנָיָאתָא","r":"A02926","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְנָיָיתָא\">אַקְנָיָיתָא</a></div>","alt":[]},"2927":{"h":"*אַקְנָיוּתָא","r":"A02927","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (קני II) <i>being provoked</i>. <span class=\"citation\">Targ. I Sam. I, 16</span> (v. ib. v. 6).</div>","alt":[]},"2928":{"h":"אַקְנָיָיתָא","r":"A02928","html":"<div class=\"sense\">pl., <a href=\"#\" data-headword=\"הֲקְנָאָה\">הַקְנָאָה</a> h. f. (קני I) <i>giving possession</i>, whence <span dir=\"rtl\">שְׁטָרֵי אַ׳</span> or <span dir=\"rtl\">שְׁטַר ה׳</span> <i>an agreement by which one’s landed estate is mortgaged in the form of a sale from date</i>, independent of the loan to be consummated afterwards, so that at a certain date the creditor can claim the property, even if sold in the meantime, by referring to the priority of his purchase; <i>deed of transfer</i> (v. Bloch Civil-Process, p. 54, notes 5 a. 6 a. quot. ib.). <span class=\"citation\">B. Mets. 13ᵃ</span>; <span class=\"citation\">14ᵃ</span>; <span class=\"citation\">16ᵇ</span>. <span class=\"citation\">B. Bath. 172ᵃ</span> <span dir=\"rtl\">שטרא אקניאתא</span> (<span dir=\"rtl\">שטרי</span>, Ms. M. <i>ib</i>. a. <span class=\"citation\">B. Mets. 16ᵇ</span> <a href=\"#\" data-headword=\"אַקְנָיָיתָא\">אקנייתא</a> without <span dir=\"rtl\">שטר׳</span>).—אַקְנָיָיתָא בְּמָנֵי <i>transfers</i>, or <i>sales by symbolic delivery</i>, v. <a href=\"#\" data-headword=\"מָאן\">מָנָא</a>; whence <i>Aknayatha B’mané</i>, adaptation of the name of <i>a Babylonian festive time and fair</i> (cmp. <a href=\"#\" data-headword=\"יָרִיד\">יָרִיד</a>). <span class=\"citation\">Ab. Zar. 11ᵇ</span> Ms. M. a. oth. (ed. <span dir=\"rtl\">אקניתא בחנוני</span>, Var. <span dir=\"rtl\">אקניתיה</span>); [cmp. Y. ib. I, 39ᶜ where our w. seems to be rendered <a href=\"#\" data-headword=\"כָּנוֹנֵי\">כנוני</a>].</div>","alt":["אַקְנָיָאתָא"]},"2929":{"h":"אקניתא","r":"A02929","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְנָיָיתָא\">preced.</a></div>","alt":[]},"2930":{"h":"אקניקתא","r":"A02930","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲנַנְקָתָא\">אֲנַנְקָתָא</a></div>","alt":["אקנקיתא"]},"2931":{"h":"אָקְסִיגָרוֹן","r":"A02931","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אָכְסִיגָ׳</span></div>","alt":[]},"2932":{"h":"אַקְסְיוֹס","r":"A02932","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἄξιος) <i>worthy, adequate</i>. <span class=\"citation\">Gen. R. s. 46</span> ‘<i>I am God Shadday</i>’ (<span class=\"citation\">Gen. XVII, 1</span>) is translated by Aquila <span dir=\"rtl\">אקווס ואקנוס</span> Ar. (ed. <a href=\"#\" data-headword=\"אכסיוט\">אכסיוס</a>, <a href=\"#\" data-headword=\"אכסיוט\">אכסיוט</a>, corr. acc.) ἄξιος and (καὶ) ἵκανος, adequate and sufficient (competent); cmp. ibid. <span dir=\"rtl\">דייך וכ׳</span> it is sufficient for thee that I am thy protector.</div>","alt":["אַכְסְיוֹס"]},"2933":{"h":"אַקְסִיל","r":"A02933","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַקְסִילָאלִיאָיָין\">next w.</a></div>","alt":[]},"2934":{"h":"*אַקְסִילָאלִיאָיָין","r":"A02934","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (ξυλαλόη = ἀγάλλοχον) <i>pieces of bitter aloë-wood</i>. <span class=\"citation\">Targ. Ps. XLV, 9</span> Ar. (ed. <span dir=\"rtl\">אַקְסִיל אַלוּאוֹן</span> combine) (h. text <a href=\"#\" data-headword=\"אָהֳלוֹת\">אֲהָלוֹת</a>).</div>","alt":[]},"2935":{"h":"אַקְפָּדָה","r":"A02935","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">קפד</span>, Hif.) <i>getting excited, ebullition of temper, rashness</i>. <span class=\"citation\">Num. R. s. 10</span>; <span class=\"citation\">Y. Ned. I, 36ᵈ</span> bot. they make the vow of a nazir <span dir=\"rtl\">(<a href=\"#\" data-headword=\"ה׳\">ה׳</a>) <span dir=\"rtl\">מתוך א׳</span></span> inconsiderately. <span class=\"citation\">Y. Ab. Zar. IV, 44ᵃ</span>. <span class=\"citation\">Tosef. Gitt. VII</span> (<span class=\"citation\">V), 6</span> (opp. <span dir=\"rtl\">ברצון</span>). <span class=\"citation\">Y. Naz. I, end, 51ᶜ</span> <span dir=\"rtl\">הקפדן</span>, read: <span dir=\"rtl\">דָתָן …</span></div>","alt":["הַקְפָּדָה"]},"2936":{"h":"אַקָּפוּתָא","r":"A02936","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָקַף I\">נקף</a>, <span dir=\"rtl\">קף</span>) <i>curling the hair</i>. <span class=\"citation\">Targ. Is. III, 24</span>. Cmp. <a href=\"#\" data-headword=\"אַקּוּפֵי\">אַקּוּפֵי</a>.</div>","alt":[]},"2937":{"h":"אקקבטון","r":"A02937","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַקּוּבִּיטוֹן\">אַקּוּבִּיטוֹן</a></div>","alt":["אקקוביטון"]},"2938":{"h":"*אֲקַקְיָא","r":"A02938","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἀκακία) <i>the thorny acacia</i>. <span class=\"citation\">Gitt. 69ᵇ</span> Ar. (ed. <a href=\"#\" data-headword=\"אקיקא\">אקיקא</a>, corr. acc.).</div>","alt":[]},"2939":{"h":"אַקְרָא","r":"A02939","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (dialect. for <a href=\"#\" data-headword=\"חַקְרָא\">חַקְרָא</a> in Yer. dial. q. v.; cmp. var. lect. bel.) <i>fort</i>, designation of various, mostly Babyl. places. <span class=\"citation\">Meg. 6ᵃ</span> <span dir=\"rtl\">א׳ דתולבקני</span> (Ms. Oxf., L., F. <span dir=\"rtl\">עקרא</span>; v. Rabb. D. S. a. l. note); <span class=\"citation\">Kidd. 71ᵇ</span>, v. <a href=\"#\" data-headword=\"תּוּלְבַּקְנֵי\">תולבקני</a>. [Rashi: <i>fortified ford</i>.] <span class=\"citation\">B. Bath. 127ᵃ</span>, <span class=\"citation\">Kidd. 72ᵃ</span>, v. <a href=\"#\" data-headword=\"אַגְמָא\">אַגְמָא</a>. <span class=\"citation\">B. Mets. 86ᵃ</span> <span dir=\"rtl\">מא׳ לאגמא</span> from Fort (Agma) to Agma (Var. lect. v. Rabb. D. S. a. l.). <span class=\"citation\">B. Bath. 73ᵇ</span>, v. <a href=\"#\" data-headword=\"הַגְרוֹנְיָא\">הגרוניא</a>. <span class=\"citation\">Macc. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"סְלִיקוֹס\">סְלִיקוֹס</a>; a. fr. [The Gr. ἄκρα, orig. <i>summit</i>, is a phonetic coincidence.]</div>","alt":[]},"2940":{"h":"אֶקְרָאִי","r":"A02940","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">קרא</span>, <a href=\"#\" data-headword=\"קרי ³\">קרה</a>; h. <i>accidental, chance</i>. <span class=\"citation\">R. Hash. 29ᵇ</span> <span dir=\"rtl\">בית דינא דא׳</span> improvized court. <span class=\"citation\">Snh. 25ᵇ</span>, a. fr. <span dir=\"rtl\">א׳ בעלמא</span> a mere chance.</div>","alt":[]},"2941":{"h":"אקרופיטא","r":"A02941","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַקְרַפְטָא\">אַקְרַפְטָא</a></div>","alt":[]},"2942":{"h":"אַקְרוֹקְתָּא","r":"A02942","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קַרְקַר\">קרקר</a>) [<i>croaker</i>,] <i>frog</i>. <span class=\"citation\">B. Bath. 73ᵇ</span> <a href=\"#\" data-headword=\"א׳\">א׳</a> (Var. <a href=\"#\" data-headword=\"אֲקוּרְקַרְתָּא\">אקורקרתא</a>, &amp;c., v. Rabb. D. S. a. l. note 3) <span dir=\"rtl\">דהויא כי וכ׳</span> a frog as big as Fort Hag. (others read <span dir=\"rtl\">בי</span>, a frog which was in Fort H.). <span class=\"citation\">Ned. 41ᵃ</span> <span dir=\"rtl\">עקרבא דיתיבא על א׳ ועברה נהרא</span> (corr. ed. acc.) a scorpion sitting on a frog and crossing the river.</div>","alt":[]},"2943":{"h":"אַקְרַפְטָא","r":"A02943","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κράβατος, grabatus) <i>couch, raised upholstered seat</i>. <span class=\"citation\">M. Kat. 10ᵇ</span> למבני א׳ Ar. (ed. <span dir=\"rtl\">אקרפיטא</span>, Ms. M. <span dir=\"rtl\">אקרפיטרא</span>) to build up a raised seat (on a frame). [Rashi: <a href=\"#\" data-headword=\"אקרופיטא\">אקרופיטא</a> <i>crib</i>.] <span class=\"citation\">Kidd. 70ᵃ</span> <span dir=\"rtl\">ליתיב מר אקר׳</span> sit down, Sir, on the couch; (cmp. <a href=\"#\" data-headword=\"אִיסְתִּירָא\">אִיצְטְבָא</a>, the Chald. equivalent of our w.).</div>","alt":["קְרַפְטָא","קַרְפִּיטָא"]},"2944":{"h":"אֲרָא","r":"A02944","html":"<div class=\"sense\"><i>to treat, argue</i>, v. <a href=\"#\" data-headword=\"ארי\">ארי</a>.</div>","alt":[]},"2945":{"h":"ארא","r":"A02945","html":"<div class=\"sense\"><i>fowler</i>, v. <a href=\"#\" data-headword=\"אָדָא IV\"><span dir=\"rtl\">אָדָא</span> IV</a>.</div>","alt":[]},"2946":{"h":"*ארא","r":"A02946","html":"<div class=\"sense\"> (Ms. M. <span dir=\"rtl\">ניר׳</span>; Ar. s. v. <span dir=\"rtl\">פלמודא</span>: <a href=\"#\" data-headword=\"פדא\">פדא</a> or <a href=\"#\" data-headword=\"פרא\">פרא</a>) name of a <i>fish</i> or <i>fish-brine;</i> perh. <span dir=\"rtl\">אֲרָאיָא</span> (<i>Raia</i>) <i>ray</i> or <i>skate</i>. <span class=\"citation\">Ab. Zar. 40ᵃ</span></div>","alt":["ארא׳"]},"2947":{"h":"אֶרְאֵל","r":"A02947","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Is. XXXIII, 7</span>, <i>messenger</i>, esp. (in poetry) <i>angel.</i> Pl. <span dir=\"rtl\">אֶרְאֵלִים</span>. <span class=\"citation\">Keth. 104ᵃ</span> <span dir=\"rtl\">א׳ ומצוקים וכ׳</span> the Erelim (angels) and the mortals seized the holy ark (strove for the soul of R. Judah); <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> top <span dir=\"rtl\">יצוקים וא׳</span>; <span class=\"citation\">Y. Keth. XII, 35ᵃ</span>; <span class=\"citation\">Koh. R. to VII, 11</span>; <span class=\"citation\">IX, 10</span>; v. <a href=\"#\" data-headword=\"יָצַק\">יָצַק</a>, <a href=\"#\" data-headword=\"מָצַּק\">מָצַק</a>.</div>","alt":[]},"2948":{"h":"אראני","r":"A02948","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲרוֹנֵי\">אֲרוֹנֵי</a></div>","alt":[]},"2949":{"h":"אָרַב","r":"A02949","html":"<div class=\"sense\"><b>1)</b> <i>to press into holes, to make holes; to weave; join</i>. </div><div class=\"sense\"><b>2)</b> <i>to look through a hole, to espy, lurk, lie in wait</i>. <span class=\"citation\">B. Kam. 44ᵇ</span>, a. e. (ref. to <span class=\"citation\">Deut. XIX, 11</span>) <span dir=\"rtl\">וא׳ לו וכ׳</span> it says ‘And he lurks for <i>him</i>’ &amp;c., that means the intention to kill <i>that</i> man.—Denom. <a href=\"#\" data-headword=\"אֲרוּבָּה\">ארובה</a>, <a href=\"#\" data-headword=\"אוּרְבָּא\">אורבא</a>, <span dir=\"rtl\">ארבל׳</span>, <a href=\"#\" data-headword=\"אַרְבָּא I\">ארבא</a>, <a href=\"#\" data-headword=\"אֲרַבְתָּא\">ארבתא</a>.</div>","alt":[]},"2950":{"h":"*אֲרַב","r":"A02950","html":"<div class=\"sense\">, part. <a href=\"#\" data-headword=\"אָרְבָּא\">אָרְבָּא</a> <i>lurking</i>. <span class=\"citation\">B. Mets. 101ᵇ</span>; <span class=\"citation\">B. Kam. 85ᵃ</span>; <span class=\"citation\">B. Bath. 168ᵃ</span> thou appearest to me <span dir=\"rtl\">כאריא א׳</span> like a lurking lion, i.e. I have no confidence in thee.</div>","alt":[]},"2951":{"h":"אַרְבָּא I","r":"A02951","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ארב <i>to join</i>, cmp. <a href=\"#\" data-headword=\"אַרְגִּיז\">ארגז</a>, <span dir=\"rtl\">תיבה</span>) <i>boat</i>. <span class=\"citation\">B. Mets. 101ᵇ</span> <span dir=\"rtl\">א׳ דחמרא</span> a boat-load of wine; a. fr.—<span class=\"citation\">Gitt. 6ᵃ</span>; <span class=\"citation\">Kidd. 72ᵃ</span> א׳ תנייתא וכ׳ Ar. ed. Koh. (ed. <a href=\"#\" data-headword=\"תִּנְיָין\">תניינא</a>) to the second boat of the (floating) bridge; cmp. Kidd. l. c. <span dir=\"rtl\">והאידנא וכ׳</span> ‘and now the Persians placed the bridge higher up’. [Oth. opin., v. <a href=\"#\" data-headword=\"אֲרַבְתָּא\">אֲרַבְתָּא</a>.]—Pl. <a href=\"#\" data-headword=\"רְבֵי\">אַרְבֵּי</a>. <span class=\"citation\">B. Mets. 72ᵇ</span> <span dir=\"rtl\">חיטי … וא׳</span> the wheat in granaries and ships.</div>","alt":[]},"2952":{"h":"*אַרְבָּא II","r":"A02952","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a small silver vessel in the shape of a trough</i> (= <a href=\"#\" data-headword=\"עֲרֵיבָה\">עֲרֵיבָה</a> Ar.) <span class=\"citation\">B. Bath. 34ᵇ</span> (Comm.: <i>ship</i>).</div>","alt":[]},"2953":{"h":"אָרְבָּא","r":"A02953","html":"<div class=\"sense\"><i>layer, mesh</i>, v. <a href=\"#\" data-headword=\"אוּרְבָּא\">אוּרְבָּא</a>.</div>","alt":[]},"2954":{"h":"אָרְבָּא ²","r":"A02954","html":"<div class=\"sense\"><i>lurking</i>, v. <a href=\"#\" data-headword=\"*אֲרַב\">אֲרַב</a>.</div>","alt":[]},"2955":{"h":"אֲרָבָאֵי","r":"A02955","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>Arabs</i>. <span class=\"citation\">Targ. II Chr. XVII, 11</span> (ed. Beck; oth. <a href=\"#\" data-headword=\"עֲרָבָאָה\">עֲרָבָאֵי</a>).</div>","alt":[]},"2956":{"h":"אַרְבֶּה I","r":"A02956","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>locust</i>(also collect.). <span class=\"citation\">Ex. R. s. 13</span>; a. fr. V. <a href=\"#\" data-headword=\"כּוֹבֵשׁ\">כּוֹבֵשׁ</a>.</div>","alt":[]},"2957":{"h":"אַרְבֶּה II","r":"A02957","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"הַרְבָּה\">הַרְבָּה</a></div>","alt":[]},"2958":{"h":"*אַרְבּוּנָא","r":"A02958","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארב</span>, cmp. <span dir=\"rtl\">ערב</span>) <i>confounding of colors, thickness</i>, whence <i>feeble sight</i>. <span class=\"citation\">Pes. 111ᵇ</span> the following three things <span dir=\"rtl\">יהיבי א׳ וכ׳</span> (Ms. Oxf. <span dir=\"rtl\">עוורונא</span>; Ms. M. v. Rabb. D. S. a. l.) cause defective eye-sight.</div>","alt":[]},"2959":{"h":"אַרְבֵּילָא","r":"A02959","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְבְּלָא\">אַרְבְּלָא</a></div>","alt":[]},"2960":{"h":"אַרְבֵּיסַר","r":"A02960","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְבְּעָה\">אַרְבְּעָה</a> end.</div>","alt":[]},"2961":{"h":"אַרְבֵּל I","r":"A02961","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Arbel, Arbela</i>, in Galilee, near Zepphoris. <span class=\"citation\">Y. Ber. I, 2ᶜ</span> <span dir=\"rtl\">בקעת א׳</span> the Valley of Ar.; <span class=\"citation\">Y. Taan. IV, 69ᵇ</span> <a href=\"#\" data-headword=\"ארכל\">ארכל</a> (corr. acc.). <span class=\"citation\">Y. Shebi. VI, 36ᵈ</span> bot. <span class=\"citation\">Koh. R. to I, 18</span> coarse linen <span dir=\"rtl\">הבאין מא׳</span> coming from A.; a. e.</div>","alt":[]},"2962":{"h":"אַרְבֵּל II","r":"A02962","html":"<div class=\"sense\"> (denomin. of <a href=\"#\" data-headword=\"אַרְבְּלָא\">next w.</a>, v. <a href=\"#\" data-headword=\"עַרְבֵּל\">עַרְבֵּל</a>) <i>to sift, shake</i>. <span class=\"citation\">B. Mets. 26ᵇ</span> דאייתי ארבלא ומְאַרְבֵּל Ar. (Ms. R. 2 <span dir=\"rtl\">מארביל</span>, ed. <span dir=\"rtl\">וקא מַרְבֵּל</span> = <span dir=\"rtl\">מארבל</span>) that he brought a sieve and sifted the sand. <span class=\"citation\">Snh. 39ᵃ</span> וקמרבלינהו Ms. M. (ed. Sonc. <span dir=\"rtl\">וקא מא׳ להו</span>, oth. ed. <span dir=\"rtl\">מהדר להו</span>) and shook them.</div><div class=\"sense\"><b>Ithpe. אִירְבֵּל</b> <div class=\"sense\"> (= <span dir=\"rtl\">איתארבל</span>) <i>to be shaken</i>. <span class=\"citation\">Ḥull. 49ᵃ</span> <span dir=\"rtl\">מירבל הוא דרְבִיל</span> it was shaken down (by the movements of the animal). [Targ. <a href=\"#\" data-headword=\"עַרְבֵּל\">עַרְבֵּל</a>.]</div></div>","alt":["(רְבַל)"]},"2963":{"h":"אַרְבְּלָא","r":"A02963","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארב</span>, cmp. <a href=\"#\" data-headword=\"אֲרוּבָּה\">אֲרוּבָּה</a>) <i>net work, sieve</i>. <span class=\"citation\">B. Mets. 26ᵇ</span>; <span class=\"citation\">Snh. 39ᵃ</span>, v. preced.—<span class=\"citation\">Macc. 20ᵇ</span> <span dir=\"rtl\">בארבילא</span> (Ms. M. <span dir=\"rtl\">בארבי</span>); <span class=\"citation\">Snh. 89ᵇ</span> <span dir=\"rtl\">אכיל תמרא בא׳</span> ate dates out of the sieve, i.e. did a harmless thing.—<span class=\"citation\">Targ. Amos IX, 9</span> <span dir=\"rtl\">ערבלא</span>.—V. <a href=\"#\" data-headword=\"עַרְבְּלָאִין\">עַרְבְּלָאִין</a>.</div>","alt":["אַרְבֵּילָא","עַרְבְּלָא"]},"2964":{"h":"אַרְבֵּלִי","r":"A02964","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (אַרְבֵּל I) <i>a native or resident of Arbel, Arbelite</i>. <span class=\"citation\">Ab. I, 6</span>.—Pl. <span dir=\"rtl\">אַרְבֵּלִיִּין</span>. <span class=\"citation\">Gen. R. s. 19</span>, beg.; cmp. <span class=\"citation\">Koh. R. to I, 18</span>.—[<span class=\"citation\">Tosef. Par. XII</span> (<span class=\"citation\">XI), 16</span> <span dir=\"rtl\">כוש הא׳</span>, v. next w.]—Fem. <a href=\"#\" data-headword=\"אַרְבֵּלִי\">אַרְבֵּלִית</a>. <span class=\"citation\">Y. Peah VII, 20ᵃ</span> bot.; <span class=\"citation\">Y. Sot. I, 17ᵇ</span>; IX, 24ᵇ bot. <span dir=\"rtl\">סאה א׳</span> one S’ah of Arbelite wheat. [Ib. IV, end, 19ᵈ top <span dir=\"rtl\">רבי מר עוקבא הורה בארבלי</span> <i>Arbeli</i>, supposed to be a place in Babylon. The entire sentence is spurious both from Mar Ukba’s title of Rabbi as well as from comparison with <span class=\"citation\">Keth. 60ᵇ</span>.]</div>","alt":[]},"2965":{"h":"אָרְבָּן","r":"A02965","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ארב 1) <i>coarse weft</i>, opp. to <span dir=\"rtl\">פשתין</span> fine flax woof. <span class=\"citation\">Parah XII, 8</span> <span dir=\"rtl\">כוש של א׳</span> (Var. <a href=\"#\" data-headword=\"רוֹבָן\">רוֹבָן</a>) the spindle used for spinning coarse material; [Tosef. ib. XII (XI) 16 <span dir=\"rtl\">כוש הארבלי</span> the spindle used at Arbel; cmp. <span class=\"citation\">Koh. R. to I, 18</span> s. v. <a href=\"#\" data-headword=\"אַרְבֵּל I\"><span dir=\"rtl\">אַרְבֵּל</span> I</a>].</div>","alt":[]},"2966":{"h":"אָרְבָּנָא","r":"A02966","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אוּרְבָּנָא\">אוּרְבָּנָא</a></div>","alt":[]},"2967":{"h":"אַרְבֵּסְרָאָה","r":"A02967","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְבְּעָה\">אַרְבְּעָה</a></div>","alt":[]},"2968":{"h":"אַרְבַּע","r":"A02968","html":"<div class=\"sense\"><i>four</i>, v. <a href=\"#\" data-headword=\"אַרְבָּעָה I\"><span dir=\"rtl\">אַרְבָּעָא</span> I</a> a. <a href=\"#\" data-headword=\"אַרְבְּעָה\"><a href=\"#\" data-headword=\"אַרְבְּעָה\">אַרְבְּעָה</a>.</a></div>","alt":[]},"2969":{"h":"אַרְבְּעָא","r":"A02969","html":"<div class=\"sense\"><i>couching</i>, v. <a href=\"#\" data-headword=\"*אַרְבָּעָה II\"><span dir=\"rtl\">אַרְבָּעָה</span> II</a>.</div>","alt":[]},"2970":{"h":"אַרְבָּעָה I","r":"A02970","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"אַרְבַּע\">אַרְבַּע</a> f. (b. h.) <i>four</i> (frequently represented by <a href=\"#\" data-headword=\"ד׳\">ד׳</a>). <span class=\"citation\">Ḥag. 14ᵇ</span> <span dir=\"rtl\">א׳ נכנסו וכ׳</span> four men entered into theosophical speculation; a. fr.—Constr. <span dir=\"rtl\">אַרְבַּעַת</span> followed by singul. <span class=\"citation\">Y. Ber. I, 2ᶜ</span> <span dir=\"rtl\">אַרְבַּעַת מיל</span> = <span dir=\"rtl\">אַרְבָּעָה מילין</span>; <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span>; (cmp. <span class=\"citation\">Gen. R. s. 50</span>).—Pl. <span dir=\"rtl\">אַרְבָּעִים</span> (<a href=\"#\" data-headword=\"מ׳\">מ׳</a>) <i>forty</i>. <span class=\"citation\">Sabb. VII, 2</span> <span dir=\"rtl\">א׳ חסר אחת</span> thirty nine.—<span class=\"citation\">Macc. I, 1</span>, a. fr. <span dir=\"rtl\">לוקה א׳</span> receives forty (thirty nine) lashes; v. <span class=\"citation\">ib. III, 10</span>.</div>","alt":[]},"2971":{"h":"אַרְבְּעָה","r":"A02971","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XIV, 9</span>; a. fr.—Constr. a) <a href=\"#\" data-headword=\"אַרְבְּעָא\">אַרְבְּעַת</a> Targ. Y. ibid.—b) <span dir=\"rtl\">אַרְבְּעֵי</span>, <a href=\"#\" data-headword=\"אַרְבְּעִיתָא\">אַרְבַּעְתֵּי</a> <span class=\"citation\">Sabb. 73ᵃ</span> (omitting the object numbered); a. fr.—<span class=\"citation\">Targ. Y. Num. II, 3</span>; a. fr.—Y. Gitt. V, 46ᵈ top <span dir=\"rtl\">ארבעתי דינרייא</span> four denars—<a href=\"#\" data-headword=\"אַרְבְּעִיתָא\">אַרְבַּעְתָּא</a>, <a href=\"#\" data-headword=\"אַרְבְּעִיתָא\">אַרְבְּעִיתָא</a> m. <i>the fourth</i> (day of the week). <span class=\"citation\">Gen. R. s. 11</span>; <span class=\"citation\">Pesik. R. s. 23</span>, beg. Ibid. p. 120ᵃ ed. Fr. <span dir=\"rtl\">ארבעיא</span>, ed. Prag <a href=\"#\" data-headword=\"אַרְבְּעִיתָא\">ארבעיתא</a>. Ibid. p. 115ᵇ <span dir=\"rtl\">באַרְבַּעְתָּה</span> on Wednesday.—Pl. <span dir=\"rtl\">אַרְבְּעִין</span> <i>forty</i>. <span class=\"citation\">Targ. Gen. V, 13</span>; a. fr.—<span class=\"citation\">Snh. 26ᵇ</span> <span dir=\"rtl\">א׳ בכתפיה</span> forty (lashes) rest on his shoulders, i.e. he is punishable (v. <a href=\"#\" data-headword=\"אַרְבָּעָה I\">preced.</a>); a. fr.—<a href=\"#\" data-headword=\"אַרְבֵּיסַר\">אַרְבֵּיסַר</a>, <span dir=\"rtl\">אַרְבַּעְסְרֵי</span>, <span dir=\"rtl\">אַרְבַּע סְרֵי</span> <i>fourteen, fourteenth</i>. <span class=\"citation\">Targ. Y. Gen. XIV, 5</span> <span dir=\"rtl\">בּירְבֵּיסְרֵי</span>; a. fr. <span class=\"citation\">Meg. 2ᵇ</span> <span dir=\"rtl\">בא׳</span> on the fourteenth of Adar. <span class=\"citation\">Sabb. 98ᵇ</span>.—אַרְבֵּסְרָאָה <i>the fourteenth</i>. <span class=\"citation\">Targ. I Chr. XXIV, 13</span>.</div>","alt":["אַרְבַּע"]},"2972":{"h":"*אַרְבָּעָה II","r":"A02972","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רבע</span>) <i>couching</i>. <span class=\"citation\">Targ. Is. VII, 25</span>; <span class=\"citation\">LXV, 10</span> <a href=\"#\" data-headword=\"אֶבֶן\">בית א׳</a> (Var. <a href=\"#\" data-headword=\"אַרְבְּעָא\">אַרְבְּעָא</a>, <a href=\"#\" data-headword=\"רִבּוּעַ\">רִבּוּעָא</a>) couching place (for animals).</div>","alt":[]},"2973":{"h":"אַרְבְּעִיתָא","r":"A02973","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְבְּעָה\">אַרְבְּעָה</a></div>","alt":["אַרְבַּעְתָּא","אַרְבַּעְתָּה"]},"2974":{"h":"אֲרַבְתָּא","r":"A02974","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ארב</span>, h. , b. h. <a href=\"#\" data-headword=\"עֲרָבִי\">עֲרָבִים</a> pl.) [<i>the thickly interwoven</i>,] <i>willow</i>. <span class=\"citation\">Pes. 111ᵇ</span> טולא דא׳ Ms. M., Ar. (v. Rabb. D. S. a. l.; ed. <a href=\"#\" data-headword=\"עָמִירָא\">עֲ׳</a>) the shade of a willow-tree.—Pl. <a href=\"#\" data-headword=\"אֲרַבְתָּא\">אַרְבָּתָא</a>. <span class=\"citation\">Sabb. 20ᵇ</span> (Ar. <span dir=\"rtl\">אַרְבָּאתָא</span>; Mss. <a href=\"#\" data-headword=\"עִזְגַּד\">עַ׳</a>). [<span class=\"citation\">Gitt. 6ᵃ</span>; <span class=\"citation\">Kidd. 72ᵃ</span> <span dir=\"rtl\">ארבא וכ׳</span> the second willow after crossing the bridge; v., however, <a href=\"#\" data-headword=\"אַרְבָּא I\"><span dir=\"rtl\">אַרְבָּא</span> I</a>.] V. <a href=\"#\" data-headword=\"עַרְבָא I\"><span dir=\"rtl\">עַרְבָא</span> I</a>, II a. <a href=\"#\" data-headword=\"עֲרַבְתָּא\">עֲרַבְתָּא</a>.</div>","alt":["אַרְבָּא"]},"2975":{"h":"אָרָג","r":"A02975","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"אֲרַג\">אֲרַג</a> m. (v. <a href=\"#\" data-headword=\"רְגַג\">רגג</a>, h. <a href=\"#\" data-headword=\"עָרַג\">ערג</a>) <i>something desirable</i> … <span dir=\"rtl\">שפר א׳</span> the choicest of … <span class=\"citation\">Targ. Ps. XLV, 14</span>. <span class=\"citation\">Targ. Y. Gen. XLV, 18</span>.</div>","alt":[]},"2976":{"h":"אָרַג","r":"A02976","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">ארב</span>; cmp. <a href=\"#\" data-headword=\"חוֹרֵג\">חרג</a>) <i>to plait, braid, weave</i>. <span class=\"citation\">Sabb. VII, 2</span> <span dir=\"rtl\">האוֹרֵג</span> he who weaves on the Sabbath; a. fr.—Metaph. (cmp. <a href=\"#\" data-headword=\"טרי\">טרי</a>) <i>to argue, conclude, spin out, deduct</i> &amp;c. Ruth R., Par. 2, beg. (play on <i>or’gim</i> <span class=\"citation\">II Sam. XXI, 19</span>) they brought a subject up <span dir=\"rtl\">והוא אוֹרְגָהּ</span> and he carried it to a conclusive decision. Ib. <span dir=\"rtl\">שהיו אוֹרְגִין עמו</span> they argued with him.—<span class=\"citation\">Num. R. s. 4</span> (play on <i>argaman</i>, purple) <span dir=\"rtl\">שהוא היה א̇ור̇ג̇ … מ̇ן̇ וכ׳</span> for it (the purple-covered altar) argued Israel free from sin (pleaded in his behalf). <span class=\"citation\">Num. R. s. 12</span> (same play on the word) <span dir=\"rtl\">והוא אורג וכ׳</span> and He wove (planned) the world so that all creatures should come forth each according to its kind. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">א׳ מַן</span> the Sun weaves (ripens) food.</div><div class=\"sense\"><b>Nif. נֶאֱרַג</b> <div class=\"sense\"><i>to be woven</i>. Y. Ter. XI, end, 48ᵇ. <span class=\"citation\">Ex. R. s. 50</span>; a. fr.</div></div><div class=\"sense\"><b>*. אִירֵג</b> <div class=\"sense\">, part. <span dir=\"rtl\">מְאָרֵג</span> (cmp. <a href=\"#\" data-headword=\"עֲרוּגָה\">עֲרוּגָה</a>) <i>to follow the grooves of</i> the garden bed, <i>to range</i>, esp. <i>to select the green and tender onions</i> (v. <a href=\"#\" data-headword=\"חָלַק\">חָלַק</a> Hif.). <span class=\"citation\">Tosef. Peah I, 9</span> <span dir=\"rtl\">המארג</span>, quoted in Y. ib. III, 17ᶜ top <span dir=\"rtl\">המירוג</span> (corr. acc.; v. <a href=\"#\" data-headword=\"מֵירוּג\">מֵירוּג</a>) a. explained ibid. <span dir=\"rtl\">המחליק וכ׳</span> he who takes out the green onions for sale and leaves the others to ripen for storage.</div></div>","alt":[]},"2977":{"h":"אֲרַג","r":"A02977","html":"<div class=\"sense\"><span class=\"citation\">Snh. 48ᵇ</span> <span dir=\"rtl\">וא׳ בגד וכ׳</span> and where they weave a garment (directly) for a corpse.</div>","alt":[]},"2978":{"h":"אַרְגְּוָאנָא","r":"A02978","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְגְּוָון\">אַרְגְּוָון</a></div>","alt":[]},"2979":{"h":"אַרְגֹּוב","r":"A02979","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><b>1)</b>  pr. n. m. (b. h. <span dir=\"rtl\">ארגב</span>) <i>Argob</i>. <span class=\"citation\">Targ. II Kings XV, 25</span>.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"טְרָכוֹנָא\">טְרָכוֹנָּא</a></div>","alt":[]},"2980":{"h":"אַרְגּוּבְלָא","r":"A02980","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= b. h. <a href=\"#\" data-headword=\"גִּבְלִית\">גִּבְלִים</a>) <i>Giblean</i> (v. <a href=\"#\" data-headword=\"גְּבָל\">גְּבָל</a>); <i>master-mason.</i> Pl. <a href=\"#\" data-headword=\"אַרְגּוּבְלָא\">אַרְגּוּבְלַיָּא</a>. <span class=\"citation\">Targ. I Kings V, 32</span> (h. text <span dir=\"rtl\">גבלים</span>); <span class=\"citation\">II Kings XII, 13</span> (h. text <span dir=\"rtl\">גֹּדְרִים</span>). Cmp. <a href=\"#\" data-headword=\"אַרְדִּיכָל\">אַרְדִּיכָל</a>.</div>","alt":[]},"2981":{"h":"אַרְגְּוָון","r":"A02981","html":"<div class=\"sense\">(also … <span dir=\"rtl\">גְּוָנ׳</span>) = b. h. <a href=\"#\" data-headword=\"אַרְגָּמָן\">אַרְגָּמָן</a> <i>purple</i> (<i>garment</i>). <span class=\"citation\">Dan. V, 7</span>; a. e.—<span class=\"citation\">Targ. Ex. XXV, 4</span>; a. e.—<span class=\"citation\">Tam. 32ᵃ</span> <span dir=\"rtl\">לבישין דא׳</span> purple garments.—Pl. <span dir=\"rtl\">אַרְגְּוָונִים</span>. <span class=\"citation\">Pesik. R. s. 33</span>.—<span dir=\"rtl\">אַרְגְּוָונוֹת</span>. <span class=\"citation\">Lam. R. to III, 19</span> <span dir=\"rtl\">א׳ טובות</span> fine purple dresses (for females).</div>","alt":["אַרְגְּוָונָה","אַרְגְּוָון","אַרְגְּוָונָא"]},"2982":{"h":"ארגוטרייא","r":"A02982","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְגֶּנְטָרְיָא\">אַרְגֶּנְטָרְיָא</a></div>","alt":[]},"2983":{"h":"אַרְגְּוָן","r":"A02983","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְגְּוָון\">אַרְגְּוָו׳</a></div>","alt":["אַרְגְּוָנָא"]},"2984":{"h":"אַרְגָּז","r":"A02984","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> r. <span dir=\"rtl\">ארג</span> with format. <a href=\"#\" data-headword=\"ז\">ז</a>; cmp. <a href=\"#\" data-headword=\"אֲרַבְתָּא\">אַרְבָּא</a>) <i>box, chest</i> (joined with tenons &amp;c.). <span class=\"citation\">Num. R. s. 4</span>; <span class=\"citation\">Hor. 12ᵃ</span>; a. e.—<span class=\"citation\">Snh. 46ᵇ</span> <i>kabor</i> (to bury, cover) might mean only <span dir=\"rtl\">דעבד א׳ וכ׳</span> Ms. F. a. Ar. (Var. <a href=\"#\" data-headword=\"אַרְזָג\">ארזג</a>, ed. <a href=\"#\" data-headword=\"אָרוֹן\">ארון</a>) one makes a chest and puts the corpse in. [Pr. n. pl. v. <a href=\"#\" data-headword=\"אַרְגִּיז\">אַרְגִּיזָא</a>.]</div>","alt":[]},"2985":{"h":"*אַרְגָּזָא","r":"A02985","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְגַז I\">רגז</a>) <i>provocation, evil deed</i>. <span class=\"citation\">Targ. Ezek. XX, 28</span> <span dir=\"rtl\">א׳ קורבניהון</span> (prob. to be corr. <a href=\"#\" data-headword=\"אַרְגָּזוּתָא\">אַרְגָּזוּת</a>, v. <a href=\"#\" data-headword=\"אַרְגָּזוּתָא\">next w.</a>).</div>","alt":[]},"2986":{"h":"אַרְגָּזוּתָא","r":"A02986","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"*אַרְגָּזָא\">same</a>. <span class=\"citation\">Targ. I Kings XXI, 22</span>; <span class=\"citation\">XV, 30</span>.</div>","alt":["אַרְגְּזָיוּתָא"]},"2987":{"h":"אֶרְגָּטִיס","r":"A02987","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἐργάτης) <i>working man, common laborer</i>. Y’lamd. Koraḥ (quot. in Ar.) <span dir=\"rtl\">ועשה אותו א׳</span> (read <span dir=\"rtl\">אותי</span>) and made me (Korah) a working man (<span class=\"citation\">Num. VII, 9</span>); Tanḥ. ed. Bub. Korah, p. 96 <span dir=\"rtl\">אור׳</span>.</div>","alt":[]},"2988":{"h":"אַרְגִּיז","r":"A02988","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Argiz, Argiza</i> (ארזק Schr. KGF 228; <i>Eragiza</i>, Ptol. V, 15, 14; modern <i>Razek</i>, Koh. Ar. s. v.). <span class=\"citation\">Sabb. 19ᵇ</span>; <span class=\"citation\">Erub. 63ᵃ</span> חדתא דא׳ Ms. M. a. oth. (v. Rabb. D. S. a. l. notes, ed. <a href=\"#\" data-headword=\"חַרְתָּא I\">חרתא</a>) Ḥadta (Newtown) [Ḥarta] near Ar. [Rashi: <i>Argiz</i>, pr. n. m. the builder of the town.] <span class=\"citation\">Gitt. 7ᵃ</span> <a href=\"#\" data-headword=\"אַרְגִּיז\">ארגיזה</a>, <a href=\"#\" data-headword=\"*אֶבְיוֹנֵי\">בי א׳</a>. <span class=\"citation\">Zeb. 18ᵇ</span> <a href=\"#\" data-headword=\"אַרְגִּיז\">ארגיזא</a> (Ms. M. <span dir=\"rtl\">אגוזיא</span>, Ms. R. <span dir=\"rtl\">ארגיסיא</span>, <span dir=\"rtl\">ארגזיא</span>, Ms. K. <span dir=\"rtl\">ארגיזיא</span>; v. Rabb. D. S. a. l.).</div>","alt":["אַרְגִּיזָא","אַרְגִּיזָה","(ארגז)"]},"2989":{"h":"ארגינטין","r":"A02989","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"*אֲרוֹגְנַוְטֵיס\">אֲרוֹגְנַוְטִין</a>, <a href=\"#\" data-headword=\"*אֲרוֹגְנַוְטֵיס\">אֲרוֹגְנַוְטֵיס</a> q. v.</div>","alt":["ארגיניטון"]},"2990":{"h":"אַרְגִּירָא","r":"A02990","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּרִיסוֹ\">כְּרִיסוֹ</a></div>","alt":[]},"2991":{"h":"אֶרְגַּלְיָא","r":"A02991","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (ἐργαλεῖα, τὰ) <i>tools, implements</i>. <span class=\"citation\">Ex. R. s. 40</span>, beg. <span class=\"citation\">Lev. R. s. 23</span>; <span class=\"citation\">Y. Succ. IV, 54ᶜ</span> top; <span class=\"citation\">Cant. R. to IV, 8</span> <span dir=\"rtl\">היא וכל א׳ וכ׳</span> itself (the brick) and all the implements for making it. [Y’lamd. B’haaloth., quot. in Ar. <span dir=\"rtl\">כלי א׳</span> implements of a ship.]</div>","alt":["אֶרְגַּלְיָיא","אֶרְגַּלְיָיה"]},"2992":{"h":"אַרְגָּמָן","r":"A02992","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.); <i>purple-dye, purple garment</i>. <span class=\"citation\">Sabb. 90ᵃ</span>. <span class=\"citation\">Kel. XXVII, 12</span>; a. fr.; cmp. <a href=\"#\" data-headword=\"אַרְגְּוָון\">אַרְגְּוָון</a>.</div>","alt":[]},"2993":{"h":"ארגנאטרייא","r":"A02993","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְגֶּנְטָרְיָא\">אַרְגֶּנְטָרְיָא</a></div>","alt":["ארגנטורין"]},"2994":{"h":"ארגנטין","r":"A02994","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְגֶּנְטָרְיָא\">next w.</a>, a. <a href=\"#\" data-headword=\"*אֲרוֹגְנַוְטֵיס\">אֲרוֹגְנַוְטֵיס</a>.</div>","alt":[]},"2995":{"h":"אַרְגֶּנְטָרְיָא","r":"A02995","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἀργενταρία, argentarium) <i>silver-case, plate, table service</i> (of silver or gold). Pesik. Baḥod. p. 106ᵇ ארגנטין Ar. Var. (<a href=\"#\" data-headword=\"אַרְגֶּנְטָרְיָא\">ארגנטרין</a> ed. Koh.; ed. <a href=\"#\" data-headword=\"אנגיטירין\">אנגיטירין</a>); <span class=\"citation\">Yalk. Ex. 271</span> <span dir=\"rtl\">ארגניטין</span> (cmp. versions ibid. a. Ar. s. v., in order to arrive at a correct reading of the whole passage). <span class=\"citation\">Y. Peah VIII, 21ᵇ</span> <a href=\"#\" data-headword=\"אגנטין\">אגנטין</a>, <a href=\"#\" data-headword=\"ארגנאטרייא\">ארגנטורין</a> (corr. acc.). <span class=\"citation\">Esth. R. to I, 4</span> <span dir=\"rtl\">ארגוטדיא</span>, <a href=\"#\" data-headword=\"ארגנאטרייא\">ארגנאטרייא</a> (corr. acc.).</div>","alt":["אַרְגֶּנְטָארְיָיא","אַרְגֶּנְטָרִין"]},"2996":{"h":"אַרְגֶּסְטֵיס","r":"A02996","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀργέστης) <i>the brightening</i>, epithet of various winds (cmp. <a href=\"#\" data-headword=\"אִסְתָּן\">אִסְתָּן</a>); <i>West-North-West, West-South-West</i>. <span class=\"citation\">Num. R. s. 13</span> אני מביא רוח א׳ וכ׳ I shall cause to pass over the world an argestes in which both winds (the Northern and the Southern) shall do service; <span class=\"citation\">Cant. R. to IV, 16</span> <span dir=\"rtl\">ארג׳</span>; <span class=\"citation\">Lev. R. s. 9</span> <a href=\"#\" data-headword=\"אַרְגֶּסְטֵיס\">ארגסטס</a>; Ar. Var. <a href=\"#\" data-headword=\"אגרסטיס\">אגרסטיס</a>.</div>","alt":["(ארגסטס","אגריסטיס)"]},"2997":{"h":"*ארגסטירין","r":"A02997","html":"<div class=\"sense\"> <span class=\"citation\">Koh. R. to XI, 9</span>, v. <a href=\"#\" data-headword=\"אָכְסִיגָרוֹן\">אָכְסִיגָרוֹן</a></div>","alt":[]},"2998":{"h":"*אַרְגְּרוֹן","r":"A02998","html":"<div class=\"sense\"> (read <a href=\"#\" data-headword=\"*אַרְגְּרוֹן\">אַרְגוּרוֹן</a>) m. (ἄργυρον) <i>a small silver coin</i>, also called <i>milliarium</i>. <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> top <span dir=\"rtl\">ובלבד וכ׳</span> provided you do not refuse him his customary <i>argyron</i> (the beggar’s penny); v. <span class=\"citation\">B. Bath. 9ᵃ</span></div>","alt":[]},"2999":{"h":"ארד","r":"A02999","html":"<div class=\"sense\"> <span class=\"citation\">Y. Sot. II, 18ᵃ</span> top, read <a href=\"#\" data-headword=\"אָרַר\">אָרַר</a> q. v.</div>","alt":[]},"3000":{"h":"אַרְדָּא I","r":"A03000","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Syr. <span dir=\"rtl\">ערדא</span>, v. Löw Pfl. p. 303) <i>mushroom, morel</i>. <span class=\"citation\">Keth. 61ᵃ</span> Ar. (ed. <span dir=\"rtl\">אַרְדֵּי</span> pl.)—Pl. <a href=\"#\" data-headword=\"*אוּרְדַּיָּא\">אַרְדַּיָּא</a>, <span dir=\"rtl\">אַרְדֵּי</span>. <span class=\"citation\">Pes. 119ᵇ</span> ארדיא לי Ar. (ed. <a href=\"#\" data-headword=\"אַרְדְּלַיָּיא\">אַרְדְּלַיָּיא</a>, <span dir=\"rtl\">אַרְדִּילַיָּא</span>, <a href=\"#\" data-headword=\"אוּרְדִּילָאֵי\">אוּרְדִּילָאֵי</a>, Ms. <a href=\"#\" data-headword=\"אַרְדִּילָא\">אַרְדִּילֵי</a>, v. Rabb. D. S. a. l. note); Y. ib. X, end, 37ᵈ <a href=\"#\" data-headword=\"ערדילו\">ערדילו</a> (read <a href=\"#\" data-headword=\"עַרְדִּילִין\">עַרְדִּילֵי</a> or <span dir=\"rtl\">עַרְדֵּי לִי</span>). <span class=\"citation\">Ber. 47ᵃ</span> ארדיא Ar. (ed. a. Ms. <span dir=\"rtl\">אַרְדִּילַיָּא</span>). <span class=\"citation\">Ab. Zar. 38ᵃ</span> <span dir=\"rtl\">ארדי</span>.</div>","alt":[]},"3001":{"h":"*אַרְדָּא II","r":"A03001","html":"<div class=\"sense\"> prefix of Persian proper nouns, <i>Arda</i>.—<span class=\"citation\">Gitt. 14ᵇ</span> their names are bewildering <span dir=\"rtl\">א׳ וארטא … בריש</span> beginning with Arda-, and Arta-, and Phile-.</div>","alt":[]},"3002":{"h":"אַרְדַּב","r":"A03002","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἀρτάβη, Syr. <a href=\"#\" data-headword=\"אַרְדַּב\">ארדבא</a>, <span dir=\"rtl\">ארטבא</span>) <i>Artaba</i>, a Persian and Egyptian dry measure (v. Zuckerm. Jüd. Masse p. 47; Sm. Ant. s. v.). <span class=\"citation\">B. Mets. 80ᵇ</span> א׳ לעריבה Ar. (ed. <a href=\"#\" data-headword=\"אַדְרִיב\">אדריב</a>) an Artaba is an unreasonable additional load for a small boat called Arebah. <span class=\"citation\">Erub. 102ᵃ</span> Ar. (ed. <a href=\"#\" data-headword=\"אַדְרִיב\">אדריבא</a>, v. Rabb. D. S. a. l. note 20).</div>","alt":["אַרְדְּבָא"]},"3003":{"h":"אִרְדַּבְלִיס","r":"A03003","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אִדְר׳</span></div>","alt":[]},"3004":{"h":"אַרְדִּיכָל","r":"A03004","html":"<div class=\"sense\">; ch. form <a href=\"#\" data-headword=\"אַרְדִּילָא\">אַרְדִּיכְלָא</a> (<span dir=\"rtl\">אדר׳</span>) m. (prob. from a place or country, cmp. <a href=\"#\" data-headword=\"אַרְגּוּבְלָא\">אַרְגּוּבְלָא</a>) <i>artist, artisan</i> (v. P. Sm. 370 s. v., a. derivat.) esp. <i>architect, key-stone-setter</i>. <span class=\"citation\">B. Mets. 118ᵇ</span> <span dir=\"rtl\">בנאי … לא׳</span> (ed. <span dir=\"rtl\">אדרי׳</span>) when the builder has handed the key-stone over to the architect (to set it). Y. ib. X, end, 12ᶜ <span dir=\"rtl\">ארדכל</span>. <span class=\"citation\">Gen. R. s. 8</span> <a href=\"#\" data-headword=\"אָרָמוּתָא\">אר׳</a>; ib. s. 27 <a href=\"#\" data-headword=\"דְּכַר I\">אד׳</a>.—Pl. <span dir=\"rtl\">ארְדִּיכְלִין</span>. <span class=\"citation\">Targ. II Sam. V, 11</span> (h. text <span dir=\"rtl\">חרשי אבן קיר</span>); a. e.—<span class=\"citation\">Erub. 26ᵃ</span> אַרְדַּ׳ Ar. (Ms. M. <span dir=\"rtl\">דאַרְדַּכְלֵי</span>; ed. <span dir=\"rtl\">אדר׳</span>).—אַרְדִּיכְלַיָּא <span class=\"citation\">Targ. Ps. CXVIII, 22</span>; a. e.</div>","alt":["אַרְדְּכָל"]},"3005":{"h":"אַרְדִּילָא","r":"A03005","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (dimin. of <a href=\"#\" data-headword=\"אָרְבָּא\">אַרְרָּא</a> I q. v.).—Pl. <a href=\"#\" data-headword=\"אַרְדִּילָא\">אַרְדִּילֵי</a>, <span dir=\"rtl\">אַרְדִילַיָּא</span>, <a href=\"#\" data-headword=\"אַרְדְּלַיָּיא\">אַרְדְּלַיָּיא</a></div>","alt":[]},"3006":{"h":"אַרְדְּכָל","r":"A03006","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְדִּיכָל\">אַרְדִּיכָל</a></div>","alt":[]},"3007":{"h":"אַרְדְּלַיָּיא","r":"A03007","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְדִּילָא\">אַרְדִּילָא</a></div>","alt":[]},"3008":{"h":"*ארדפוי","r":"A03008","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. XXX, 37</span> <span dir=\"rtl\">דלוז וא׳</span>, a corruption; prob. <span dir=\"rtl\">דלוז וּדְאַרְמוֹן</span>, v. <a href=\"#\" data-headword=\"אַרְמוֹן III\"><span dir=\"rtl\">אַרְמוֹן</span> III</a></div>","alt":[]},"3009":{"h":"אַרְדַּפְנֵי","r":"A03009","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"הַרְדֹּופַנִּין\">הַרְדֹּופַנִּין</a>; v. <a href=\"#\" data-headword=\"הַרְדַּפְנֵי\">הַרְדַּפְנֵי</a>. <span class=\"citation\">Targ. Y. I Ex. XV, 25</span>, <span class=\"citation\">Targ. Y. II, Ex. XV, 25</span>.</div>","alt":["אַרְדִּפְנֵי"]},"3010":{"h":"ארדקסם","r":"A03010","html":"<div class=\"sense\">, read <span dir=\"rtl\">אַרְדּקְסַט</span> or</div>","alt":[]},"3011":{"h":"אַרְדַּקְסַס","r":"A03011","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Artaxata</i>, or <i>Artaxiata</i>, capital of Great Armenia. Y. Erub. III, beg. 20ᶜ. Bab. <span class=\"citation\">Erub. 29ᵃ</span> <a href=\"#\" data-headword=\"עַרְדִּיסְקָא\">עַרְדִּיסְקָא</a> ed. (Ms. M. <span dir=\"rtl\">עַרְדַסְקִיס</span>, Var. <a href=\"#\" data-headword=\"עַרְדַּסְקוֹס\">ערדסקוס</a>, <span dir=\"rtl\">ערדיקס</span>, v. Rabb. D. S. a. l. note). Tosef. ib. IX (VI), 4 <span dir=\"rtl\">ערדסקס</span>, (Var. <a href=\"#\" data-headword=\"עַרְדַּסְקוֹס\">ערדסקוס</a>, <span dir=\"rtl\">ערדסקין</span>).</div>","alt":[]},"3012":{"h":"אַרְדְּשִׁיר","r":"A03012","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ardjir</i>, formerly <i>Seleucia</i>, near Ctesiphon. <span class=\"citation\">Gitt. 6ᵃ</span> <a href=\"#\" data-headword=\"*אֶבְיוֹנֵי\">בי א׳</a>. <span class=\"citation\">Erub. 57ᵇ</span>. <span class=\"citation\">B. Bath. 52ᵃ</span>, v. <a href=\"#\" data-headword=\"הוֹרְמִיז\">הוֹרְמִיז</a>. <span class=\"citation\">Yeb. 37ᵇ</span> <span dir=\"rtl\">דַּרְדְּשִׁיר</span> = <span dir=\"rtl\">דְאַרְ׳</span>, sub. <a href=\"#\" data-headword=\"הוֹרְמִיז\">הוֹרְמִיז</a>; <span class=\"citation\">Yoma 18ᵇ</span> <span dir=\"rtl\">דרשיש</span> (corr. acc.).</div>","alt":[]},"3013":{"h":"אָרָה","r":"A03013","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"ארי\">ארי</a></div>","alt":[]},"3014":{"h":"אֲרוּ","r":"A03014","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"ארי\">ארי</a>; v. <a href=\"#\" data-headword=\"אֲלוּ\">אֲלוּ</a>, cmp. <a href=\"#\" data-headword=\"הֲרֵי I\">הֲרֵי</a>) <i>lo!, behold.</i> <span class=\"citation\">Dan. VII, 6</span>; <span class=\"citation\">7</span>; <span class=\"citation\">13</span>.</div>","alt":[]},"3015":{"h":"אֲרוּבָּה","r":"A03015","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>opening</i>, whence </div><div class=\"sense\"><b>1)</b> <i>an aperture in the roof looking to the ground floor</i> (answering to the Greek <i>hypaithron</i>, Roman <i>compluvium</i>), contrad. fr. <a href=\"#\" data-headword=\"חַלּוֹן\">חַלֹּון</a> a garret window in the wall projecting above the flat roof. <span class=\"citation\">Bets. V, 1</span> (<span class=\"citation\">35ᵇ</span>); cmp. Rashi a. l. <span class=\"citation\">Nidd. 20ᵇ</span> <span dir=\"rtl\">כסומא בא׳</span> like a blind man finding his way down from the <i>ărubbah</i>, i.e. hitting the truth by chance. Ohol. X, 1; a. fr.—Pl. <span dir=\"rtl\">אֲרוּבֹּות</span>. <span class=\"citation\">Ib. 4</span> sq.; a. e.</div><div class=\"sense\"><b>—2)</b> <i>the opening panel of folding doors.</i> <i>—Pl.</i> as supra. <span class=\"citation\">Yoma 76ᵃ</span>. [<span class=\"citation\">Sabb. 43ᵃ</span>; <span class=\"citation\">153ᵇ</span>; <span class=\"citation\">Kel. XV, 2</span> read with Ar. <span dir=\"rtl\">אֲרוּכוֹת</span>.]</div>","alt":[]},"3016":{"h":"אֲרוּגָּה","r":"A03016","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ארג</span>) <i>web, matting</i>. Y. Succ. I, end, 52ᶜ <span dir=\"rtl\">א׳ טמאה</span> a mat (of twigs &amp;c. for covering the festive booth) that became unclean.</div>","alt":[]},"3017":{"h":"*אֲרוֹגְנַוְטֵיס","r":"A03017","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀρωγοναύτης sub. δαίμων) <i>helper of sailors, Arogonautes</i>, a demon. <span class=\"citation\">Gen. R. s. 63</span>; Y. Ter. VIII, 46ᶜ top; <span class=\"citation\">Yalk. Gen. 110</span>, variously corrupted <a href=\"#\" data-headword=\"ארגינטין\">ארגינטין</a>, <a href=\"#\" data-headword=\"ארגינטין\">ארגיניטון</a>, <span dir=\"rtl\">ארגניטין</span>, <a href=\"#\" data-headword=\"אנגיטריס\">אנגיטריס</a>.</div>","alt":["אֲרוֹגְנַוְטֵין"]},"3018":{"h":"ארְוָא","r":"A03018","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">אֻרְוָתָא</span>, <span dir=\"rtl\">אֻרְוָת</span>, v. <a href=\"#\" data-headword=\"אוּרְיָא\">אוּרְיָא</a> Ch.</div>","alt":[]},"3019":{"h":"אָרוֹד","r":"A03019","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>mule</i>, v. <a href=\"#\" data-headword=\"עָרוֹד\">עָרוֹד</a>.</div>","alt":["אָרוֹדָא"]},"3020":{"h":"אֻרְיָה","r":"A03020","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אוֹרְיָא ²\"><span dir=\"rtl\">אוּרְיָא</span> II</a>) <i>manger, crib.</i> <i>—</i> Pl. <span dir=\"rtl\">אֻרְווֹת</span>. <span class=\"citation\">Snh. 21ᵇ</span></div>","alt":[]},"3021":{"h":"אַרְוָוד","r":"A03021","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Aradus</i> on the Phœnician coast. <span class=\"citation\">Gen. R. s. 37</span> (to <i>Arvadi</i>, <span class=\"citation\">Gen. X, 18</span>).</div>","alt":[]},"3022":{"h":"אַרְוָודָאֵי","r":"A03022","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אַרְוָוד\">preced.</a>) <i>Aradeans</i>. <span class=\"citation\">Targ. O. Gen. X, 18</span> (Targ. Y. II <a href=\"#\" data-headword=\"אַנְטִירִידִינָאֵי\">אַנְטִירִידִינָאֵי</a>; I <a href=\"#\" data-headword=\"לוּטָסָאֵי\">לוּטָסָאֵי</a>, Var. in <span class=\"citation\">Targ. I Chr. I, 16</span> <a href=\"#\" data-headword=\"לְטוֹסָאֵי\">לְטוּסָאֵי</a>).</div>","alt":[]},"3023":{"h":"אַרְוָוסָא","r":"A03023","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַרְוִיסָא\">אַרְוִיסָא</a></div>","alt":[]},"3024":{"h":"אָרוּזָא","r":"A03024","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>rice</i>, v. <a href=\"#\" data-headword=\"אוּרְזָא\">אוּרְזָא</a>.</div>","alt":[]},"3025":{"h":"*אַרְוִיסָא","r":"A03025","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a transpos. of <a href=\"#\" data-headword=\"אַפְסִירָא\">אַפְסִירָא</a>, <a href=\"#\" data-headword=\"אַפְסָרָא\">אַפְסָרָא</a>) <i>halter</i> (Rashi). [Ar. <i>chain</i>, Perl. Et. St. p. 21 = Pers. arvîs <i>rope</i>.] <span class=\"citation\">Yeb. 46ᵃ</span> רמו ליה ארוו׳ וכ׳ Ar. ed. Koh. (ed. <span dir=\"rtl\">ארוי׳</span>, Ar. ed. <a href=\"#\" data-headword=\"ארוסיה\">ארוסיה</a>) they put a halter around his neck (to prevent him from claiming his liberty).</div>","alt":["אַרְוָוסָא"]},"3026":{"h":"אָרוּךְ","r":"A03026","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ארך\">ארך</a>) </div><div class=\"sense\"><b>1)</b> <i>long, tall, lasting;</i> v. infra. v. infra.</div><div class=\"sense\"><b>—2)</b>  (= <span dir=\"rtl\">עָרוּךְ</span>; cmp. <a href=\"#\" data-headword=\"אֲרִיךְ I\">אֲרִיךְ</a>) <i>well-arranged, well-balanced, thinker</i>, a title of prominent scholars; cmp. <a href=\"#\" data-headword=\"אַרְיוֹךְ\">אַרְיוֹךְ</a> a. <a href=\"#\" data-headword=\"אֲרִיכָא\">אֲרִיכָא</a>. [In legend intellectual eminence was identified with physical tallness.] <span class=\"citation\">Nidd. 24ᵇ</span> א׳ בדורו <i>arukh</i> (the tallest) in his generation. <span class=\"citation\">Kidd. 39ᵇ</span> <span dir=\"rtl\">עולם שכולו א׳</span> the world in which all is well-balanced (also called <span dir=\"rtl\">שכולו טוב</span>) i.e. <i>the hereafter.—Pl.</i> <span dir=\"rtl\">אֲרוּכִים</span>. <span class=\"citation\">Yoma 71ᵃ</span> <span dir=\"rtl\">חיים א׳</span> long life; a. fr.—Fem. <a href=\"#\" data-headword=\"אֲרוּכָה I\">אֲרוּכָה</a>. <span class=\"citation\">Ber. I, 4</span> <span dir=\"rtl\">אחת א׳</span> one lengthy (benediction); a. fr.—<span class=\"citation\">Y. Hor. II, 46ᵈ</span> <span dir=\"rtl\">בא׳</span> by the long road, slowly; <span class=\"citation\">Shebu. 18ᵃ</span>; <span class=\"citation\">18ᵇ</span>.—Pl. <span dir=\"rtl\">אֲרוּכוֹת</span>. Y. Ber. II, 5ᶜ top, a. e. <span dir=\"rtl\">א׳ וקצרות</span> long and short roads, i.e. <i>in all directions</i>. V. <a href=\"#\" data-headword=\"אֲרוּכָא\">next art.</a></div>","alt":[]},"3027":{"h":"אֲרוּכָא","r":"A03027","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְכָא III\"><span dir=\"rtl\">אַרְכָא</span> III</a></div>","alt":[]},"3028":{"h":"אֲרוּכָה I","r":"A03028","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  fem. of <a href=\"#\" data-headword=\"אָרוּךְ\">אָרוּךְ</a>.</div><div class=\"sense\"><b>—2)</b>  (noun) <i>long board, longside of bedstead, bedside</i>. <span class=\"citation\">Succ. 15ᵇ</span> <span dir=\"rtl\">א׳ ושתי כרעים</span> the long bedside with its two knees (supporters); <span class=\"citation\">16ᵃ</span>.—Pl. <span dir=\"rtl\">אֲרוּכוֹת</span>. <span class=\"citation\">Ib. I, 8</span> (Var. <span dir=\"rtl\">ארובות</span>, v. Rabb. D. S. ib. ad 15ᵃ, note 1); <span class=\"citation\">Sabb. 43ᵃ</span>; <span class=\"citation\">ib. XXIII, 5</span> (<span class=\"citation\">151ᵇ</span>) <span dir=\"rtl\">א׳ המטה</span> (some ed. <span dir=\"rtl\">ארובות</span>, corr. acc.).—[<span class=\"citation\">Kel. XV, 2</span> א׳ של נחתומים Ar. Var. <i>the long ranging boards</i> used by the bakers: Maim.; the prevailing versions are <span dir=\"rtl\">אֲרוּבֹּות</span> or <span dir=\"rtl\">אֲרֵיבוֹת</span>; <span class=\"citation\">Tosef. B. Mets. V, 4</span> <span dir=\"rtl\">ארובות</span>, (Var. <span dir=\"rtl\">ארונות</span>) <i>basins</i> or <i>moulds</i> in which loaves or cakes are shaped.—Var. Ar. <a href=\"#\" data-headword=\"עֲרִיכוּת\">עֲרִיכוֹת</a>.]</div>","alt":[]},"3029":{"h":"אֲרוּכָה II","r":"A03029","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. Ges. H. Dict. s. v.) <i>the web of new flesh or skin on a healing wound, healing</i>. <span dir=\"rtl\">העלה א׳</span> <i>to produce a new cover, be restored</i>. <span class=\"citation\">Ḥull. 77ᵃ</span>; <span class=\"citation\">125ᵃ</span>; <span class=\"citation\">B. Kam. 91ᵇ</span></div>","alt":[]},"3030":{"h":"אֲרוּם","r":"A03030","html":"<div class=\"sense\"><b>1)</b>   v. <a href=\"#\" data-headword=\"אֲרֵי\">אֲרֵי</a>.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"אֲרִים\">אֲרִים</a></div>","alt":[]},"3031":{"h":"אֲרוּמָא","r":"A03031","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Aruma</i>. <span class=\"citation\">Erub. 51ᵇ</span> ed., Ms. M. <a href=\"#\" data-headword=\"רוּמָה\">רוּמָא</a> q. v.</div>","alt":[]},"3032":{"h":"אֲרוֹמָאָה","r":"A03032","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Roman.</i> Pl. <span dir=\"rtl\">אֲרוֹמָאֵי</span>. <span class=\"citation\">Gitt. 17ᵃ</span>; cmp. <a href=\"#\" data-headword=\"אֲרַמָּאָה\">אֲרַמָּאָה</a>.</div>","alt":[]},"3033":{"h":"אֲרוֹמִי","r":"A03033","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> . <span class=\"citation\">Gitt. 17ᵃ</span>; v. <a href=\"#\" data-headword=\"אֲרָם\">אֲרָם</a>, <a href=\"#\" data-headword=\"אֲרַמִּי\">אֲרַמִּי</a>.</div>","alt":[]},"3034":{"h":"אָרוֹן","r":"A03034","html":"<div class=\"sense\"> c. (b. h.;  [joined together,] <i>chest, box, coffin</i>, freq. (= <span dir=\"rtl\">אֲרוֹן הַקּוֹדֶשׁ</span>) <i>the Holy Ark</i>, in the tabernacle and the Temple, or in Synagogues. <span class=\"citation\">Yoma V, 1</span> <span dir=\"rtl\">הגיע לא׳</span> reached the place where the Ark stood during the First Temple. <span class=\"citation\">Y. Ber. IV, 8ᶜ</span> top; <span class=\"citation\">Gen. R. s. 55</span> (allegorical etymologies).—<span class=\"citation\">Keth. 104ᵃ</span> <span dir=\"rtl\">א׳ הקודש</span> (figuratively) <i>a good and learned man’s soul;</i> v. <a href=\"#\" data-headword=\"אֶרְאֵל\">אֶרְאֵל</a>.—<span class=\"citation\">Kel. XII, 5</span> <span dir=\"rtl\">א׳ של גרוסות</span> the grits-dealer’s chest. <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> top; <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\"><span dir=\"rtl\">אֲרוֹנִי נקובה</span> (<span dir=\"rtl\">נקופה</span>) <span dir=\"rtl\">וכ׳ ותהא</span></span> let my coffin be perforated at the bottom. <span class=\"citation\">Snh. 98ᵇ</span> <span dir=\"rtl\">אין לך כל א׳ וא׳ וכ׳</span> there is no coffin in Palestine in which the Median horses do not eat straw (being used as cribs); a. fr.—Pl. <span dir=\"rtl\">אֲרוֹנוֹת</span>. <span class=\"citation\">Sot. 13ᵃ</span>; a. fr. [<span class=\"citation\">Y. Keth. VI, 30ᵈ</span> bot. <span dir=\"rtl\">וארון</span>, v. <a href=\"#\" data-headword=\"אֲרִי I\"><span dir=\"rtl\">אֲרִי</span> I</a>.]</div>","alt":[]},"3035":{"h":"אֲרוֹנָא","r":"A03035","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ex. XXV, 10</span>; a. fr. <span class=\"citation\">Targ. Gen. L, 26</span> (coffin).—<span class=\"citation\">Y. Meg. III, 73ᵈ</span> bot. the curtain <span dir=\"rtl\">על א׳ כא׳</span> over the ark containing the scrolls is as sacred as the ark itself. <span class=\"citation\">Y. Ber. II, 5ᶜ</span> bot. <span dir=\"rtl\">אֲרוֹנֵיה נפקא</span> his coffin was carried out for burial.</div>","alt":["(אֲרוֹנָה)"]},"3036":{"h":"ארונטס","r":"A03036","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָרְנָטוּס\">אָרְנָטוּס</a></div>","alt":[]},"3037":{"h":"*אֲרוֹנֵי","r":"A03037","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (prob. pl. of <a href=\"#\" data-headword=\"אֲרוֹנָא\">ארונא</a>, so called from closing and opening like chests) name of certain <i>plants</i> growing in marshes and closing their leaves at nightfall. <span class=\"citation\">Sabb. 35ᵇ</span> בדברא עורבי באגמא חזו אדני Ms. M. (ed. <span dir=\"rtl\">עורבי א&quot;נ אדאני …</span>; v. Rabb. D. S. a. l., Ar. <a href=\"#\" data-headword=\"הרני\">הרני</a>, Var. <a href=\"#\" data-headword=\"*אֲרוֹנֵי\">ארוני</a>, Rashi ed. Sonc., Asheri a. R. Niss. early ed. <a href=\"#\" data-headword=\"אראני\">אראני</a>) in the desert you recognize the entrance of the Sabbath (on a cloudy day) by the ravens, in marsh-land you look out for <i>aroné</i></div>","alt":["אֲרָאנֵי"]},"3038":{"h":"אֲרוֹנִים","r":"A03038","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֹרֶן\">אֹרֶן</a></div>","alt":[]},"3039":{"h":"אִרוֹנִית","r":"A03039","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִירוֹנִית\">אִירוֹנִית</a></div>","alt":[]},"3040":{"h":"ארונקי","r":"A03040","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲדַנְדְּקֵי\">אדנדקי</a></div>","alt":[]},"3041":{"h":"אֵרוּס","r":"A03041","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵירוּס I\"><span dir=\"rtl\">אֵירוּס</span> I</a>, II.</div>","alt":[]},"3042":{"h":"ארוסיה","r":"A03042","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַרְוִיסָא\">אַרְוִיסָא</a></div>","alt":[]},"3043":{"h":"אֵרוּסִין","r":"A03043","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָרַס\">אָרַס</a>) <i>betrothal, preliminary act of marriage</i>, answering to the Roman <i>sponsalia; promise in marriage</i>, disting. fr. <a href=\"#\" data-headword=\"נִישּׂוּאִין\">נישואין</a>, or <a href=\"#\" data-headword=\"כְּנִיסָה\">כניסה</a>, marriage proper, the latter consisting in conducting the bride to the groom’s permanent (or improvised) home. [The betrothal carries with it almost all the legal consequences of marriage, excepting some modifications mostly of a civil (pecuniary) character, and is, according to Talmudic usage, preceded by a benediction <span dir=\"rtl\">(בִּרְכַת א׳</span>), while the act itself is performed by the bride-groom (or his mandatary) delivering into the hands of the bride (or her mandatary, or her father, if she be a minor) an object representing any value not below the smallest coin (P’rutah), whereby the purpose of the delivery is stated and assented to by acceptance.] <span class=\"citation\">Keth. I, 2</span> <span dir=\"rtl\">אלמנה מן הא׳</span> a widow whose betrothed died before marriage proper. <span class=\"citation\">Ib. V, 1</span>; a. fr. <span class=\"citation\">Yeb. 43ᵃ</span>, a. fr. <span dir=\"rtl\">סעודת א׳</span> the repast following the betrothal.—Metaph. of the relation between Israel and God, <i>covenant</i>. <span class=\"citation\">Ex. R. s. 15</span>, end; a. e.</div>","alt":["אֵירוּסִין"]},"3044":{"h":"אֲרוּקְתָּא","r":"A03044","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְקְתָא I\"><span dir=\"rtl\">אַרְקְתָא</span> I</a></div>","alt":[]},"3045":{"h":"ארורא","r":"A03045","html":"<div class=\"sense\">, Y. Shek. II, end, 47ᵃ <span dir=\"rtl\">דארורא צילמא</span>, v. <a href=\"#\" data-headword=\"אֲדוּרֵי\">אֲדוּרֵי</a></div>","alt":[]},"3046":{"h":"אֲרוּרֵי","r":"A03046","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲרַר\">אֲרַר</a></div>","alt":["אֲרוּרַיָּיא"]},"3047":{"h":"*ארז","r":"A03047","html":"<div class=\"sense\"> (√<span dir=\"rtl\">אר</span>, v. <span dir=\"rtl\">ארר</span>; cmp. <span dir=\"rtl\">חרז</span>) </div><div class=\"sense\"><b>1)</b> <i>to penetrate deeply, to take deep root</i>.</div><div class=\"sense\"><b>—2)</b> <i>to be prickly, dry, hard</i>. <span class=\"citation\">Sabb. 155ᵃ</span> זירין דאַרְזֵי Zirin are called bundles of twigs which are hard. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כיפין דא׳</span>; [oth. opin., v. <a href=\"#\" data-headword=\"אַרְזָא\">אַרְזָא</a>]. Denom. <a href=\"#\" data-headword=\"אוּרְזָא\">אוּרְזָא</a>, <a href=\"#\" data-headword=\"אָרוּזָא\">אָרוּזָא</a>, a. <a href=\"#\" data-headword=\"אֶרֶז\">next ws.</a></div>","alt":[]},"3048":{"h":"אֶרֶז","r":"A03048","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>cedar</i>. <span class=\"citation\">Tam. III, 5</span> <span dir=\"rtl\">של א׳</span> of cedar wood.—Pl. <a href=\"#\" data-headword=\"*אֲרָזִין\">אֲרָזִים</a>. <span class=\"citation\">R. Hash. 23ᵃ</span>; <span class=\"citation\">Taan. 25ᵇ</span>; a. e.—Metaph. <i>prominent men, scholars</i>. <span class=\"citation\">Sabb. 118ᵇ I</span> planted <span dir=\"rtl\">חמשה א׳</span> five cedars (begot five sons who acquired renown). <span class=\"citation\">M. Kat. 25ᵇ</span>, v. <a href=\"#\" data-headword=\"אֵזוֹב\">אֵזוֹב</a>.</div>","alt":[]},"3049":{"h":"אַרְזָא","r":"A03049","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"אֶרֶז\">same</a>. <span class=\"citation\">Targ. Lev. XIV, 4</span>; a. e.—<span class=\"citation\">Ab. Zar. 14ᵃ</span>. <span class=\"citation\">R. Hash. 23ᵃ</span>; a. e.—Pl. <a href=\"#\" data-headword=\"*אֲרָזִין\">אַרְזִין</a>, <span dir=\"rtl\">אַרְזַיָּא</span>, <a href=\"#\" data-headword=\"רזֵי\">אַרְזֵי</a>. <span class=\"citation\">Targ. Num. XXIV, 6</span>; a. e.—<span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> top. <span class=\"citation\">Sabb. 157ᵃ</span>.—<span class=\"citation\">Ib. 155ᵃ</span> <span dir=\"rtl\">זירין דא׳</span> (Ms. <span dir=\"rtl\">זירין סוכי דא׳</span> <i>Zirin</i> means twigs of cedars (Rashi <span dir=\"rtl\">דארזא</span>); [oth. opin. v. <a href=\"#\" data-headword=\"*ארז\">ארז</a>].</div><div class=\"sense\"><b>—2)</b>  pr. n. pl. <span dir=\"rtl\">תֵּל א׳</span> <i>Tel Arza</i> (Cedar-Hill), in Palestine, scene of massacres during the Bar Kokhba war. (Cedar-Hill), in Palestine, scene of massacres during the Bar Kokhba war. <span class=\"citation\">Yeb. XVI, 7</span>.</div><div class=\"sense\"><b>—3)</b>  pr. n. m. <i>Arza</i>. <span class=\"citation\">Tam. VII, 3</span> <span dir=\"rtl\">בן א׳</span>: <span class=\"citation\">Shek. V, 1</span> <a href=\"#\" data-headword=\"אַרְזָה\">ארזה</a>; <span class=\"citation\">Tosef. ib. II, 14</span>.</div>","alt":[]},"3050":{"h":"אַרְזְבוֹנִית","r":"A03050","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אַרְזוֹבָא\">אַרְזוֹבָא</a>) <i>arz’bonith</i>, a species of <i>locusts</i>; cmp. <a href=\"#\" data-headword=\"עַרְצוּבְיָא\">עַרְצוּבְיָא</a> a. <a href=\"#\" data-headword=\"כַּרְזְבָא\">כַּרְזוּבָּא</a>. Sifra Sh’mini <span class=\"citation\">Par. III</span>, ch. 5; <span class=\"citation\">Ḥull. 65ᵃ</span> <span dir=\"rtl\">הרזבנית</span>.</div>","alt":[]},"3051":{"h":"אַרְזָג","r":"A03051","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְגָּז\">אַרְגָּז</a></div>","alt":[]},"3052":{"h":"אַרְזָה","r":"A03052","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְזָא\">אַרְזָא</a></div>","alt":[]},"3053":{"h":"אַרְזוֹבָא","r":"A03053","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"אַרְזַפְתָּא I\">אַרְזַפְתָּא</a>) <i>hammer.</i> <i>—</i> Pl. <span dir=\"rtl\">אַרְזוֹבִין</span>. <span class=\"citation\">Targ. I Kings VI, 7</span>.</div>","alt":[]},"3054":{"h":"ארזון","r":"A03054","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אֲרָזִין\">אֲרָזִין</a></div>","alt":[]},"3055":{"h":"אַרְזִילָא","r":"A03055","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְזְלָא\">אַרְזְלָא</a>.—<span dir=\"rtl\">אַרְזִילֵי</span>, v. <a href=\"#\" data-headword=\"אוּרְזִילָא\">אוּרְזִילָא</a>.</div>","alt":[]},"3056":{"h":"*אֲרָזִין","r":"A03056","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (prob. plur. of <a href=\"#\" data-headword=\"אֶרֶז\">אֶרֶז</a>) <i>box, chest</i> (for collecting bones). <span class=\"citation\">Tosef. Snh. IX, 8</span> (ed. Zuck. <span dir=\"rtl\">בארון</span>, Var. <span dir=\"rtl\">בארזון</span>). <span class=\"citation\">Treat. S’maḥ. ch. XII</span> <span dir=\"rtl\">בגלוסקמא בא׳</span> (one word inserted by a glossator to explain the other). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בידין</span> (corr. acc.). [Tur Y. D. Abeluth 403: <span dir=\"rtl\">ארזים</span>.]</div>","alt":[]},"3057":{"h":"אַרְזְלָא","r":"A03057","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (dimin. of <a href=\"#\" data-headword=\"עֶרֶס\">עֶרֶס</a>, <a href=\"#\" data-headword=\"עֶרֶס\">עַרְסָא</a>) <i>cradle, hammock</i> for watchmen in gardens. <span class=\"citation\">Targ. Is. I, 8</span>; <span class=\"citation\">XXIV, 20</span> (h. <span dir=\"rtl\">מלונה</span>).—<span class=\"citation\">Erub. 25ᵇ</span> דעבידא כי אר׳ Ar. (ed. <span dir=\"rtl\">אור׳</span>; Rashi <span dir=\"rtl\">ארזי׳</span>; Tosaf. <span dir=\"rtl\">ערס׳</span>) the roof of the shed has the shape of a cradle, i. e both sides slanting towards the centre.</div>","alt":["(אוּרְזִילָא)","אַרְזִילָא","עַרְסַל","עַרְסְלָא"]},"3058":{"h":"אַרְזְנָאֵי","r":"A03058","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <span dir=\"rtl\">ארזוניא</span> P. Sm. 374, cmp. <span dir=\"rtl\">פרשניא</span> Neub. Géogr. p. 396) <i>of Arzania</i>. <span class=\"citation\">Taan. 24ᵇ</span> ארבי דא׳ Ar. (ed. <span dir=\"rtl\">דחיטין דפרזינא</span>; Ms. M. <span dir=\"rtl\">דפרזינאי</span>) ships of the Arzanians. Fem. *<span dir=\"rtl\">אַרְזַנְיָיתָא</span>. <span class=\"citation\">Git. 70ᵃ</span> חיטין א׳ Arzanian wheat (of a large size).</div>","alt":[]},"3059":{"h":"אַרְזַפְתָּא I","r":"A03059","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רזף</span>) <i>hammer</i>. Targ. <span class=\"citation\">Judg. IV, 26</span>.—<span class=\"citation\">Gitt. 56ᵇ</span>. <span class=\"citation\">Meg. 25ᵃ</span> (Ms. <a href=\"#\" data-headword=\"מַרְזַפְתָּא\">מַרְזפְתָּא</a>).</div>","alt":[]},"3060":{"h":"אַרְזַפְתָּא II","r":"A03060","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זַיִף\">זַיִף</a>, a. <a href=\"#\" data-headword=\"אַרְדַּפְנֵי\">אַרְדַּפְנֵי</a> = <span dir=\"rtl\">הַרְדַּ׳</span>; cmp. Löw, Pfl. p. 320) <i>hypericum</i> (<i>barbatum</i>), <i>St.</i> <i> John’s wort</i>, a plant said to be fatal to cattle. <span class=\"citation\">B. Kam. 47ᵇ</span> באר׳ Ar. a. Ms. H. (Var. <a href=\"#\" data-headword=\"הַרְזִיפָּא\">הרזיפא</a>, v. Koh. Ar.; ed. <span dir=\"rtl\">אפר׳</span>) under ‘poison’ is meant <i>arzafta</i> which may also be called <i>peré</i> (<i>fruit</i>, produces of the earth). <span class=\"citation\">B. Bath. 20ᵃ</span> אר׳ Ar. (Ms. <a href=\"#\" data-headword=\"אָרָמוּתָא\">אר׳</a>, changed into <a href=\"#\" data-headword=\"אִיפַּרְכִי\">אפ׳</a> as ed.). Cmp. <a href=\"#\" data-headword=\"הַרְזיפּוּ\">הַרְזִיפּוּ</a>.</div>","alt":["(אַפְרַזְתָּא)"]},"3061":{"h":"אָרַח","r":"A03061","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">ארר</span>) </div><div class=\"sense\"><b>1)</b> <i>to go through;</i> v. <a href=\"#\" data-headword=\"אָרִיחַ\">אָרִיחַ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to go outside, to travel</i>. Part. <a href=\"#\" data-headword=\"אוֹרֵחַ\">אוֹרֵחַ</a> q. v.—Denom. <a href=\"#\" data-headword=\"אוֹרַח\">אוֹרַח</a> <i>path</i></div><div class=\"sense\"><b>Pi. אֵרַח</b> <div class=\"sense\"> (Denom. of <a href=\"#\" data-headword=\"אוֹרֵחַ\">אוֹרֵחַ</a>) <i>to receive a guest, to lodge</i>. <span class=\"citation\">Ber. 63ᵇ</span> <span dir=\"rtl\">המְאָרֵחַ</span>. Y. Ab. Zar. I, 39ᶜ bot. <span dir=\"rtl\">לאָרְחוֹ</span>.</div></div><div class=\"sense\"><b>Hithpa. הִתְאָרֵחַ  נִתְאָרֵחַ</b> <div class=\"sense\"><i>to be received, be the guest of</i>. <span class=\"citation\">Sabb. 13ᵇ</span> a. fr. Y. Ḥall. IV, 60ᵃ <span dir=\"rtl\">מִתְאָ׳</span>.</div></div>","alt":[]},"3062":{"h":"אֲרַח","r":"A03062","html":"<div class=\"sense\">, esp. <i>to take lodging</i>. <span class=\"citation\">Targ. Jud. XIX, 17</span>. [<span dir=\"rtl\">ארח</span>, <span dir=\"rtl\">ארחא</span> <span class=\"citation\">Yoma 82ᵇ</span>, a. e., Af. of <a href=\"#\" data-headword=\"רִיחַ\">רִיחַ</a>.]</div><div class=\"sense\"><b>Ithpe. אִתְאֲרַח</b> <div class=\"sense\">, contr. <span dir=\"rtl\">אִתְרַח</span> <i>to dwell as a stranger, sojourn</i>. <span class=\"citation\">Targ. Y. Deut. I, 6</span>; v. <a href=\"#\" data-headword=\"אָחַר\">אְחַר</a>.</div></div>","alt":["אָרַח"]},"3063":{"h":"אָרְחָא","r":"A03063","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרַח\">preced.</a>) <i>traveler, guest</i>. <span class=\"citation\">Targ. II Sam. XII, 4</span>.—[<span class=\"citation\">Y. Ber. I, 2ᵈ</span> top <span dir=\"rtl\">לא הוה ארחא אתיא וכ׳</span>, oth. ed. <span dir=\"rtl\">ארתא</span>, read <a href=\"#\" data-headword=\"שַׁחֲרָא\">שַׁחְרָא</a> with oth. ed.].—Pl. <span dir=\"rtl\">אָרְחִין</span>, <span dir=\"rtl\">אוֹרְחִין</span>. Y. Peah VIII, end, 21ᵇ, (read as) <span class=\"citation\">Y. Shek. V, end, 49ᵇ</span> <span dir=\"rtl\">הוה ליה א׳</span> he had guests. [אָרְחָא <i>path</i>, v. <a href=\"#\" data-headword=\"אוֹרַח\">אוֹרְחָא</a>.]</div>","alt":["אוֹרְחָא"]},"3064":{"h":"אַרְחָא","r":"A03064","html":"<div class=\"sense\"><i>lath</i>, v. <a href=\"#\" data-headword=\"אָרִיחָא\">אֲרִיחָא</a>.—<span dir=\"rtl\">ארחין</span>, v. <a href=\"#\" data-headword=\"אָרִיחַ\">אָרִיח</a>.</div>","alt":[]},"3065":{"h":"אַרְטָא","r":"A03065","html":"<div class=\"sense\"> prefix of Pers. proper nouns, <i>Arta-</i>. <span class=\"citation\">Gitt. 14ᵇ</span>, v. <a href=\"#\" data-headword=\"*אַרְדָּא II\"><span dir=\"rtl\">אַרְדָּא</span> II</a>.</div>","alt":[]},"3066":{"h":"ארטבון","r":"A03066","html":"<div class=\"sense\"> <span class=\"citation\">Yoma 11ᵃ</span>; <span class=\"citation\">Yalk. Deut. 844</span>; Sam. 124—perh. a corruption of <span dir=\"rtl\">טְרִיבּוּן</span> (a Jewish) <i>tribunus;</i> cmp. <a href=\"#\" data-headword=\"ארטיגוס\">ארטיגוס</a>. [Or pr. n.?]</div>","alt":["ארטבין"]},"3067":{"h":"אַרְטְבִינָא","r":"A03067","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְטְבַנְיָא\">ארְטְבַנְיָא</a></div>","alt":[]},"3068":{"h":"ארטבלאי","r":"A03068","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Esth. VIII, 10</span> Levita, v. <span dir=\"rtl\">ערְטִילֵי</span></div>","alt":[]},"3069":{"h":"אַרְטְבַן","r":"A03069","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Artaban</i> (IV), the last Parthian king, friend of R. Judah han-Nasi. <span class=\"citation\">Y. Peah I, 15ᵈ</span> bot.; <span class=\"citation\">Gen. R. s. 35</span>; <span class=\"citation\">Yalk. Deut. 844</span>; Prov. 934.—V. <a href=\"#\" data-headword=\"אֲדַרְכָּן\">אדרכן</a>.</div>","alt":["אַרְטְבָאן"]},"3070":{"h":"אַרְטְבַנְיָא","r":"A03070","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Artabania</i> (named after Artaban, v. <a href=\"#\" data-headword=\"אַרְטְבַן\">preced.</a>), near Pumbeditha. <span class=\"citation\">Erub. 51ᵇ</span> (Var. lect., v. Rabb. D. S. a. l.).</div>","alt":["אַרְטְבִינָא","אַרְטְוַנְיָא","ארטיבנא"]},"3071":{"h":"ארטיגוס","r":"A03071","html":"<div class=\"sense\"> <span class=\"citation\">Yalk. Esth. 1053</span>, read <a href=\"#\" data-headword=\"סְטַרְטֵיגוֹס\">סְטַרְטֵיגוֹס</a> or <a href=\"#\" data-headword=\"אִסְטְרָא\">אִסְטְרָ׳</a> (<span class=\"citation\">Esth. R. to III, 1</span> <a href=\"#\" data-headword=\"טריכונוס\">טריכונוס</a>, read <span dir=\"rtl\">טריב׳</span>; v. <a href=\"#\" data-headword=\"ארטבון\">ארטבון</a>).</div>","alt":[]},"3072":{"h":"ארטיקנס","r":"A03072","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָרְסְקִינָס\">אַרְסְקִינָס</a></div>","alt":[]},"3073":{"h":"ארטל","r":"A03073","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְכִי I\">ארכי</a> <span dir=\"rtl\">ליפורין</span>.</div>","alt":["(א׳ ליפרן)"]},"3074":{"h":"אַרְטְלָאֵי","r":"A03074","html":"<div class=\"sense\">, v. <span dir=\"rtl\">עַרְטִילֵי</span></div>","alt":[]},"3075":{"h":"*ארטסיס","r":"A03075","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 13</span> <span dir=\"rtl\">וא׳ נכנס</span>, read: <span dir=\"rtl\">ואין רוטב נכנס בתוכה</span> but no juice enters into it, <span dir=\"rtl\">כך נעשה לבו של פרעה ולא היה מקבל וכ׳</span> so was Pharaoh’s heart made and it received not &amp;c.; v. <span class=\"citation\">Ter. X, 11</span>.</div>","alt":["ארסטוס","ארסיסיס"]},"3076":{"h":"אַרְטְקָפָא","r":"A03076","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀρτόκοπος) <i>baker</i>, <a href=\"#\" data-headword=\"אֶבֶן\">בית א׳</a> <i>bakery.</i> Midr. Sam. ch. XIX <span dir=\"rtl\">בית א׳ שלו</span> (Var. <a href=\"#\" data-headword=\"ארתוקופיון\">ארתוקופיון</a> q. v.) a rendition of <i>beth hallaḥmi</i>, <span class=\"citation\">I Sam. XVI</span>, </div><div class=\"sense\"><b>1)</b>  to his (Jesse’s) bakery, <span dir=\"rtl\">שהוא בא וכ׳</span> (read with <span class=\"citation\">Yalk. Sam. 124</span> <span dir=\"rtl\">והוא יבוא וכ׳</span>) and he (Jesse) shall come out (to the bakery) from Bethlehem (to meet Samuel there). Yalk. l. c. <a href=\"#\" data-headword=\"ארנקפאן\">ארנקפאן</a>, <span dir=\"rtl\">ארכ׳</span> (corr. acc.).</div>","alt":[]},"3077":{"h":"אֲרֵי","r":"A03077","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֲרִי I\">next w.</a>; cmp. <a href=\"#\" data-headword=\"אֲרוּ\">אֲרוּ</a>) prop. <i>behold</i>, in most cases corresponding to b. h. <a href=\"#\" data-headword=\"כִּי\">כִּי</a>, <i>that, so that, because, if; but</i>. Targ. O. <a href=\"#\" data-headword=\"ארי\">ארי</a>; Targ. Y. <span dir=\"rtl\">ארום</span>; v. fr.</div>","alt":["אֲרוּם"]},"3078":{"h":"אֲרִי I","r":"A03078","html":"<div class=\"sense\"> (√<span dir=\"rtl\">אר</span>, cmp. <a href=\"#\" data-headword=\"ירי\">ירי</a>) prop. <i>to point, throw</i>, hence (in a logical sense) <i>to argue, question, discuss, treat</i>. <span class=\"citation\">B. Kam. 30ᵇ</span> מדקא ארינן גלל Ar. (ed. <span dir=\"rtl\">איירינן</span>, v. infra) since we pointed out the law about the dung placed in the street as an argument against Rab. <span class=\"citation\">Keth. 16ᵃ</span>, a. fr. <span dir=\"rtl\">ודקארי לה מאי קארי לה</span> and he who raised the question, how could he raise it at all, i.e. the answer being so obvious, what must have been the impression he labored under, that he could ask such a question, or raise such an argument?—<span class=\"citation\">Y. Keth. VI, 30ᵈ</span> bot. <span dir=\"rtl\">ואין קמו יתמי ואָרוּן</span> if the heirs should rise and raise objections (go to law).</div><div class=\"sense\"><b>Af. אַיְירִי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"אֲרֵי\">same</a>. <span class=\"citation\">Ned. 2ᵇ</span> <span dir=\"rtl\">איירי בהון</span> he does treat thereof.—<span class=\"citation\">Pes. 6ᵇ</span>, a. fr. <span dir=\"rtl\">איידי דאיירי ב־</span> incidentally of treating the question of … <span class=\"citation\">Kerith. 14ᵃ</span>, a. fr. <span dir=\"rtl\">(<span dir=\"rtl\">באבר אחד</span>) <span dir=\"rtl\">קא מַיְירֵי</span></span> the argument is up (about one limb). <span class=\"citation\">B. Kam. 30ᵇ</span> <span dir=\"rtl\">כי איירינן</span> when we raised the objection (taking our argument from ‘the dung’, v. supra), it was before R. N. had given his opinion; a. fr.—Deriv. <a href=\"#\" data-headword=\"אִרְיָא\">אִרְיָא</a>.</div></div>","alt":["אֲרָא"]},"3079":{"h":"ארי","r":"A03079","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">ארר</span>) [<i>to create a gap</i>,] <i>to pluck</i>, esp. figs. <span class=\"citation\">Shebi. I, 2</span> <span dir=\"rtl\">הָאוֹרֶה וכ׳</span> the gatherer and his basket. <span class=\"citation\">B. Mets. 89ᵇ</span> day laborers <span dir=\"rtl\">שהיו אוֹרִין בתאנים</span> Ar. (ed. <span dir=\"rtl\">עודר׳</span>; v. Rabb. D. S. a. l. note 300) engaged in picking figs. <span class=\"citation\">Y. B. Bath. V, 15ᵃ</span> bot.; a. fr.—<span class=\"citation\">Num. R. s. 20</span> Tanḥ. Bal. 4 (homiletic etymology of <i>arah</i>, <span class=\"citation\">Num. XXII, 6</span>).</div>","alt":["אָרָה"]},"3080":{"h":"אֲרִי II","r":"A03080","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"ארי\">preced.</a>) [<i>the light-colored</i>] </div><div class=\"sense\"><b>1)</b> <i>lion</i>. <span class=\"citation\">B. Kam. 16ᵇ</span> <span dir=\"rtl\">א׳ תרבות</span> a tamed lion; a. fr.—Transf. <i>brave man; distinguished scholar</i> (opp. <span dir=\"rtl\">שועל</span>). <span class=\"citation\">Yeb. 122ᵇ</span>. <span class=\"citation\">Kidd. 48ᵇ</span>; <span class=\"citation\">Snh. 8ᵇ</span>. <span class=\"citation\">Gitt. 83ᵇ</span>; Y. ib. IX, 50ᵃ <span dir=\"rtl\">אין משיבין את הא׳ וכ׳</span> you must not argue against a lion (scholar) after he is dead. <span class=\"citation\">B. Kam. 117ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">אֲרָיוֹת</span>.—<span dir=\"rtl\">זנב לא׳</span> a tail to lions, i.e. the least among the great (opp. head to foxes). <span class=\"citation\">Ab. IV, 15</span>; <span class=\"citation\">Y. Snh. IV, 22ᵇ</span> bot.—<span class=\"citation\">Ḥull. 3ᵇ</span>, a. fr. <span dir=\"rtl\">גירי א׳</span>, v. <a href=\"#\" data-headword=\"גֵּר\">גֵּר</a>.—[<span class=\"citation\">Gen. R. s. 28</span> <span dir=\"rtl\">א׳ גסטריות</span>, v. <a href=\"#\" data-headword=\"גַּסְטְרָא\">גַּסְטְרָא</a>.]</div><div class=\"sense\"><b>—2)</b> <i>Leo, Lion</i> the fifth sign of the Zodiac (corresp. to the month of Ab). <span class=\"citation\">Yalk. Ex. 418</span>. Pesik. Dibré p. 116ᵃ; <span class=\"citation\">Pesik. R. s. 27</span> (<span class=\"citation\">28</span>, p. 133ᵇ, ed. Fr.); v. <a href=\"#\" data-headword=\"אֲרִיאֵל\">אֲרִיאֵל</a>.</div><div class=\"sense\"><b>—3)</b>  homiletic surname of <i>the Lord, Israel</i> &amp;c. Pesik. l. c.; Pesik. R. l. c.; <span class=\"citation\">Yalk. Jer. 259</span>, v. <a href=\"#\" data-headword=\"אֲרִיאֵל\">אֲרִיאֵל</a>.</div>","alt":["אַרְיֵה"]},"3081":{"h":"אֲרִי","r":"A03081","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Num. XXIV, 9</span>; a. fr.—<span class=\"citation\">B. Mets. 101ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"*אֲרַב\">אֲרב</a>. <span class=\"citation\">Ned. 62ᵇ</span> <span dir=\"rtl\">לאברוחי א׳</span> to drive the lion off, i.e. to get rid of the tax-collector.—<span class=\"citation\">Shebu. 22ᵇ</span>, a. fr. <span dir=\"rtl\">א׳ הוא דרביע עלה</span> a lion lies on it, i.e. it is unavailable because it is forbidden.—<span class=\"citation\">Ab. Zar. 31ᵇ</span>, a. e. <a href=\"#\" data-headword=\"אמוראי\">בר א׳</a> son of a lion (of a great man).—<span class=\"citation\">Ḥull. 59ᵇ</span> the tiger is <span dir=\"rtl\">א׳ דבי עילאי</span> the lion of the forest of Ilai (v. Schorr He-Ḥaluts VII, 32; cmp. Koh. Angelol. p. 103).—Pl. <span dir=\"rtl\">אַרְיָוָתָא</span>, <a href=\"#\" data-headword=\"אַרְיָוָא\">אַרְיָוָן</a>. <span class=\"citation\">Targ. I Chron. XI, 22</span>; a. fr.— <span class=\"citation\">Lam. R. to I, 9</span>) <span dir=\"rtl\">א׳ דאורייתא</span> the lions of the Law (scholars). Y. Shebi. IX, 39ᵃ top. <span class=\"citation\">Y. Sabb. I, 4ᵃ</span> top <span dir=\"rtl\">מעלי רישא בין א׳</span> to put one’s head between lions, i.e. to argue against the opinions of great men. [<span class=\"citation\">Yalk. Num. 771</span> <span dir=\"rtl\">גבתא דא׳</span>, v. <a href=\"#\" data-headword=\"אֲרִיחַ\">אֲרִיחַ</a>.]</div>","alt":["אַרְיָא","(אַרְיָוָא)"]},"3082":{"h":"אִרְיָא","r":"A03082","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרִי\">אֲרִי</a>, <a href=\"#\" data-headword=\"אֲרָא\">אֲרָא</a>) <i>pointing at, argument, topic, subject</i>. <span class=\"citation\">Kerith. 3ᵇ</span> <span dir=\"rtl\">גבי כריתות דאי׳ וכ׳</span> in speaking of K’rithoth, where this (the punishment of extinction) is the subject proper, I may say, the general term of Sabbath &amp;c. is introduced (relying on those places in the Mishnah where the respective laws are treated in detail). <span class=\"citation\">Yoma 74ᵃ</span>, a. fr. <span dir=\"rtl\">אי משום הא לא א׳</span> were it only for this, there would be no argument (no difficulty). <span class=\"citation\">Kerith. 18ᵃ</span>, a. fr. <span dir=\"rtl\">מאי א׳ כי וכ׳</span> why is the argument brought up only on the presumption (that he has eaten? Supposed, he had not eaten, would not the same argument hold good?). <span class=\"citation\">Sabb. 101ᵃ</span>, a. fr. <span dir=\"rtl\">מידי א׳</span> is this an argument (i.e. how can you compare two cases so unlike each other)?</div>","alt":["אִירְיָיא","אִירְיָא"]},"3083":{"h":"אֲרִיאֵל","r":"A03083","html":"<div class=\"sense\"> (b. h.) <i>Ariël, Divine Light</i> (cmp. <span class=\"citation\">Ps. CXVIII, 27</span>, v. <a href=\"#\" data-headword=\"אֲרִי II\"><span dir=\"rtl\">אֲרִי</span> II</a>); poetic surname of the Temple and Jerusalem. Pesik. Dibré p. 116ᵃ. <span class=\"citation\">Pesik. R. s. 27</span> (<span class=\"citation\">28</span>, p. 133ᵇ, ed. Fr.) <span dir=\"rtl\">הבית שנקרא אריה</span> (read <a href=\"#\" data-headword=\"אֲרִיאֵל\">אריאל</a>) the Temple which is called Ariël (<span class=\"citation\">Is. XXIX, 1</span>). Ib. <span dir=\"rtl\">ישראל שנקרא אריאל</span> (read <a href=\"#\" data-headword=\"אֲרִיחַ\">אריה</a>); <span dir=\"rtl\">בחדש שנקרא אריאל</span> (read <a href=\"#\" data-headword=\"אֲרִיחַ\">אריה</a>); <span dir=\"rtl\">דבריו של אריאל</span> (read <a href=\"#\" data-headword=\"אֲרִיחַ\">אריה</a>; <span class=\"citation\">Num. XXIII, 24</span>; <span class=\"citation\">Amos III, 8</span>); v. <a href=\"#\" data-headword=\"אַרְיֵה\">אַרְיֵה</a>.</div>","alt":[]},"3084":{"h":"אָרִיג","r":"A03084","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארג</span>) <i>something woven, web</i>. <span class=\"citation\">Sabb. XIII, 1</span>; a. fr. Y. M. Kat. III, end, 83ᵈ, what is meant by <a href=\"#\" data-headword=\"אִיחוּי\">אִיחוּי</a>? Ans. <span dir=\"rtl\">כאריג</span> when it looks as if woven. <span class=\"citation\">Meg. 26ᵇ</span>, a. e. <span dir=\"rtl\">טווי לא׳</span> spinning the flax so as to prepare it for weaving (indirect preparation or designation); <span class=\"citation\">Snh. 48ᵃ</span> <span dir=\"rtl\">טווי לאֲרִיגָה</span>, (Rashi <span dir=\"rtl\">לאריג</span>).</div>","alt":[]},"3085":{"h":"אֲרִיגָה","r":"A03085","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אָרִיג\">preced.</a>) <i>weaving</i>. <span class=\"citation\">Y. Yoma III, 40ᶜ</span> bot. <span dir=\"rtl\">אֲרִיגָתָן בקודש</span> their weaving must take place within the sanctuary. <span class=\"citation\">Snh. 48ᵃ</span>, v. <a href=\"#\" data-headword=\"אָרִיג\">preced.</a></div>","alt":[]},"3086":{"h":"אַרְיֵה","r":"A03086","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲרִי\">אֲרִי</a>.—אריה <span class=\"citation\">Y. Snh. X, 28ᵈ</span>, v. <a href=\"#\" data-headword=\"אֲרִיחַ\">אֲרִיחַ</a>.</div>","alt":[]},"3087":{"h":"*אריהון","r":"A03087","html":"<div class=\"sense\"> (prob. corruption of <a href=\"#\" data-headword=\"אֲרִיחַ\">אֲרִיחַ</a>) pr. n. pl.<span class=\"citation\">Cant. R. to II, 17</span> (ref. to <span dir=\"rtl\">הרי בתר</span> ibid. ‘mountains of cutting’) <span dir=\"rtl\">כדי שיטלו המלכיות בֶּתֶר א׳</span> (not <span dir=\"rtl\">שיתלו</span>, v. Matt. Keh. a. l.) that the (Roman) governments may receive (their pay for) the massacre of Ar. (cmp. Joseph. B. J. III, 10, 9 sq. or perh. ref. to the Bar Kokhba war; cmp. <span dir=\"rtl\">גופנית</span>, <span dir=\"rtl\">טור שמעון</span> a. oth. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> sq.).</div>","alt":[]},"3088":{"h":"אַרְיָוָא","r":"A03088","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲרִי\">אַרְיָא</a></div>","alt":[]},"3089":{"h":"אַרְיוֹךְ","r":"A03089","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (<span class=\"citation\">Gen. XIV, 1</span>) <i>Aryokh</i>, homiletic surname of Nebuzraddan. <span class=\"citation\">Lam. R. to V, 5</span> (allusion to <a href=\"#\" data-headword=\"ארי\">ארי</a>).</div><div class=\"sense\"><b>—2)</b>  (cmp. <span class=\"citation\">Dan. II, 14</span>) <i>Aryokh</i>, a title of Samuel, the contemporary of Rab. <span class=\"citation\">Sabb. 53ᵃ</span>. <span class=\"citation\">Kidd. 39ᵃ</span>. <span class=\"citation\">Men. 38ᵇ</span>. <span class=\"citation\">Ḥull. 76ᵇ</span> (prob. a Persian adaptation for <i>judge</i>).</div>","alt":[]},"3090":{"h":"*אַרְיוֹס","r":"A03090","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Arios</i>. <span class=\"citation\">Sifré Deut. 13</span>; <span class=\"citation\">Yalk. Deut. 802</span>.</div>","alt":[]},"3091":{"h":"אריוסטו","r":"A03091","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אורוסטי\">אורוסטי</a></div>","alt":[]},"3092":{"h":"אָרִיחַ","r":"A03092","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארח</span>) </div><div class=\"sense\"><b>1)</b> <i>bond-timber</i>, also <i>small bricks</i>, which are placed at intervals between the rows of bricks (v. Sm. Ant. s. v. Paries II); <i>lath</i> (of half the width of a brick). <span class=\"citation\">Erub. I, 3</span>; <span class=\"citation\">B. Bath. 3ᵇ</span>; a. e.—Pl. <span dir=\"rtl\">אָרִיחִין</span>. <span class=\"citation\">Y. Erub. I, 19ᵃ</span> top <span dir=\"rtl\">ארחין</span> (corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>ariaḥ</i>, a term used in rules for writing certain passages of Holy Scriptures metrically arranged, <i>the short space filled out with writing</i>, opp. <span dir=\"rtl\">לבנה</span> (brick, the larger space); v. R. Niss. to <span class=\"citation\">Meg. 16ᵇ</span>; [Rashi: <a href=\"#\" data-headword=\"א׳\">א׳</a> <i>the writing</i>, <span dir=\"rtl\">לבנה</span> <i>the blank</i>). <span class=\"citation\">Y. Meg. III, 74ᵇ</span> bot.; Bab. ib. l. c.; <span class=\"citation\">Treat. Sof’rim XII, 10</span> <span dir=\"rtl\">א׳ ע&quot;ג ל׳ וכ׳</span> small brick (lath) above brick, and brick above small brick (lath); e.g. (<span class=\"citation\">Ex. ch. XV</span>)ויאמרו לאמר\tאשירה לד׳ כי גאה גאה\tסוסורכבו רמה בים\tעזי וזמרת יה ויהי ליIb. <span dir=\"rtl\">א׳ ע׳&#x27;ג א׳ וכ׳</span> small brick (lath) above small brick and brick above brick; e.g. (<span class=\"citation\">Esth. IX, 7</span> sq.)פרשנדתא\tואתדלפון\t<span dir=\"rtl\">ואת</span></div>","alt":[]},"3093":{"h":"אֲרִיחַ","r":"A03093","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ăriaḥ</i>; [Tarichæa, South of Tiberias, Neub. Géogr. p. 21ᵇ]. <span class=\"citation\">Y. Snh. X, 28ᵈ</span> <span dir=\"rtl\">גופתה א׳</span>; <span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">גובתא דא׳</span>; <span class=\"citation\">Yalk. Num. 771</span> <span dir=\"rtl\">דאריא</span> (Y. l. c. ed. Zyt. <a href=\"#\" data-headword=\"אֲרִיחַ\">אריה</a>) Gufta in the district of Ariaḥ. <span class=\"citation\">Tosef. Kil. I, 3</span>; Y. ib. I, 27ᵃ bot. <span dir=\"rtl\">תחום א׳</span> district of A.</div>","alt":["(אריה","אריא)"]},"3094":{"h":"אָרִיחָא","r":"A03094","html":"<div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אָרִיחַ\">אָרִיחַ</a>) <i>lath, bar, pole</i>. <span class=\"citation\">Targ. Num. XIII, 23</span>; a. e. (h. <a href=\"#\" data-headword=\"מוֹט\">מוֹט</a>). <span class=\"citation\">Bets. 32ᵇ</span> <span dir=\"rtl\">נפל לה ארי׳ בתנורא</span> ed. (Ar. <span dir=\"rtl\">ארחא</span>) a binder of the brick wall fell into the stove. <span class=\"citation\">Sabb. 129ᵃ</span> a house <span dir=\"rtl\">דשב לביניא וא׳</span> the width of whose walls was seven bricks and a half; a. e.—Pl. <span dir=\"rtl\">אָרִיחַיָּא</span>, <span dir=\"rtl\">אֲרִיחִין</span>, <span dir=\"rtl\">אַרְחֵי</span>, <span dir=\"rtl\">אַרְחִין</span>. <span class=\"citation\">Targ. Ex. XXV, 27</span>; a. e. (h. <span dir=\"rtl\">בַּדִּים</span>). <span class=\"citation\">B. Bath. 3ᵃ</span> כפיסין ארחי K’fissin are bondlaths. <span class=\"citation\">Y. Erub. I, 19ᵃ</span> top (also <span dir=\"rtl\">אורחין</span>).</div>","alt":["אַרְחָא"]},"3095":{"h":"אֲרִיךְ I","r":"A03095","html":"<div class=\"sense\"><i>to be long, to project</i>. <span class=\"citation\">Targ. I Kings VIII, 8</span>; <span class=\"citation\">II Chr. V, 9</span>.—<span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> top, v. <a href=\"#\" data-headword=\"אִימָמָא\">אִימָמָא</a>.</div><div class=\"sense\"><b>Af. אוֹרֵיךְ</b> <div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"אָרֵךְ\">אָרֵךְ</a> </div><div class=\"sense\"><b>1)</b> <i>to be prolonged; to lengthen</i>. <span class=\"citation\">Targ. Ex. XX, 12</span>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 67</span> <a href=\"#\" data-headword=\"מָאַרְכָן\">מְאַרְכַן</a> make appear long; a. fr.—Y. Taan. IV, 68ᵃ <span dir=\"rtl\">מְאַרְכָה יומין</span> to live long; <span class=\"citation\">Koh. R. to VII, 7</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be tall</i>. <span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">כי מאריך</span> when one was tall.</div><div class=\"sense\"><b>—3)</b> <i>to tarry, wait, hope</i>. <span class=\"citation\">Targ. Num. IX, 22</span>. <span class=\"citation\">Targ. Job VI, 11</span>.—Y. Yoma VI, 43ᵈ <span dir=\"rtl\">אורכין צבחר</span> wait a while. Y. R. Hash. I, 57ᵃ bot. <span dir=\"rtl\">הוות מוֹרְכָה וכ׳</span> she waited a whole year. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הוו מורכין</span>. Y. M. Kat. II, 81ᵇ top <span dir=\"rtl\">אילפא מורכא לך</span> the ship will wait for thee.</div></div>","alt":[]},"3096":{"h":"אֲרִיךְ II","r":"A03096","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרִיךְ I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>long</i>. <span class=\"citation\">Targ. Ezek. XVII, 3</span>.—<span class=\"citation\">Targ. Prov. XIV, 17</span> <span dir=\"rtl\">דא׳ תרעיתיה</span> whose intrigue is long prepared (h. <span dir=\"rtl\">איש מזמות</span>). V. <a href=\"#\" data-headword=\"אֲרִיכָא\">אֲרִיכָא</a></div><div class=\"sense\"><b>—2)</b>  (part. pass. of <a href=\"#\" data-headword=\"אֲרַךְ\">אֲרַךְ</a> <i>to arrange</i>) <i>right, befitting.</i> <span class=\"citation\">Ezra IV, 14</span>.—<span class=\"citation\">Succ. 4ᵇ</span> <span dir=\"rtl\">א׳ או לא א׳</span> is it right or not? <span class=\"citation\">B. Mets. 75ᵃ</span> <span dir=\"rtl\">וא׳</span> and it is proper to do so. <span class=\"citation\">Midr. Till. to Ps. I, 2</span> <span dir=\"rtl\">וא׳ כדין</span> is such a thing right?</div>","alt":["אֲרִיכָא"]},"3097":{"h":"אָרִיךְ","r":"A03097","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרִיךְ II\">preced.</a>) <i>prolonging, retarding</i>. <span class=\"citation\">Targ. Y. I Num. XIV, 18</span> (<span class=\"citation\">II</span> <span dir=\"rtl\">א׳ רחמין</span>, read <span dir=\"rtl\">רוחיה</span>).</div>","alt":[]},"3098":{"h":"אָרֵיךְ","r":"A03098","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"אֲרִיךְ II\"><span dir=\"rtl\">אֲרִיךְ</span> II</a>, 2) <i>preparing, dressing</i>. <span class=\"citation\">Sabb. 33ᵇ</span> <span dir=\"rtl\">הוא קא א׳ ליה לבישריה</span> was dressing (cleansing) his body. <span class=\"citation\">Keth. 103ᵇ</span> ואָרֵיכְנָא וכ׳ I would dress parchment rolls of deer skins.</div>","alt":[]},"3099":{"h":"אָרֵיכָא","r":"A03099","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָרֵיךְ\">preced.</a>) [one who arranges arguments,] <i>Arekha</i>, title of a lecturer. <span class=\"citation\">Sabb. 59ᵇ</span> <span dir=\"rtl\">גברא רבה א׳</span> a great man, a lecturer. Esp. known R. <i>Aḥa Arekha</i>. <span class=\"citation\">Ib. 111ᵃ</span>; a. e. <span class=\"citation\">Ber. 33ᵃ</span> ed. (Ms. M. Ḥiya); <i>Abba Arekha</i> (Rab, v. <a href=\"#\" data-headword=\"רַב\">רַב</a>). [In legend: <i>tall</i>, v. <a href=\"#\" data-headword=\"אָרוּךְ\">אָרוּךְ</a>.]</div>","alt":[]},"3100":{"h":"*אֲרֵיכָא","r":"A03100","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָרֵיכָא\">preced.</a>) <i>theme of a lecture</i>. Midr. Till., beg. <span dir=\"rtl\">עבד לה א׳</span> used that idea of R. Yudan as a theme.</div>","alt":[]},"3101":{"h":"אֲרִיכָא","r":"A03101","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֲרִיךְ II\"><span dir=\"rtl\">אֲרִיךְ</span> II</a>) <i>long, prolonged</i>. <span class=\"citation\">Bets. 30ᵇ</span> יומא א׳ Ms. M. (ed. <span dir=\"rtl\">אריכתא</span>); <span class=\"citation\">Succ. 45ᵇ</span> <span dir=\"rtl\">יומא א׳</span> an adjourned day.—Fem. <span dir=\"rtl\">אֲרִיכְתָּא</span>. <span class=\"citation\">Ber. 4ᵇ</span> <span dir=\"rtl\">תפלה א׳</span> a continued prayer; <span dir=\"rtl\">גאולה א׳</span> a continued benediction on redemption, v. <a href=\"#\" data-headword=\"גְּאוּלָּה\">גְּאוּלָּה</a>.—Pl. <a href=\"#\" data-headword=\"אֲרִיכוּתָא\">אֲרִיכָתָא</a>. <span class=\"citation\">Keth. 8ᵃ</span> <span dir=\"rtl\">שית א׳</span> the six lengthy benedictions.</div>","alt":[]},"3102":{"h":"אֲרִיכָה","r":"A03102","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ארך\">ארך</a>) <i>prolongation, length;</i> (sub. <a href=\"#\" data-headword=\"אַף I\">אף</a>, or <span dir=\"rtl\">פנים</span>) <i>forbearance</i>. <span class=\"citation\">Koh. R. to VII, 8</span> <span dir=\"rtl\">א׳ שהאריך וכ׳</span> the forbearance which Samuel showed. <span class=\"citation\">Gen. R. s. 70</span> <span dir=\"rtl\">א׳ פנים</span>. <span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> bot.; a. e. <span dir=\"rtl\">א׳ ימים</span> length of days, long life.—<span class=\"citation\">Gen. R. s. 64</span> <span dir=\"rtl\">א׳ ימים</span> lapse of time.</div>","alt":["אֲרִיכוּת"]},"3103":{"h":"אֲרִיכוּתָא","r":"A03103","html":"<div class=\"sense\"><span class=\"citation\">Targ. Is. XXXVIII, 11</span>.</div>","alt":[]},"3104":{"h":"אֲרֵיכוּתָא","r":"A03104","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֲרִיךְ II\"><span dir=\"rtl\">אֲרִיךְ</span> II</a>, </div><div class=\"sense\"><b>2)</b> <i>preparation, future</i> (v. <span dir=\"rtl\">ורך</span>, Schr. KAT p. 549). <span class=\"citation\">Targ. Jer. XXXI, 5</span>.</div>","alt":[]},"3105":{"h":"אֲרִים","r":"A03105","html":"<div class=\"sense\"><b>,</b> pr. n. <i>Arim</i> (Arum). <span class=\"citation\">Y. Ḥag. I, 76ᶜ</span> bot.; <span class=\"citation\">Y. Pes. III, end, 30ᵇ</span> <span dir=\"rtl\">עליית בית א׳</span>, v. <a href=\"#\" data-headword=\"עֲלִיָּה\">עֲלִייָּה</a>; (<span class=\"citation\">Sifré Deut. 41</span> <a href=\"#\" data-headword=\"עָרוֹד\">ערוד</a>; <span class=\"citation\">Yalk. ib. 681</span> <a href=\"#\" data-headword=\"שְׁעָרִים\">שערים</a>; <span class=\"citation\">Kidd. 40ᵇ</span> <a href=\"#\" data-headword=\"נִתזָה\">נתזה</a>).</div>","alt":["(אֲרוּם)"]},"3106":{"h":"אֱרִימִין","r":"A03106","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἔρημα, τὰ) <i>desert, wilderness</i>. <span dir=\"rtl\">מקום א׳</span> a settlement in a desert. <span class=\"citation\">Lev. R. s. 35</span> (ed. <span dir=\"rtl\">אדרימון</span>, Ar. <span dir=\"rtl\">ארימון</span>, corr. acc.). <span class=\"citation\">Cant. R. to VII, 11</span>.—<span class=\"citation\">Yalk. Jer. 257</span> <a href=\"#\" data-headword=\"אֱירִימוֹן\">אירימון</a>, cmp. <a href=\"#\" data-headword=\"אֱירֵימִיאָה\">אֱירֵימִיאָה</a>.</div>","alt":[]},"3107":{"h":"*אָרִיס I","r":"A03107","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארס</span>) <i>something tied to the body</i> (περίαμμα), whence <i>an emblem set in a ring or chain</i> (cmp. <span class=\"citation\">Deut. VI, 8</span>; <span class=\"citation\">Prov. VI, 21</span>, also Sm. Ant. s. v. Amuletum). . <span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">הכניסה לו שנים א׳</span> (read <a href=\"#\" data-headword=\"שני\">שני</a>) brought into his house two emblems (of faith); the king, too, <span dir=\"rtl\">זקף לה כנגדן שני א׳</span> had two corresponding emblems set for her. Ib. Abraham delivered to his children <span dir=\"rtl\">שני א׳</span> two emblems (which they should guard, <span class=\"citation\">Gen. XVIII, 19</span>).</div>","alt":[]},"3108":{"h":"אָרִיס II","r":"A03108","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארס</span>) prop. <i>bound, engaged</i>, esp. <i>tenant</i> who tills the owner’s ground for a certain share in the produces, contrad. fr. <span dir=\"rtl\">חכור</span> tenant who pays the landlord a certain rent in kind, irrespective of the yield of the crops. Y. Bicc. I, end, 64ᵇ. <span class=\"citation\">Y. B. Bath. III, 14ᵃ</span> bot. <span dir=\"rtl\">א׳ שהוריד א׳</span> a farmer letting to a sub-farmer. <span class=\"citation\">Ex. R. s. 43</span>. <span class=\"citation\">Lev. R. s. 1</span> <span dir=\"rtl\">אֲרִיסוֹ</span> his (the king’s) tenant, i.e. Adam (in paradise); a. fr.—Pl. <span dir=\"rtl\">אֲרִיסִים</span>, <a href=\"#\" data-headword=\"אֲנִיסִין\">אֲרִיסִין</a>. Y. B. Bath. l. c. Y. M. Kat. III, 82ᵇ bot. <span class=\"citation\">Deut. R. s. 7</span>; a. fr.—Cmp. <a href=\"#\" data-headword=\"עָרִיס\">עָרִיס</a>.</div>","alt":[]},"3109":{"h":"אָרִיס","r":"A03109","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"אָרִיס II\">same</a>, also <i>field laborer</i>. <span class=\"citation\">Targ. Y. Deut. XXIII, 25</span>; <span class=\"citation\">26</span> Levita (ed. <a href=\"#\" data-headword=\"פּוֹעֵל\">פועל</a>). <span class=\"citation\">Targ. Cant. VIII, 11</span>.—<span class=\"citation\">Ab. Zar. 21ᵇ</span> <span dir=\"rtl\">א׳ אריסותיה קעביד</span> the gentile tenant working during the Jewish festive week, works for his tenancy (not as the Jew’s employee). <span class=\"citation\">Ḥag. 25ᵇ</span> <span dir=\"rtl\">דינא הוא … א׳ וכ׳</span> it is the tenant’s business to procure kegs &amp;c.—*<span class=\"citation\">B. Bath. 55ᵃ</span> דאריסא דפרסאי עד וכ׳ Rashb. a. l. (ed. <span dir=\"rtl\">אריסותא</span>, Var. <span dir=\"rtl\">דאֲרִישָׂן</span>, <span dir=\"rtl\">שָׂאִין …</span>, <span dir=\"rtl\">דאֲרִישָׂאָן</span>, v. Rabb. D. S. a. l. note, Ms. M. <span dir=\"rtl\">דאריש׳</span>) that the tenant of the Persians is such only up to forty years (after which time he is considered a legitimate owner); v. Nim. Jos. to Alf. a. l. [It seems that the Pers. Jews pronounced <a href=\"#\" data-headword=\"אֲרִישָׂא\">אֲרִישָׁא</a> a. <a href=\"#\" data-headword=\"אֲרִישְׂתָּא\">אֲרִישׁוּתָא</a>, cmp. <a href=\"#\" data-headword=\"דִּישְׁתָּנָא\">דִּישְׁתָּנָא</a> a. <a href=\"#\" data-headword=\"דִּיסְתָּנָא\">דִּיסְתָּנָא</a>.]—Pl. <span dir=\"rtl\">אֲרִיסַיָּא</span>. <span class=\"citation\">Targ. Job XXIX, 23</span>. <a href=\"#\" data-headword=\"אֲרִישָׂא\">אֲרִישָׂאִין</a>, v. supra. [<span class=\"citation\">Lev. R. s. 28</span>, v. <a href=\"#\" data-headword=\"אֲרִיסְטָא\">אֲרִיסְטָא</a>.]</div><div class=\"sense\"><b>—2)</b> <i>betrothed</i>, v. <a href=\"#\" data-headword=\"אֲרַס\">אֲרַס</a>.</div>","alt":["אֲרִיסָא","אֲרִישָׂא"]},"3110":{"h":"אֲרִיס","r":"A03110","html":"<div class=\"sense\"><i>poison</i>, v. <a href=\"#\" data-headword=\"אֶרֶס\">אֶרֶס</a> ch.</div>","alt":["אֲרִיסָא"]},"3111":{"h":"אֲרִיסָה","r":"A03111","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Kel. B. Bath. IV, 8</span>; v. <a href=\"#\" data-headword=\"עֲרִיסָה\">עֲרִיסָה</a></div>","alt":[]},"3112":{"h":"אֲרִיסוּת","r":"A03112","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אָרִיס II) <i>tenancy, condition of the Aris</i>. <span class=\"citation\">Peah V, 5</span> <span dir=\"rtl\">בא׳</span> as a tenancy; a. fr.—Pl. <span dir=\"rtl\">אֲרִיסִיּוֹת</span>. <span class=\"citation\">Y. Bicc. I, end, 64ᵇ</span> <span dir=\"rtl\">בעלי א׳</span> owners of tenanted properties, v. <a href=\"#\" data-headword=\"חֲכִינָה\">חֲכִירָה</a>.</div>","alt":[]},"3113":{"h":"אֲרִיסוּתָא","r":"A03113","html":"<div class=\"sense\"><span class=\"citation\">Lev. R. s. 5</span>. <span class=\"citation\">Ab. Zar. 21ᵇ</span>; a. e. <span class=\"citation\">B. Bath. 55ᵃ</span>, v. <a href=\"#\" data-headword=\"אָרִיס\">אֲרִיסָא</a>. [<span class=\"citation\">M. Kat. 22ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲרִישְׂתָּא\">אֲרִישְׂתָּא</a>.]</div>","alt":[]},"3114":{"h":"אֲרִיסְטָא","r":"A03114","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (corrupt. of <span dir=\"rtl\">אריסטיטא</span>, ἀριστητής) <i>break-fasting</i>, in gen. <i>invited guest.</i> Pl. <span dir=\"rtl\">אֲרִיסְטִין</span>, <span dir=\"rtl\">אֲרִיסְטַיָּיא</span>. <span class=\"citation\">Koh. R. to I, 3</span> <span dir=\"rtl\">שביק א׳ וכ׳</span> let the guests eat (some ed. <a href=\"#\" data-headword=\"אֲרִיסְטוֹן I\">אריסטון</a>, <i>our guests?</i>). <span class=\"citation\">Lev. R. s. 28</span> <span dir=\"rtl\">אריסייא</span> (corr. acc.). <span class=\"citation\">Lam. R. to IV, 2</span> <span dir=\"rtl\">ביני א׳</span> among the seated guests.</div>","alt":[]},"3115":{"h":"אֲרִיסְטוֹבּוֹלוֹס","r":"A03115","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Ἀριστόβουλος) <i>Aristobule</i>, brother of Hyrcan, son of Alexander Jannai. <span class=\"citation\">Men. 64ᵇ</span>; <span class=\"citation\">B. Kam. 82ᵇ</span>; a. e.</div>","alt":["אֲרִיסְטוֹבְלוֹס"]},"3116":{"h":"אריסטוון","r":"A03116","html":"<div class=\"sense\">, read:</div>","alt":[]},"3117":{"h":"אֲרִיסְטוֹן I","r":"A03117","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἄριστον) orig. <i>morning meal</i>, later <i>principal meal, dinner, repast</i>. <span class=\"citation\">Y. Ber. IV, 7ᵇ</span> <span dir=\"rtl\">אין הווה לכון א׳ כ׳</span> if ye are invited to a dinner, and the day is advanced, &amp;c. <span class=\"citation\">Y. Snh. III, 21ᶜ</span> top <span dir=\"rtl\">גו א׳</span> during dinner. Ib. VI, 23ᶜ; a. fr.</div>","alt":[]},"3118":{"h":"אֲרִיסְטוֹן II","r":"A03118","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ariston</i>. <span class=\"citation\">Ḥall. IV, 11</span>; <span class=\"citation\">Y. Shebi. VI, end, 37ᵃ</span> (a Syrian land-owner).—Y. Yeb. XVI, end, 16ᵃ <span dir=\"rtl\">חד א׳</span> one Ariston. [‘<i>One of the</i> βουλὴ ἀριστῶν mentioned Cod. Theod. Lib. XII, Tit. 888, Frankel M’bo p. 65ᵃ.]</div>","alt":[]},"3119":{"h":"אֲרִירָה","r":"A03119","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ארר</span>) <i>cursing, imprecation</i>. <span class=\"citation\">Y. Ber. IV, 8ᶜ</span> (play on <i>Aron</i>, the ark) from there <span dir=\"rtl\">א׳ יוצאה לעולם</span> curse goes forth into the world (for transgressors); a. e.</div>","alt":[]},"3120":{"h":"אֲרִירָן","r":"A03120","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲרָרָן\">אֲרָרָן</a></div>","alt":[]},"3121":{"h":"אֲרִישָׂא","r":"A03121","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָרִיס\">אֲרִיסָא</a></div>","alt":["אֲרִישָׁא","ארישאין","ארישאן","ארישן"]},"3122":{"h":"אֲרִישְׂתָּא","r":"A03122","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*אָרַשׁ\">ארשׁ</a>, v. <span dir=\"rtl\">ארס</span>) prop. <i>obligation</i>, hence (sub. <span dir=\"rtl\">סעודת</span>) <i>a meal which creates an obligation, a meal which is given in the expectation of receiving invitations from the reciprocating members of a social club</i>, opp. <a href=\"#\" data-headword=\"פּוּרְעָן\">פורענא</a> the entertainment in reciprocation for invitations received. <span class=\"citation\">M. Kat. 22ᵇ</span> אריש׳ Ar. (ed. <span dir=\"rtl\">אריסותא</span>, Ms. M. <span dir=\"rtl\">ארשיותא</span>, read <span dir=\"rtl\">ארישו׳</span>).</div>","alt":["אֲרִישְׁתָּא","(אֲרִישׁוּתָא","אֲרִיסוּתָא)"]},"3123":{"h":"אֲרִיתָא","r":"A03123","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארת</span>, √<span dir=\"rtl\">אר</span>, cmp. <a href=\"#\" data-headword=\"יְאוֹר\">יְאוֹר</a>) <i>cut, channel, dyke</i> <span class=\"citation\">Targ. Ps. CVII, 35</span> (h. text <a href=\"#\" data-headword=\"אַגָּם\">אגם</a>); a. e.—<span class=\"citation\">Ḥull. 107ᵃ</span> <span dir=\"rtl\">א׳ דדלאי</span> dyke for irrigation. <span class=\"citation\">B. Kam. 50ᵇ</span> sq.—Pl. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"אֲרִיתָא\">אֲרִיתַּ׳</a>) <a href=\"#\" data-headword=\"אֲרִיתָא\">אֲרִיתַיָּא</a></span>. <span class=\"citation\">Targ. O. Ex. VIII, 11</span>. <span class=\"citation\">Targ. Ps. LXXVIII, 44</span>. (h. text <a href=\"#\" data-headword=\"יְאוֹר\">יְאֹר</a>); a. e. Cmp. <a href=\"#\" data-headword=\"חָרִיץ\">חריץ</a>.</div>","alt":["(אֲרִיתָּא)"]},"3124":{"h":"ארך","r":"A03124","html":"<div class=\"sense\"> (√<span dir=\"rtl\">אר</span>, cmp. <span dir=\"rtl\">ארג</span>) <i>to join, weave;</i> whence <i>to arrange, plan;</i> v. <span dir=\"rtl\">ערך</span>.—V. <a href=\"#\" data-headword=\"אֲרִיךְ II\"><span dir=\"rtl\">אֲרִיךְ</span> II</a></div>","alt":[]},"3125":{"h":"אָרֵךְ","r":"A03125","html":"<div class=\"sense\"> , cmp. Schr. KAT p. 497 <span dir=\"rtl\">ארג</span>; cmp. also <span dir=\"rtl\">גדל</span> to <i>plait</i>,to<i> be tall</i>) to <i>be</i> [<i>pointed, stretched</i>,] <i>long, tall</i>.</div><div class=\"sense\"><b>Hif. הֶאֱרִיךְ</b> <div class=\"sense\"><b>1)</b> <i>to prolong, be long in doing</i>. <span class=\"citation\">Ber. I, 4</span> <span dir=\"rtl\">אמרו להַאֲרִיךְ</span> they commended a lengthy benediction. <span class=\"citation\">Ib. 34ᵃ</span>; cmp. <a href=\"#\" data-headword=\"אַרְכָן I\">אַרְכָן</a>. <span class=\"citation\">Yoma 35ᵇ</span> <span dir=\"rtl\">הֶאֱ׳ בתפלתו</span> staid long in prayer.—הא׳ ימים <i>to live long</i>. <span class=\"citation\">Meg. 27ᵇ</span>; a. fr.—<span class=\"citation\">Ber. 8ᵇ</span>, a. fr. <span dir=\"rtl\">מַאֲרִיכִין ימיו</span> his life will be prolonged.—<span dir=\"rtl\">פנים</span>, <span dir=\"rtl\">הא׳ רוח</span> <i>to be long-suffering, forbearing.</i> Y. Shebu. IV, beg. 35ᵇ; a. fr.—Y. Taan. II, 65ᵇ bot. when collecting debts (punishing) <span dir=\"rtl\">מאריך וגובה</span> he is slow in collecting (punishes in long intervals, gives extension).</div><div class=\"sense\"><b>—2)</b> <i>to be long, last long</i>. <span class=\"citation\">Num. R. s. 20</span>, end <span dir=\"rtl\">הא׳ הברזל</span> the point of the spear grew longer, v. infra; a. fr.</div><div class=\"sense\"><b>—3)</b>  [<i>to lengthen the carrying pole</i>,] <i>to make heavy</i>. <span class=\"citation\">Nidd. 16ᵇ</span> <span dir=\"rtl\">כמה הֶאֱרַכְתָּ עלינו</span> how heavy thou hast made our burden (through restrictive laws)!</div></div><div class=\"sense\"><b>Nif. נֶאֱרַךְ</b> <div class=\"sense\"><i>to be prolonged, grow longer</i>. <span class=\"citation\">Sifré Num. 131</span>; <span class=\"citation\">Yalk. ib. 771</span>; (Num. R. l. c. <a href=\"#\" data-headword=\"אָרֵךְ\">האריך</a>).</div></div>","alt":["ארַךְ"]},"3126":{"h":"אֲרַךְ","r":"A03126","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲרִיךְ I\"><span dir=\"rtl\">אֲרִיךְ</span> I</a></div>","alt":[]},"3127":{"h":"אֶרֶךְ","r":"A03127","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) only with <a href=\"#\" data-headword=\"אַף I\">אַף</a>, <span dir=\"rtl\">אֲפַּיִם</span> <i>long-suffering, forbearing</i>. <span class=\"citation\">Y. Taan. II, 65ᵇ</span>; a. fr.; v. <a href=\"#\" data-headword=\"אַף I\">אַף</a>.</div>","alt":[]},"3128":{"h":"אַרְכָא I","r":"A03128","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ארך\">ארך</a>; cmp. <a href=\"#\" data-headword=\"אוּרְבָּא\">אוּרְבָּא</a>); pl. <a href=\"#\" data-headword=\"אַרְכִי I\">אַרְכֵי</a> <i>meshes, ranges, intervals</i>. <span class=\"citation\">Sabb. 50ᵇ</span>. <span class=\"citation\">Gitt. 69ᵇ</span>. <span class=\"citation\">B. Bath. 3ᵃ</span>, v. <a href=\"#\" data-headword=\"אוּרְבָּא\">אוּרְבָּא</a>.—<span class=\"citation\">Targ. Esth. VIII, 15</span> <span dir=\"rtl\">בארכוהי</span> in its (the girdle’s) meshes.</div>","alt":[]},"3129":{"h":"אַרְכָא II","r":"A03129","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ארך\">ארך</a>) <i>duration, term, limit; extension of time.</i> <span class=\"citation\">Dan. IV, 24</span> (prolongation). <span class=\"citation\">Ib. VII, 12</span> (set term).—<span class=\"citation\">Targ. Gen. VI, 3</span>; a. e.</div>","alt":["אַרְכָּא","אַרְכָה"]},"3130":{"h":"אַרְכָא III","r":"A03130","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"אֲרוּכָה I\">אֲרוּכָה</a>) <i>healing, restoration</i>. <span class=\"citation\">Targ. II Chr. XXIV, 13</span>.—Pl. <span dir=\"rtl\">(<span dir=\"rtl\">אֲרוּכִין</span>) <span dir=\"rtl\">אַרְכִין</span></span>. <span class=\"citation\">Targ. Ps. CXLVII, 3</span> (ed. Vien. <a href=\"#\" data-headword=\"אַרְכָא II\">ארכא</a>).</div>","alt":[]},"3131":{"h":"*אַרְכַּבְתָּא","r":"A03131","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רכב</span>) (a rider,) <i>the uppermost layer of a clay dam around a field</i>. <span class=\"citation\">B. Mets. 103ᵇ</span> <a href=\"#\" data-headword=\"בּוּכְרָא I\">בוכרא</a> the first, <span dir=\"rtl\">טפתא</span> the additional (middle), <a href=\"#\" data-headword=\"א׳\">א׳</a> the uppermost. [<span class=\"citation\">Targ. Y. Lev. IX, 17</span> read <a href=\"#\" data-headword=\"אַדְכַּרְתָּא\">אַדְכַּרְתָּהּ</a>.]</div>","alt":[]},"3132":{"h":"אַרְכָה","r":"A03132","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"אַרְכָא II\"><span dir=\"rtl\">אַרְכָא</span> II</a>) <i>extension, a certain time</i>. <span class=\"citation\">Num. R. s. 14</span> (p. 259ᵃ ed. Amst.) <span dir=\"rtl\">נתן להם א׳ וכ׳</span> allowed them a certain time but finally punished them.</div>","alt":[]},"3133":{"h":"אַרְכּוּבָא","r":"A03133","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אַרְכּוּבְתָּא\">אַרְכּוּבְתָּא</a>.</div>","alt":[]},"3134":{"h":"אַרְכּוּבָה","r":"A03134","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רכב</span>) </div><div class=\"sense\"><b>1)</b> <i>the leg from under the hip-bone to the ankle, the knee and its surrounding parts</i> (containing three sections each of which is called <a href=\"#\" data-headword=\"א׳\">א׳</a> and defined by a different surname). <span class=\"citation\">Ḥull. IV, 6</span>; v. <span class=\"citation\">ib. 76ᵃ</span> (also <a href=\"#\" data-headword=\"רְכוּבָה\">רְכוּבָה</a>); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>anything joined, joint.</i> <span class=\"citation\">Kil. VII, 1</span> <span dir=\"rtl\">הא׳ שבגפן</span> (<span class=\"citation\">Tosef. ib. IV, 11</span>, Var. <span dir=\"rtl\">הבריכה שבסלע</span>) that part of the vine which is bent down and laid in the ground to rise at another place. <span class=\"citation\">Y. Meg. I, 71ᶜ</span> bot. <span dir=\"rtl\">א׳ של למ&quot;ד</span> the lower joint of the Lammed. <span class=\"citation\">Kel. XIV, 8</span> <span dir=\"rtl\">מפתח של א׳ וכ׳</span> (<span class=\"citation\">Tosef. Kel. B. Mets. IV, 15</span> <span dir=\"rtl\">רוֹכְבָּה … רְכוּבָתוֹ</span>) a key with a joint, broken at the joint.—Pl. <span dir=\"rtl\">אַרְכּוּבוֹת</span>. <span class=\"citation\">Nidd. 30ᵇ</span>. <span class=\"citation\">B. Mets. 105ᵃ</span></div>","alt":[]},"3135":{"h":"אַרְכּוּבְתָּא","r":"A03135","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Esth. V, 9</span>. [<span class=\"citation\">Y. Maasr. V, end, 52ᵃ</span> <span dir=\"rtl\">אביבא דפילא</span>, read <a href=\"#\" data-headword=\"אַרְכּוּבָא\">ארכובא</a> or <a href=\"#\" data-headword=\"עֲנִיבָה I\">עניבה</a>; <span class=\"citation\">Y. Ned. III, 37ᵈ</span> bot.; <span class=\"citation\">Y. Shebu. III, 34ᵈ</span>.]—Pl. <a href=\"#\" data-headword=\"אַרְכּוּבְתָּא\">אַרְכּוּבָתָא</a>. <span class=\"citation\">Targ. Koh. XII, 3</span>. Targ. II, <span class=\"citation\">Esth. VI, 11</span>.—אַרְכּוּבַיָּא <span class=\"citation\">Targ. Job. IV, 4</span>.—V. <a href=\"#\" data-headword=\"רְכוּבְתָּא\">רְכוּבְתָּא</a>.</div>","alt":[]},"3136":{"h":"ארכוליפורין","r":"A03136","html":"<div class=\"sense\">, v. <span dir=\"rtl\">ארכי׳</span></div>","alt":[]},"3137":{"h":"אַרְכוֹן","r":"A03137","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אַרְכָן I\">אַרְכָן</a> q. v.) <i>ruler, elder</i> <span class=\"citation\">Targ. I Chr. XI, 2</span> (h. text <a href=\"#\" data-headword=\"נָגִיד I\">נגיד</a>). <span class=\"citation\">Targ. Job. XXI, 28</span> (h. text <span dir=\"rtl\">נדיב</span>); a. fr.—<span class=\"citation\">Y. Ber. V, 9ᵃ</span> <span dir=\"rtl\">עבר א׳</span> an elder passed by.—Pl. <span dir=\"rtl\">אַרְכוֹנִין</span>. <span class=\"citation\">Targ. II Chr. XI, 11</span>; a. e.—<span class=\"citation\">Y. Peah VIII, 21ᵃ</span> (defective sentence); [h. pl. <span dir=\"rtl\">אַרְכוֹנוֹת</span>, v. <a href=\"#\" data-headword=\"רְכַן ²\">ארְכָן</a>).</div>","alt":["אַרְכוּנָא"]},"3138":{"h":"אַרְכוֹנְטוֹס","r":"A03138","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἄρχων, -οντος) <i>archont, city-magistrate, prefect</i>. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> top. <span class=\"citation\">Lam. R. to II, 2</span>; <span class=\"citation\">IV, 18</span>. <span class=\"citation\">Gen. R. s. 76</span> <span dir=\"rtl\">ארכוננוס</span> (corr. acc.). [The office of a city mayor or senator in the Roman days was often ruinous to its occupants; v. Sm. Ant. s. v. Senatus.]</div>","alt":["אַרְכוֹנְטָס"]},"3139":{"h":"*אַרְכּוֹף","r":"A03139","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">רכף</span>, cmp. <a href=\"#\" data-headword=\"מַרְכּוֹף\">מַרְכּוֹף</a>) prob. <i>a screwing contrivance for bending wood; engine of torture, stocks</i>. <span class=\"citation\">Esth. R. to I, 1</span>ᵇ; v. <a href=\"#\" data-headword=\"*אוּכַּיְיפָא\">אוּכַּיְיפָא</a>.</div>","alt":[]},"3140":{"h":"אַרְכִי I","r":"A03140","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ארך\">ארך</a>, v. <a href=\"#\" data-headword=\"עַרְכִי\">עַרְכִי</a>; an adaptation of ἀρχή, cmp. <a href=\"#\" data-headword=\"אַרְכָן I\">אַרְכָן</a>) <i>term of office, office, court of elders</i>. <span class=\"citation\">Num. R. s. 9</span> whoever was signed as a witness <span dir=\"rtl\">בא׳ ישנה וכ׳</span> (<span class=\"citation\">Kidd. IV, 5</span> <a href=\"#\" data-headword=\"עַרְכִי\">ערכי</a> q. v.) in the old court of Zepphoris.—<span class=\"citation\">Y. M. Kat. II, end, 81ᵇ</span> <span dir=\"rtl\">מעלה לאַרְכִיָים</span> he (the gentile) takes the deed to their (gentile) office for recording. Y. Gitt. I, 43ᵈ top.—<span class=\"citation\">Ruth R. to I, 3</span> <span dir=\"rtl\">א׳ של בנך דוחקת</span> the time of thy son’s accession to office presses. <span class=\"citation\">Deut. R. s. 2</span> <span dir=\"rtl\">הגיע א׳ וכ׳</span> surrender thy office to Joshua. Ib. a prefect <span dir=\"rtl\">שהיה בא׳ שלו</span> who was in his office; a. fr.—Pl. <a href=\"#\" data-headword=\"אַרְכִיּוֹן\">אַרְכִיּוֹת</a>. Ruth. R. l. c. <span dir=\"rtl\">א׳ א׳ הן</span> the terms of office are predestined (cmp. <span class=\"citation\">Sabb. 30ᵃ</span> bot. <span dir=\"rtl\">ואין מלכות וכ׳</span>). [<a href=\"#\" data-headword=\"עַרְכָאוֹת\">עַרְכָאוֹת</a>, v. <a href=\"#\" data-headword=\"עַרְכִי\">עַרְכִי</a>.]</div>","alt":[]},"3141":{"h":"אַרְכִי II","r":"A03141","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> קִרְיַת א׳ <i>Kiryath Arkhi</i> (= <span dir=\"rtl\">קרית ספר</span>); v. <a href=\"#\" data-headword=\"אַרְכִי I\">preced.</a> <span class=\"citation\">Targ. Josh. XV, 15</span>; a. e.</div>","alt":[]},"3142":{"h":"אַרְכִי III","r":"A03142","html":"<div class=\"sense\"> (Greek pref. ἀρχι—) <i>chief of</i> (gen. followed by a pl.) as <span dir=\"rtl\">א׳ בִּרְיוֹנִים</span> <i>chief of the castle guard</i>. Pesik. Ekha p. 122ᵇ Ar. (ed. <a href=\"#\" data-headword=\"אדני מריונים\">אדני מריונים</a>, corr. acc.); v. respective determinants.</div>","alt":[]},"3143":{"h":"ארכידיקי","r":"A03143","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 50</span> beg., Mus., v. <a href=\"#\" data-headword=\"יודקו\">יודקו</a></div>","alt":[]},"3144":{"h":"אַרְכִיּוֹן","r":"A03144","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀρχεῖον, archivum) <i>prefecture, public building, archive</i>. Tanḥ. Ki Thetsé 9 he went <span dir=\"rtl\">לא׳ של וכ׳</span> into the Egyptian archive; Pesik. Zakh. p. 27ᵃ לבית א׳ Ar. (ed. <a href=\"#\" data-headword=\"אַרְמוֹן I\">ארמון</a>, corr. acc.); Yalk. a. l. <span dir=\"rtl\">ארכוון</span> (some ed. <a href=\"#\" data-headword=\"אַרְמוֹן I\">ארמון</a>, corr. acc.). <span class=\"citation\">Esth. R. to I, 3</span> <span dir=\"rtl\">להדא א׳ דגדר</span> as in the state-house of Gadara. [<span class=\"citation\">Ex. R. s. 5</span> <span dir=\"rtl\">בית ארמון</span> corr. acc.]</div>","alt":[]},"3145":{"h":"אַרְכִיטִיקְטוֹן","r":"A03145","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀρχιτέκτων, architectus) <i>architect, engineer</i>. <span class=\"citation\">Gen. R. s. 24</span>, beg. <span dir=\"rtl\">לא׳ שבנה וכ׳</span> to be compared to an engineer that built the fortifications of a principality; <span class=\"citation\">Num. R. s. 9</span>, beg. <span dir=\"rtl\">לארכי קיטון קטאד׳</span> (corr. acc., and insert <span dir=\"rtl\">שנעשה</span>) to an architect that was appointed &amp;c.; a. fr.—Pl. <span dir=\"rtl\">אַרְכִיטֶקְטוֹנִין</span>, <span dir=\"rtl\">אַרְכִיטֶקְטִין</span>. Y. Ber. IX, 13ᵃ top <span dir=\"rtl\">טקטנן …</span> (corr. acc.).</div>","alt":["אַרְכִיטִיקְטוֹס"]},"3146":{"h":"ארכילוסטקיא","r":"A03146","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְכֹּולַסְטִיקָא\">אִיסְכּוֹלַסְטִיקָא</a></div>","alt":[]},"3147":{"h":"ארכיליסטוטין","r":"A03147","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְכִילֵיסְטֵיס\">next w.</a></div>","alt":["ליסטוסין","אַרְכִילִיסְטִים"]},"3148":{"h":"אַרְכִילֵיסְטֵיס","r":"A03148","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀρχιλήστης) <i>chief robber, leader of a gang</i>. <span class=\"citation\">Gen. R. s. 48</span>; a. fr. [Frequ. <a href=\"#\" data-headword=\"ארכיליסטוטין\">ארכיליסטים</a>, divide in two words, v. <a href=\"#\" data-headword=\"אַרְכִי III\"><span dir=\"rtl\">אַרְכִי</span> III</a>, a. <a href=\"#\" data-headword=\"לִיסְטֵיס\">לֵיסְטֵיס</a>.] [<span class=\"citation\">Yalk. Ex. 255</span> <span dir=\"rtl\">ארכיליסטוסין</span>, <span dir=\"rtl\">טוטין …</span>, read <span dir=\"rtl\">אִיסְכּוֹלַסְטִיקִין</span>.—Midr. Sam. s. 25, end <a href=\"#\" data-headword=\"ארכיליסטוטין\">ארכיליסטים</a> some ed., v. <a href=\"#\" data-headword=\"אָרְכֵיסְטֵיס\">אָרְכֵיסְטֵיס</a>.]</div>","alt":[]},"3149":{"h":"*אַרְכִילִיפּוֹרִין","r":"A03149","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (read in two words, v. <a href=\"#\" data-headword=\"אַרְכִי III\"><span dir=\"rtl\">אַרְכִי</span> III</a>, a. <a href=\"#\" data-headword=\"לוּפָר\">לופר</a>) <i>chief of the body-guard, executioner;</i> cmp. <span dir=\"rtl\">ספיקולטור</span>. Pesik. B’shall. p. 91ᵇ ארכוליפורין Ar. (ed. <span dir=\"rtl\">ארטל ליפרן</span>, Var. <span dir=\"rtl\">ארכן ליפרן</span>, <span dir=\"rtl\">לפילון ארבו</span>, <span dir=\"rtl\">ארבופילון</span>, v. Buber a. l. note; corr. acc.).</div>","alt":[]},"3150":{"h":"אָרְכֵיסְטֵיס","r":"A03150","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὀρχήστης) <i>dancer</i>. <span class=\"citation\">Y. Succ. V, 55ᶜ</span> top; <span class=\"citation\">Y. Snh. II, 20ᵇ</span> bot. <a href=\"#\" data-headword=\"ארכסטס\">ארכסטס</a>; <span class=\"citation\">Num. R. s. 4</span>.—Pl. <span dir=\"rtl\">אָרְכֵיסְטִין</span> or <span dir=\"rtl\">אָרְכֵיסְטֵיסִין</span>. Midr. Sam. s. 25, end <a href=\"#\" data-headword=\"ארכיסטריס\">ארכיסטריס</a>, Var. <a href=\"#\" data-headword=\"אַרְכִילֵיסְטֵיס\">ארכיליסטיס</a> (corr. acc.).</div>","alt":[]},"3151":{"h":"*אַרְכִיסְטְרָאטֵיגוֹס","r":"A03151","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἀρχιστρατηγός) <i>commander in chief;</i> also <i>chief magistrate</i> (v. <a href=\"#\" data-headword=\"אִסְטַרְטֵיגוֹס\">אִסְטְרָטֵיגוֹס</a>). <span class=\"citation\">Gen. R. s. 58</span>; (<span class=\"citation\">Ex. R. s. 31</span> <span dir=\"rtl\">אסטרט׳</span>).</div>","alt":["אַרְכִיסְטְרָטֵיגוֹס"]},"3152":{"h":"ארכיסטריגוס","r":"A03152","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 58</span>, corr. as <a href=\"#\" data-headword=\"*אַרְכִיסְטְרָאטֵיגוֹס\">preced. w.</a></div>","alt":[]},"3153":{"h":"ארכיסטריס","r":"A03153","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָרְכֵיסְטֵיס\">אָרְכֵיסְטֵיס</a></div>","alt":[]},"3154":{"h":"ארכיקיטון","r":"A03154","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אַרְכִיטִיקְטוֹן\">אַרְכִיטֶקְטוֹן</a>.</div>","alt":[]},"3155":{"h":"ארכל","r":"A03155","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְבֵּל I\"><span dir=\"rtl\">אַרְבֵּל</span> I</a></div>","alt":[]},"3156":{"h":"אַרְכָן I","r":"A03156","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ארך\">ארך</a>, an adaptation of ἄρχων) <i>elder, magistrate</i>. <span class=\"citation\">B. Bath. 164ᵇ</span> a letter of divorce dated <span dir=\"rtl\">בשנת פלוני א׳</span> (Var. <span dir=\"rtl\">עַרְכָן</span>, <span dir=\"rtl\">עַרְכָאן</span> v. Rabb. D. S. a. l. note 3 sq.; cmp. <a href=\"#\" data-headword=\"עַרְכִי\">עַרְכִי</a>) in the year when—was magistrate; v. <a href=\"#\" data-headword=\"דוגין\">דּוּגִין</a>.—Pl. <span dir=\"rtl\">אַרְכוֹנוֹת</span>. <span class=\"citation\">Cant. R. to VII, 9</span>. Ch. <a href=\"#\" data-headword=\"אַרְכוֹן\">אַרְכוֹן</a>, <a href=\"#\" data-headword=\"אַרְכוֹן\">אַרְכוֹנָא</a>.</div>","alt":[]},"3157":{"h":"אַרְכָן II","r":"A03157","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָרֵךְ\">אָרֵךְ</a>) <i>one giving long prayers</i>, opp. <a href=\"#\" data-headword=\"קַצְרָן\">קַצְּרָן</a>. <span class=\"citation\">Ber. 34ᵃ</span>; Mekh. B’shall., Vayassa 1 <a href=\"#\" data-headword=\"מָאַרְכָן\">מארכן</a> (read <span dir=\"rtl\">מה א׳</span>).</div>","alt":[]},"3158":{"h":"אַרְכָנוּתָא","r":"A03158","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אַרְכָן I) <i>office</i>. <span class=\"citation\">B. Bath. 164ᵇ</span> (Var. <span dir=\"rtl\">עַרְכָנ׳</span>, v. <a href=\"#\" data-headword=\"אַרְכָן I\"><span dir=\"rtl\">אַרְכָן</span> I</a>).</div>","alt":[]},"3159":{"h":"*אַרְכְּסָא","r":"A03159","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">רכס</span>) <i>thick, well-kneaded</i>. <span class=\"citation\">Men. 43ᵃ</span> <span dir=\"rtl\">חמירא א׳</span> thick leaven of barley flour.</div>","alt":[]},"3160":{"h":"ארכסטס","r":"A03160","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אָרְכֵיסְטֵיס\">אָרְכֵיסְטֵיס</a>.</div>","alt":["ארכסיטס"]},"3161":{"h":"ארכקפאן","r":"A03161","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְטְקָפָא\">אַרְטְקָפָא</a></div>","alt":[]},"3162":{"h":"*אַרְכַת","r":"A03162","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Arkhath, Warka</i>, S. E. of Babylon (v. Schr. KAT p. 94). <span class=\"citation\">Yoma 10ᵃ</span> (expl. <i>Erekh</i>, <span class=\"citation\">Gen. X, 10</span>) <span dir=\"rtl\">זו א׳</span> Ms. M. (ed. <a href=\"#\" data-headword=\"אוריכות\">אוריכות</a>, v. Rabb. D. S. a. l.; Targ. Y. Gen. l. c. <span dir=\"rtl\">הדס</span>; <span class=\"citation\">Gen. R. s. 37</span> <a href=\"#\" data-headword=\"חֹרָן\">חרן</a>; Yalk. 62 <a href=\"#\" data-headword=\"אֲרָם\">ארם</a>).</div>","alt":[]},"3163":{"h":"*אַרְלָא","r":"A03163","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"עָרֵל ²\">עַרְלָא</a>.—Pl. <span dir=\"rtl\">אַרְלִין</span>, <a href=\"#\" data-headword=\"אַכְלָאִין\">אַרְלָאִין</a>. <span class=\"citation\">Targ. Y. II, Gen. XXXIV, 31</span>, some ed.</div>","alt":[]},"3164":{"h":"אֲרָם","r":"A03164","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>Aram</i>, son of Shem., son of Shem. <span class=\"citation\">Targ. Gen. X, 22</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>Aramaea, Syria</i>. <span class=\"citation\">Targ. I Kings XX, 1</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  (a disguise for <a href=\"#\" data-headword=\"רוֹמִי I\">רוֹמָא</a>) <i>Rome, Roman empire</i> (cmp. <a href=\"#\" data-headword=\"אֱדוֹם\">אֱדוֹם</a>). <span class=\"citation\">Pes. 87ᵇ</span> <span dir=\"rtl\">לקבל גזרות אכזריות א׳</span> ed. (read <span dir=\"rtl\">לסבול … של א׳</span>; in Ms. M. 1 only <span dir=\"rtl\">לסבול גזיר׳</span>, Ms. 2 … <span dir=\"rtl\">של רומיים</span>; oth. var., v. Rabb. D. S. a. l. note; <span class=\"citation\">Gitt. 17ᵃ</span> <span dir=\"rtl\">אֲרוֹמִיִּים</span>) to endure the severe decrees of Rome.</div>","alt":[]},"3165":{"h":"אֲרַמָּא","r":"A03165","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"אֲרַמִּי\">אֲרַמִּי</a>) <i>Syrian</i>. <span class=\"citation\">Targ. Gen. XXV, 20</span>; a. e.—<span class=\"citation\">B. Kam. 59ᵃ</span> דיקלא א׳ Ms. (ed. <span dir=\"rtl\">דא׳</span> corr. acc.) Syrian palm-tree.—Fem. <span dir=\"rtl\">אֲרַמִּיתָא</span>. <span class=\"citation\">Targ. I Chr. VII, 14</span> (ed. Rahm. <a href=\"#\" data-headword=\"אָרָמוּתָא\">ארמותא</a>).—Pl. m. <a href=\"#\" data-headword=\"אַרְמַאי\">אֲרַמָּאֵי</a>. <span class=\"citation\">Targ. II Chr. XXII, 5</span>; f. <a href=\"#\" data-headword=\"אֲרַמְיוּתָא\">אֲרַמְיָאתָא</a>. <span class=\"citation\">Sabb. 29ᵃ</span> Syrian (dates).—Cmp. <a href=\"#\" data-headword=\"אַרְמַאי\">אַרְמַאי</a>.</div>","alt":["אֲרַמָּאָה"]},"3166":{"h":"אֲרָמָא","r":"A03166","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"אָרָמוּתָא\">אָרָמוּתָא</a> 2). <span class=\"citation\">Targ. Ex. XXIX, 24</span>; a. e.</div>","alt":["אָרָמָא"]},"3167":{"h":"אֲרַמָּאָה","r":"A03167","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲרַמָּא\">אֲרַמָּא</a></div>","alt":[]},"3168":{"h":"אַרְמָאָה","r":"A03168","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְמַאי\">next w.</a></div>","alt":[]},"3169":{"h":"אַרְמַאי","r":"A03169","html":"<div class=\"sense\"> ch. m. (= b. h. <a href=\"#\" data-headword=\"אֲרַמִּי\">אֲרַמִּי</a>) <i>Syrian</i>, in gen. <i>gentile, Roman;</i> cmp. <a href=\"#\" data-headword=\"אֲרַמִּי\">אֲרַמִּי</a> 2). <span class=\"citation\">Targ. O. Lev. XXV, 47</span>.—<span class=\"citation\">Y. Shebi. IV, 35ᵃ</span>; 35ᵇ <span dir=\"rtl\">חד א׳ ברומי</span> (<span class=\"citation\">Y. Snh. III, 21ᵇ</span> <span dir=\"rtl\">חד בר נש</span>) a gentile in Rome. Ib. <span dir=\"rtl\">או יהודיי וכ׳</span> (prob. plur.) either be Jewish Jews (living as Jews ought to) or gentile gentiles (Roman Romans). Y. Ab. Zar. III, 41ᶜ top <span dir=\"rtl\">ארמייא וכ׳</span> the leather bottle of an Aramæan (or gentile) burst open. <span class=\"citation\">Yeb. 45ᵇ</span> <span dir=\"rtl\">בר ארמאה</span> son of a gentile. <span class=\"citation\">Ḥull. 97ᵃ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"אַרְמַאי\">אַרְמָאֵי</a>. <span class=\"citation\">Targ. Y. Deut. XXXII, 24</span> (<i>Romans</i>); a. e.—<span class=\"citation\">Ab. Zar. 31ᵇ</span>.—<span class=\"citation\">Gitt. 17ᵃ</span> <span dir=\"rtl\">אֲרוֹמָאֵי</span> (<i>Romans</i>). <span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">אַרְמָאִין</span>. <span class=\"citation\">Koh. R. to VII, 11</span> <span dir=\"rtl\">אַרְמָיִין</span>.—<span class=\"citation\">Num. R. s. 7</span> <span dir=\"rtl\">אַרְמָאִים</span> (<span class=\"citation\">Kel. I, 8</span> <a href=\"#\" data-headword=\"עכ\">עכ&quot;ום</a>); a. fr. [<span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">אתון מארמאין</span>, read <span dir=\"rtl\">מיזדמאין</span>, v. <a href=\"#\" data-headword=\"זְמֵי I\">זְמֵי</a>.]—Fem. <span dir=\"rtl\">אַרְמַיְיתָא</span>. Yeb. l. c. V. <a href=\"#\" data-headword=\"אֲרַמָּא\">אֲרַמָּא</a>.</div>","alt":["אַרְמַי","אַרְמָיָיא","אַרְמָאָה","אֲרוֹמָאָה"]},"3170":{"h":"אַרְמוֹן I","r":"A03170","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>enclosure, palace</i> (poëtic). <span class=\"citation\">Ab. Zar. 24ᵇ</span> praised <span dir=\"rtl\">בדביר א׳</span> in the innermost of the Palace (Temple). [<span class=\"citation\">Ex. R. s. 5</span> <a href=\"#\" data-headword=\"אֶבֶן\">בית א׳</a>; Pesik. Zakh. p. 27ᵃ, v. <a href=\"#\" data-headword=\"אַרְכִיּוֹן\">אַרְכִיּוֹן</a>.] Cmp. <a href=\"#\" data-headword=\"אֲרָם\">ארם</a> Schr. KAT p. 536.</div>","alt":[]},"3171":{"h":"*אַרְמוֹן II","r":"A03171","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Armon</i>. <span class=\"citation\">Yeb. 45ᵃ</span> captives coming from A. (v. Neub. Géogr. p. 371; prob. ident. with <a href=\"#\" data-headword=\"רִמּוֹן\">רִמּוֹן</a>, q. v.).</div>","alt":[]},"3172":{"h":"אַרְמוֹן III","r":"A03172","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"עַרְמוֹן\">עַרְמוֹן</a>) <i>platanus, the oriental plane</i>. <span dir=\"rtl\">אַרְמוֹנִים</span>. <span class=\"citation\">Gen. R. s. 15</span>, beg.; (<span class=\"citation\">R. Hash. 23ᵃ</span>; <span class=\"citation\">B. Bath. 81ᵃ</span> <a href=\"#\" data-headword=\"עֵירוּבָא\">עַרְ׳</a>).</div>","alt":[]},"3173":{"h":"אָרָמוּתָא","r":"A03173","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רום</span>) </div><div class=\"sense\"><b>1)</b> <i>raising, rising</i>. <span class=\"citation\">Targ. Is. XIX, 16</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>waving, heave-offering</i>. <span class=\"citation\">Targ. O. Ex. XXIX, 27</span>; a. e.—Pl. <a href=\"#\" data-headword=\"אָרָמוּתָא\">אֲרַמְוָתָא</a>, const. <span dir=\"rtl\">אֲרַמְוָת</span>. <span class=\"citation\">Targ. O. Num. XVIII, 11</span> (Var. <span dir=\"rtl\">אֲרָמוּת</span> sing.).</div>","alt":["אֲרָ׳"]},"3174":{"h":"אֲרַמִּי","r":"A03174","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <span dir=\"rtl\">אֲרָמִית</span> f. </div><div class=\"sense\"><b>1)</b>  (b. h.) <i>Aramaean, Aramaic, Chaldaic</i>. [<span class=\"citation\">Targ. II Kings XVIII, 26</span>.]—לשון א׳ <i>Chaldaic</i>. <span class=\"citation\">Sabb. 12ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (= <a href=\"#\" data-headword=\"אֲרוֹמִי\">אֲרוֹמִי</a>; v. <a href=\"#\" data-headword=\"אֲרָם\">אֲרָם</a></div><div class=\"sense\"><b>3)</b> <i>Romish, Roman, heathen</i>. [Owing to Christian censors as well as timid Jewish copyists, many of the passages originally referring to Romans, Christians, &amp;c., have been altered by substituting <i>Arammi, Kuthi, Goy</i> &amp;c., so that only by keen criticism their real application can be ascertained.]—Fem. <i>gentile woman</i>. <span class=\"citation\">Ber. 8ᵇ</span> (Ms. M. <span dir=\"rtl\">ארמאית</span>). <span class=\"citation\">Snh. IX, 6</span>; a. fr.—<span class=\"citation\">Y. Meg. I, 71ᶜ</span> top <span dir=\"rtl\">ארמית</span> <i>Latin;</i> v. <a href=\"#\" data-headword=\"בָּדָא\">בָּדָא</a>.—Pl. <a href=\"#\" data-headword=\"אֲרַמִּי\">אֲרַמִּים</a> <span class=\"citation\">Meg. 11ᵃ</span> (some ed. <span dir=\"rtl\">פרסיים</span>; Ms. M. <span dir=\"rtl\">רוֹמִיִּים</span>; Sifra B’ḥukk. <span class=\"citation\">Par. II</span>, ch. 8 <span dir=\"rtl\">אספסיינוס</span>). V. <a href=\"#\" data-headword=\"אֲרוֹמִי\">אֲרוֹמִי</a>.</div>","alt":[]},"3175":{"h":"אֲרַמְיוּתָא","r":"A03175","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרַמִּי\">preced.</a>) <i>gentile ways, Romedom, idolatry</i>, &amp;c. <span class=\"citation\">Meg. I</span>II (IV), 9 (25ᵃ) whoever translates (<span class=\"citation\">Lev. XVIII, 21</span>), ‘Of thy seed thou shalt give none <span dir=\"rtl\">לאעברא בא׳</span> (Ms. Lond. <span dir=\"rtl\">לאעבורי אומיתא</span>, v. Var. in Rabb. D. S. a. l. note) to become with child in Romedom (identifying Molokh with Rome and misinterpreting <i>l’haăbir</i> for the purpose of making it applicable to sexual connection with Romans) must be silenced with a sharp rebuke (v. <a href=\"#\" data-headword=\"נְזִיפָה\">נְזִיפָה</a>); cmp. Targ. Y. Lev. l. c.—<span class=\"citation\">Ab. Zar. 70ᵃ</span> <span dir=\"rtl\">כד הוינן בארמיותן</span> (Ms. M. <span dir=\"rtl\">הואי בגיותא</span>) when we were yet in our heathendom (prior to our conversion).</div>","alt":[]},"3176":{"h":"אַרְמַי","r":"A03176","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְמַאי\">אַרְמַאי</a></div>","alt":["אַרְמָיָיא"]},"3177":{"h":"*אַרְמִילוֹס","r":"A03177","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (a disguise of Romulus, Ῥώμυλος = Rome) <i>Armilus</i>, a mythical personage, representative of wickedness, answering to the Christian Antichrist. <span class=\"citation\">Targ. Is. XI, 4</span> א׳ רשיעא A. the wicked. <span class=\"citation\">Targ. Y. Deut. XXXIV, 3</span> <a href=\"#\" data-headword=\"ארמלגוס\">ארמלגוס</a> (corr. acc.); cmp. <a href=\"#\" data-headword=\"אַרְמַנִּיאָה\">אַרְמַנִּיאָה</a>. [V. Book of Zerub.; Saadia Emunoth VIII, 2; Graetz Gesch. d. <span class=\"citation\">Jud. V</span>, p. 496.]</div>","alt":[]},"3178":{"h":"אַרְמִינְיָא","r":"A03178","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Armenia</i>, the plateau of Western Asia. <span class=\"citation\">Lam. R. to I, 14</span>.—<span class=\"citation\">Targ. Y. Gen. VIII, 4</span> name of a mountain and of a city.</div>","alt":[]},"3179":{"h":"אִרְמֵל","r":"A03179","html":"<div class=\"sense\"> (denomin. of <a href=\"#\" data-headword=\"אַרְמְלָא\">next w.</a>) <i>Nithpa</i>. <span dir=\"rtl\">נִתְאַרְמְלָה</span> <i>to become a widow</i> (a Chaldaism). <span class=\"citation\">Keth. II, 1</span>; <span class=\"citation\">V, 1</span>; v. <a href=\"#\" data-headword=\"אִלְמֵן\">אִלְמֵן</a>. <span class=\"citation\">Yeb. 42ᵇ</span>; a. e.</div>","alt":[]},"3180":{"h":"אַרְמְלָא","r":"A03180","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">אלמל׳</span> fr. <span dir=\"rtl\">עלם</span>; v. <a href=\"#\" data-headword=\"אַלְמוֹן I\">אַלְמוֹן</a>; v. P.; v. P. S. s. v. 391) <i>widow</i>. <span class=\"citation\">Targ. Gen. XXXVIII, 11</span>; a. fr.—Y. Sabb. I, 3ᵈ top; a. fr.—Pl. <a href=\"#\" data-headword=\"אַרְמְלָא\">אַרְמְלָן</a>. <span class=\"citation\">Targ. Ex. XXII, 23</span>, a. e.—Y. Keth. I, beg. 24ᵈ.—<a href=\"#\" data-headword=\"אַרְמְלוּ\">אַרְמְלָאתָא</a>, <a href=\"#\" data-headword=\"אַרְמְלוּ\">אַרְמְלָתָא</a>. <span class=\"citation\">Targ. Job XXII, 9</span>; a. e.—Y. Meg. III, 74ᵃ top; a. e.</div>","alt":["אַרְמְלָה","אַרְמַלְתָּא"]},"3181":{"h":"ארמלגוס","r":"A03181","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַרְמִילוֹס\">אַרְמִילוֹס</a></div>","alt":[]},"3182":{"h":"אַרְמְלוּ","r":"A03182","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַרְמְלָא\">ארְמְלָא</a>) (<i>in</i>) <i>widowhood</i>. <span class=\"citation\">Targ. Is. XLVII, 8</span> sq.; a. e.—<span class=\"citation\">Keth. 75ᵃ</span>, v. <a href=\"#\" data-headword=\"טַנְדּוּ\">טַנְדּוּ</a>.—Y. Ned. V, 39ᵇ top; <span class=\"citation\">B. Bath. 98ᵇ</span> Ms.; ed. <a href=\"#\" data-headword=\"אַלְמָנוּת\">אַלְמָנוּת</a>.</div>","alt":["אַרְמְלוּת","אַרְמְלוּתָא"]},"3183":{"h":"אַרְמַלְתָּא","r":"A03183","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְמְלָא\">אַרְמְלָא</a></div>","alt":[]},"3184":{"h":"אַרְמֹן","r":"A03184","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְמוֹן I\">אַרְמוֹן</a></div>","alt":[]},"3185":{"h":"אַרְמַנְיָא","r":"A03185","html":"<div class=\"sense\"><b>1)</b>  v. <a href=\"#\" data-headword=\"אַרְמִינְיָא\">אַרְמִינְיָא</a>.—[</div><div class=\"sense\"><b>2)</b>  <span class=\"citation\">Targ. Job I, 1</span> Naḥmanid. in comment., Ms. <a href=\"#\" data-headword=\"קוּשְׁטַנְטִינָא\">קושטנטינא</a>, ed. <a href=\"#\" data-headword=\"עוּץ\">עוץ</a>, v. next w.]</div>","alt":[]},"3186":{"h":"אַרְמַנִּיאָה","r":"A03186","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Armannia</i> (Romania, New-Rome, Constantinople). <span class=\"citation\">Targ. Lam. IV, 21</span> Var. (h. text <a href=\"#\" data-headword=\"עוּץ\">עוץ</a>).—Deriv. pl. <a href=\"#\" data-headword=\"אַרְמַנְיָיאֵי\">אַרְמַנְיָיאֵי</a>. <span class=\"citation\">Targ. I Chr. I, 17</span> ed. Beck. (ed. Rahm. <span dir=\"rtl\">ארמצ׳</span> corr. acc.).</div>","alt":[]},"3187":{"h":"אַרְמַנְיוֹס","r":"A03187","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (represent. a tribe; v. <a href=\"#\" data-headword=\"אַרְמַנִּיאָה\">preced.</a>) <i>Armanius</i>. <span class=\"citation\">Targ. I Chr. I, 42</span> (h. text <a href=\"#\" data-headword=\"עוּץ\">עוץ</a>).</div>","alt":[]},"3188":{"h":"אַרְמְנָיָיא","r":"A03188","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Armenian</i> (?). Y. Gitt. VI, 48ᵈ bot. <span dir=\"rtl\">ר׳ יעקב א׳</span>; <span class=\"citation\">Y. M. Kat. III, 82ᶜ</span> top <span dir=\"rtl\">ר׳ א׳</span> (insert <a href=\"#\" data-headword=\"יַעֲקֹב\">יעקב</a>).</div>","alt":[]},"3189":{"h":"אַרְמַנְיָיאֵי","r":"A03189","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְמַנִּיאָה\">אַרְמַנִּיאָה</a></div>","alt":["ארמצייאי"]},"3190":{"h":"אָרֹן","r":"A03190","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָרוֹן\">אָרוֹן</a></div>","alt":[]},"3191":{"h":"אֹרֶן","r":"A03191","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>pine</i> (Assyr. <span dir=\"rtl\">ארן</span> <i>cedar</i>, Schr. KAT p. 411).—Pl. <span dir=\"rtl\">אֳרָנִים</span>. <span class=\"citation\">Par. III, 8</span> (R. Hai Gaon <span dir=\"rtl\">ארנן</span>). <span class=\"citation\">R. Hash. 23ᵃ</span> <a href=\"#\" data-headword=\"אֲרוֹנִים\">אֲרוֹנִים</a> (Var. <a href=\"#\" data-headword=\"עֲרוֹנִים\">עֲרוֹנִים</a>). <span class=\"citation\">B. Bath. 81ᵃ</span> <a href=\"#\" data-headword=\"ע׳\">ע׳</a>.</div>","alt":[]},"3192":{"h":"אַרְנָא","r":"A03192","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אָרוֹן\">אָרוֹן</a>) <i>chest</i>. <span class=\"citation\">Sabb. 32ᵃ</span> <span dir=\"rtl\">שקורין לא&quot;הק א׳</span> who call the holy ark, ‘the chest’.</div>","alt":[]},"3193":{"h":"אַרְנָב","r":"A03193","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"אַרְנֶבֶת\">אַרְנֶבֶת</a> q. v.</div>","alt":[]},"3194":{"h":"אַרְנְבָא","r":"A03194","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַרְנַבְתָּא\">אַרְנַבְתָּא</a></div>","alt":[]},"3195":{"h":"אַרְנֶבֶת","r":"A03195","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>hare;</i> [pr. n. f., v. next w.]. <span class=\"citation\">Meg. 9ᵇ</span>. <span class=\"citation\">Lev. s. 13</span> הא׳ זו יון <i>Arnebeth</i> (<span class=\"citation\">Lev. XI, 6</span>) is an allusion to Yavan (Greece); cmp. next w.—Pl. <span dir=\"rtl\">אַרְנָבִים</span>. <span class=\"citation\">Sabb. 27ᵃ</span>; <span class=\"citation\">Men. 39ᵇ</span>. [Assyr. Annabu, Schr. KAT p. 498.]</div>","alt":[]},"3196":{"h":"אַרְנַבְתָּא","r":"A03196","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. XI, 6</span>; a. e.—<span class=\"citation\">Lam. R. to II, 10</span>; <span class=\"citation\">Ned. 65ᵃ</span> <span dir=\"rtl\">ארנבא</span>.—<span class=\"citation\">Y. Meg. I, 71ᵈ</span> bot. <span dir=\"rtl\">אמו של תלמי … ארנתא וכ׳</span> (corr. acc.) King Ptolemee’s mother was named <i>Hare</i> (λαγώς); cmp. <span class=\"citation\">Meg. 9ᵇ</span> where the King’s wife is named <i>arnebeth</i></div>","alt":["אַרְנְבָא"]},"3197":{"h":"ארנון","r":"A03197","html":"<div class=\"sense\">, Tanḥ. B’midb. 18, read <span dir=\"rtl\">אָקְטוֹ</span>, v. <a href=\"#\" data-headword=\"אָכְטָא\">אָכְטָא</a></div>","alt":[]},"3198":{"h":"*אַרְנוֹן I","r":"A03198","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (deriv. of <a href=\"#\" data-headword=\"אָרוֹן\">אָרוֹן</a>) <i>chest with many cases, trader’s chest</i>. Tanḥ. B’midb. 20 לאדם פרגמטיוטיס שהיה לו א׳ של זכוכית Ar. (ed. incorr.) like a trader that had a chest containing (common) glass beads; cmp. Tanḥ. ed. Bub. 23ᵃ. note; <span class=\"citation\">Yalk. Num. 692</span> (where <span dir=\"rtl\">אבנים</span> must be read <a href=\"#\" data-headword=\"ארנון\">ארנון</a>).</div>","alt":[]},"3199":{"h":"אַרְנוֹן II","r":"A03199","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (an adaptation of <i>annona</i>, cmp. <a href=\"#\" data-headword=\"אַנֹּונָא\">אַנּוֹנָא</a> a. <a href=\"#\" data-headword=\"טַסְקָא\">טַסְקָא</a>) [<i>chest, treasury</i>, v. preced.] <i>tax from crops and other farmer’s produces delivered in kind</i>. Y. Keth. XIII, 35ᵈ <span dir=\"rtl\">א׳ גולגולת</span> annona and poll-tax.—<span class=\"citation\">Pes. 6ᵃ</span> <span dir=\"rtl\">בהמת א׳</span> cattle subject to the annona (v. D. C. ed. Hensch, s. v. Annona: ‘capitur etiam in pecudibus’); <span dir=\"rtl\">עיסת א׳</span> dough made of flour subject to annona.—Pl. <span dir=\"rtl\">אַרְנוֹנוֹת</span>, <span dir=\"rtl\">אַרְנוֹנִיּוֹת</span>, <span dir=\"rtl\">אַרְנוֹנִין</span>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 36</span>. <span class=\"citation\">Lev. R. s. 29</span>. Y. Shebi. IV, 35ᵇ; a. fr.—<span class=\"citation\">Y. Snh. III, 21ᵇ</span> top <span dir=\"rtl\">מיגבי ארנונין</span> to collect taxes Pesik. Shek. 11ᵇ (description of Roman extortions) <span dir=\"rtl\">אייתי ארנונֵיךְ</span> bring thy <i>annonae</i></div>","alt":["אַרְנוֹנָא","אַרְנוֹנָה"]}};
